import type { CultureArticle } from "../types";

const items: CultureArticle[] = [{"id":"tra-038","version":2,"slug":"the-rostigraben-switzerland-s-border-in-the-head","contentType":"note","category":"cultural-change","title":{"ar":"روستيغرابن: حدود في العقل السويسري","de":"Der Röstigraben: eine Grenze im Kopf","en":"The Röstigraben: Switzerland's border in the head"},"deck":{"ar":"كيف يعيش السويسريون مع انقسام ثقافي وسياسي بين الناطقين بالألمانية والفرنسية، دون خط على الأرض.","de":"Wie die Schweiz mit einer kulturellen und politischen Kluft zwischen Deutsch- und Westschweiz lebt, ohne Linie auf dem Boden.","en":"How Swiss people live with a cultural and political divide between German- and French-speaking regions, without a line on the ground."},"teaser":{"ar":"يُظهر تصويت الأحد خريطة بلونين، فيسمّي المعلّقون روستيغرابن. لكن هل هذا الانقسام حقيقي أم مجرد ظاهرة إحصائية؟","de":"Nach einer Sonntagsabstimmung zeigt die Nachrichtensendung eine Karte in zwei Farben, und Kommentatoren nennen sofort den Röstigraben. Doch was steckt dahinter?","en":"After a Sunday vote, a news programme shows a map in two colours, and commentators immediately name the Röstigraben. But what does it really mean?"},"readingMinutes":1,"sections":{"ar":[{"heading":"ما هو روستيغرابن؟","paragraphs":["روستيغرابن، أو «خندق الروستي»، هو الاسم غير الرسمي للانقسام الثقافي والسياسي بين سويسرا الناطقة بالألمانية والفرنسية، سُمّي على اسم طبق البطاطس. أصبح المصطلح شائعًا في القرن العشرين، وغالبًا ما توضحه نتائج الاستفتاءات التي يصوّت فيها الغرب الفرنسي بشكل مختلف عن الوسط والشرق الألماني.","الاستفتاء عام 1992 حول الانضمام إلى المنطقة الاقتصادية الأوروبية هو المثال الكلاسيكي: صوّتت الكانتونات الفرنسية بـ«نعم»، والألمانية بـ«لا»، وفشل الاقتراح بفارق ضئيل. يختلف هذا الانقسام بين الأجيال والمناطق، إذ يميل الشباب في المدن إلى تشابه أكبر في التصويت."]},{"heading":"رمز لا حدود","paragraphs":["لا يوجد خط على الأرض: الانقسام إحصائي وثقافي، تلطفه الرحلات اليومية والثنائية اللغوية والمؤسسات الفيدرالية المشتركة، وتشكل تيسينو الناطقة بالإيطالية محورًا آخر. الروستي نفسه كعكة بطاطس مبشورة ترتبط بسويسرا الألمانية، لكنها تؤكل في جميع أنحاء البلاد، لذا فالطبق رمز وليس علامة حدود حقيقية."]}],"de":[{"heading":"Was ist der Röstigraben?","paragraphs":["Röstigraben ist der informelle Name für die kulturelle und politische Kluft zwischen der deutschsprachigen und der französischsprachigen Schweiz, benannt nach dem Kartoffelgericht. Der Begriff wurde im 20. Jahrhundert gebräuchlich und wird oft durch Abstimmungsergebnisse veranschaulicht, bei denen der französischsprachige Westen anders abstimmte als die deutschsprachige Mitte und Ost.","Die Abstimmung von 1992 über den Beitritt zum Europäischen Wirtschaftsraum ist das klassische Beispiel: Die französischsprachigen Kantone stimmten Ja, die deutschsprachigen Nein, und die Vorlage scheiterte knapp. Diese Kluft variiert je nach Region und Generation, wobei jüngere Stadtbewohner oft ähnlicher abstimmen."]},{"heading":"Symbol statt Grenze","paragraphs":["Es gibt keine Linie auf dem Boden: Die Kluft ist statistisch und kulturell, gemildert durch Pendelverkehr, Zweisprachigkeit und gemeinsame föderale Institutionen, und das italienischsprachige Tessin bildet eine weitere Achse. Rösti selbst ist ein Kartoffelgericht, das mit der Deutschschweiz verbunden ist, aber im ganzen Land gegessen wird, also ein Symbol und kein echter Grenzmarker."]}],"en":[{"heading":"What is the Röstigraben?","paragraphs":["Röstigraben, 'rösti ditch', is the informal name for the cultural and political divide between German-speaking and French-speaking Switzerland, named after the potato dish. The term became common in the twentieth century and is often illustrated by referendum results in which the French-speaking west voted differently from the German-speaking centre and east.","The 1992 referendum on joining the European Economic Area is the classic example: French-speaking cantons voted yes, German-speaking ones no, and the proposal failed narrowly. This divide varies by region and generation, with younger urban voters often leaning toward similar outcomes."]},{"heading":"A symbol, not a boundary","paragraphs":["There is no line on the ground: the divide is statistical and cultural, softened by commuting, bilingualism and shared federal institutions, and Italian-speaking Ticino forms another axis. Rösti itself is a grated potato cake associated with German-speaking Switzerland, though it is eaten across the country, so the dish is a symbol rather than a real boundary marker."]}]},"context":{"countries":["CH"],"region":"Switzerland","continent":"europe","languages":["de","fr","it"],"period":"contemporary"},"tags":["cultural-change","Switzerland"],"sources":[{"organization":"Wikipedia","title":{"ar":"Röstigraben","de":"Röstigraben","en":"Röstigraben"},"url":"https://en.wikipedia.org/wiki/R%C3%B6stigraben","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Switzerland","de":"Culture of Switzerland","en":"Culture of Switzerland"},"url":"https://en.wikipedia.org/wiki/Culture_of_Switzerland","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يعرض برنامج إخباري خريطة بعد تصويت يوم الأحد: الغرب بلون والوسط والشرق بلون آخر، ويسمّي المعلّقون على الفور روستيغرابن.","de":"Eine Nachrichtensendung zeigt nach einer Sonntagsabstimmung eine Karte: Der Westen in einer Farbe, die Mitte und der Osten in einer anderen, und Kommentatoren nennen sofort den Röstigraben.","en":"A news programme shows a map after a Sunday vote: the west is one colour and the centre-east another, and commentators immediately name the Röstigraben."},"misunderstanding":{"ar":"روستيغرابن استعارة تحليلية، وليس وصفًا لكل شخص، وقد تضاءل على многих قضايا.","de":"Der Röstigraben ist eine analytische Metapher, keine Beschreibung jeder Person, und er hat sich in vielen Fragen verringert.","en":"The Röstigraben is an analytical metaphor, not a description of every person, and it has narrowed on many issues."},"comparison":{"ar":"في حين أن الانقسام اللغوي في بلجيكا حاد أحيانًا، يظل روستيغرابن في سويسرا أداة تحليلية أكثر منه حدودًا يومية.","de":"Während der Sprachkonflikt in Belgien manchmal scharf ist, bleibt der Röstigraben in der Schweiz eher ein Analysewerkzeug als eine Alltagsgrenze.","en":"While the language divide in Belgium can be sharp, the Röstigraben in Switzerland remains more an analytical tool than an everyday border."}},{"id":"tra-039","version":2,"slug":"sinterklaas-and-the-changing-face-of-zwarte-piet","contentType":"note","category":"cultural-change","title":{"ar":"سانتركلاس والوجه المتغير لزوارته بييت","de":"Sinterklaas und der Wandel des Zwarte Piet","en":"Sinterklaas and the changing face of Zwarte Piet"},"deck":{"ar":"تقليد هولندي عريق يجد نفسه في قلب جدل اجتماعي حول الهوية والتمثيل.","de":"Ein niederländisches Fest im Spannungsfeld von Tradition, Identität und gesellschaftlicher Debatte.","en":"A Dutch tradition navigates identity and representation amid public debate."},"teaser":{"ar":"كيف يتغير تقليد سانتركلاس في هولندا تحت ضغط النقاش العام حول شخصية بييت؟","de":"Wie verändert sich das Sinterklaasfest in den Niederlanden durch die Diskussion um die Figur des Piet?","en":"How is the Sinterklaas celebration in the Netherlands shifting under the spotlight of the Piet debate?"},"readingMinutes":1,"sections":{"ar":[{"heading":"احتفال عائلي بجذور بعيدة","paragraphs":["يُحتفل بسانتركلاس في هولندا في الخامس من ديسمبر، وهو ما يُعرف بـ«باكيسافوند» (أمسية الهدايا). يصل شخصية تشبه الأسقف من إسبانيا بالقارب البخاري في منتصف نوفمبر، ويجوب المدن برفقة مساعديه. يضع الأطفال أحذيتهم خارج الباب مع جزرة للحصان، ويحصلون على هدايا صغيرة. أما الهدايا الكبرى فتُلف غالباً كـ«مفاجآت» مصحوبة بقصائد فكاهية موقعة باسم سانتركلاس."]},{"heading":"زوارته بييت: من الشخصية الكاريكاتورية إلى الجدل","paragraphs":["كان مساعد سانتركلاس، زوارته بييت، يُؤدى تاريخياً بوضع مساحيق سوداء على الوجه وشعر مستعار مجعد وشفاه حمراء، وهو تصوير أصبح محور صراع عام. منذ العقد الثاني من القرن الحادي والعشرين، تحولت العديد من المدارس وهيئات البث والبلديات إلى «روتفيك بييت» (بييت ببقع السخام)، واستخدم البث الوطني لعام 2019 هذا الشكل فقط.","هذا النقاش مثال حي على تقليد يتغير تحت الضغط الاجتماعي، حيث يختلف المدافعون عن الشخصية القديمة والمعارضون، بمن فيهم العديد من المواطنين الهولنديين السود، حول التاريخ والعنصرية. وتختلف الممارسة الآن حسب المدينة والمدرسة وهيئة البث، ويحمل الهولنديون آراء متباينة، إذ يختلف الأمر أيضاً بين الأجيال والمناطق."]}],"de":[{"heading":"Ein Familienfest mit langer Tradition","paragraphs":["Sinterklaas wird in den Niederlanden am 5. Dezember gefeiert, dem sogenannten Pakjesavond. Mitte November kommt eine bischofsähnliche Figur mit dem Dampfschiff aus Spanien an und zieht mit ihren Helfern durch die Städte. Kinder stellen ihre Schuhe mit einer Karotte für das Pferd vor die Tür und erhalten kleine Geschenke. Die Hauptgeschenke werden oft als „Überraschungen“ verpackt, begleitet von Scherzgedichten, die von Sinterklaas unterzeichnet sind."]},{"heading":"Zwarte Piet: Von der Karikatur zum Streitfall","paragraphs":["Der Helfer Zwarte Piet wurde historisch mit Blackface, lockigen Perücken und roten Lippen dargestellt – eine Darstellung, die zum Zentrum eines öffentlichen Konflikts geworden ist. Seit den 2010er Jahren sind viele Schulen, Rundfunkanstalten und Gemeinden zur Figur des Roetveegpiet übergegangen, einer Version mit Rußflecken. Die nationale Fernsehübertragung von 2019 verwendete nur noch diese Form.","Die Debatte ist ein lebendiges Beispiel für eine Tradition, die sich unter gesellschaftlichem Druck verändert. Befürworter der alten Figur und Gegner, darunter viele schwarze Niederländer, sind sich über Geschichte und Rassismus uneinig. Die Praxis variiert heute je nach Stadt, Schule und Sender, und die Niederländer vertreten sehr unterschiedliche Ansichten – auch zwischen den Generationen und Regionen gibt es Unterschiede."]}],"en":[{"heading":"A family celebration with deep roots","paragraphs":["Sinterklaas is celebrated in the Netherlands on 5 December, known as pakjesavond. A bishop-like figure arrives from Spain by steamboat in mid-November and rides through towns with his helpers. Children put their shoes out with a carrot for the horse and receive small gifts; the main presents are often wrapped as surprises with accompanying joke poems signed by Sinterklaas."]},{"heading":"Zwarte Piet: from caricature to controversy","paragraphs":["The helper Zwarte Piet was historically performed with blackface, curly wigs and red lips, a depiction that has become the centre of a public conflict. Since the 2010s many schools, broadcasters and municipalities have switched to Roetveegpiet, a soot-smudge version, and the 2019 national entry broadcast used only that form.","The debate is a live case of a tradition changing under social pressure, with defenders of the old figure and opponents, including many Black Dutch citizens, disagreeing about history and racism. Practice now varies by city, school and broadcaster, and Dutch people hold widely different views, so the topic should not be reduced to a single national position—regional and generational differences matter too."]}]},"context":{"countries":["NL"],"region":"Netherlands","continent":"europe","languages":["nl"],"period":"contemporary"},"tags":["cultural-change","Netherlands"],"sources":[{"organization":"Wikipedia","title":{"ar":"Sinterklaas","de":"Sinterklaas","en":"Sinterklaas"},"url":"https://en.wikipedia.org/wiki/Sinterklaas","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Zwarte Piet","de":"Zwarte Piet","en":"Zwarte Piet"},"url":"https://en.wikipedia.org/wiki/Zwarte_Piet","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مدرسة ابتدائية في أوترخت، يردد الأطفال أغاني الترحيب بينما يوزع بييت ذو الوجه الملوث بالسخام حلوى الببرنوتن، بينما يناقش الآباء في ساحة المدرسة اختيار المدرسة للزي.","de":"In einer Grundschule in Utrecht singen Kinder Willkommenslieder, während ein rußgesichtiger Piet Pepernoten verteilt. Auf dem Schulhof diskutieren Eltern über die Kostümwahl der Schule.","en":"At a primary school in Utrecht, children sing welcome songs as a soot-faced Piet hands out pepernoten, while parents in the playground discuss the school's choice of costume."},"misunderstanding":{"ar":"الاعتقاد بأن جميع الهولنديين يؤيدون الشكل القديم لزوارته بييت أو يعارضونه بالإجماع.","de":"Die Annahme, alle Niederländer seien entweder geschlossen für die alte Zwarte-Piet-Figur oder dagegen.","en":"Assuming all Dutch people either support the old Zwarte Piet figure or oppose it unanimously."},"comparison":{"ar":"يشبه هذا النقاش جدلاً حول تغيير رموز تقليدية في بلدان أخرى، حيث تصطدم العادة بالوعي الاجتماعي الجديد.","de":"Ähnliche Debatten über die Neubewertung traditioneller Symbole gibt es auch in anderen Ländern, wo Gewohnheiten auf ein neues gesellschaftliches Bewusstsein treffen.","en":"Similar debates about re-evaluating traditional symbols occur in other countries, where custom meets new social awareness."}},{"id":"tra-040","version":2,"slug":"the-sunday-roast-a-meal-that-kept-the-week-in-order","contentType":"scene","category":"food-and-hospitality","title":{"ar":"غداء الأحد: وجبة تُبقي الأسبوع في نظامه","de":"Der Sunday Roast: Eine Mahlzeit, die die Woche ordnet","en":"The Sunday roast that kept the week in order"},"deck":{"ar":"في بريطانيا، تجتمع العائلات يوم الأحد حول لحم مشوي وبطاطس ومرق، في طقسٍ يتجاوز الطعام إلى تنظيم الوقت والعلاقات.","de":"In Großbritannien kommen Familien am Sonntag zu Braten, Kartoffeln und Soße zusammen – ein Ritual, das mehr als Essen ist.","en":"In Britain, families gather on Sunday for roast meat, potatoes and gravy — a ritual that shapes time and relationships, not just appetite."},"teaser":{"ar":"وجبة الأحد المشوية ليست مجرد طعام؛ إنها موعد أسبوعي يجمع الأجيال ويحافظ على إيقاع الحياة البريطانية رغم تغيّر العادات.","de":"Der Sunday Roast ist kein bloßes Gericht, sondern ein wöchentlicher Termin, der Generationen verbindet und den Rhythmus des britischen Alltags prägt.","en":"The Sunday roast is more than a meal: it is a weekly appointment that links generations and holds the rhythm of British life together."},"readingMinutes":1,"sections":{"ar":[{"heading":"من الصوم إلى غداء العائلة","paragraphs":["تتكوّن وجبة الأحد المشوية في بريطانيا من لحم مشوي مع بطاطس وخضار ومرق، وغالباً بودينغ يوركشير، وتُؤكل عادةً ظهر يوم الأحد.","تعود جذورها إلى ولائم الأحد في العصور الوسطى وإلى أسبوع العمل الصناعي، حين كان الأحد يوم الراحة الوحيد؛ فكان اللحم يُوضع في الفرن قبل الذهاب إلى الكنيسة ويُكمَل طهيه بعد الصلاة."]},{"heading":"نكهات محلية وذاكرة جماعية","paragraphs":["تختلف الأطباق المرافقة بحسب المنطقة: بودينغ يوركشير مع لحم البقر، وحشوة المريمية والبصل مع لحم الخنزير، وصلصة النعناع مع لحم الضأن، والفجل الحار مع البقر.","تحافظ حانات الكارفري وقوائم غداء الأحد على التقليد تجارياً، وما زالت عائلات كثيرة تجتمع عليه حتى مع تراجع حضور الكنيسة الأسبوعي، ويحمل الطعام حنيناً قوياً في الثقافة البريطانية.","تختلف العادة بين المناطق والأجيال؛ ففي المدن أعادت غداءات الأحد الكاريبية وجنوب الآسيوية تشكيل شكل الوجبة، بينما لا تطبخها أسر كثيرة قط."]}],"de":[{"heading":"Vom Fasten zum Familienessen","paragraphs":["Der Sunday Roast ist in Großbritannien eine Mahlzeit aus Bratfleisch mit Kartoffeln, Gemüse und Soße, oft mit Yorkshire Pudding, traditionell am Sonntagmittag gegessen.","Seine Wurzeln liegen im mittelalterlichen Sonntagsmahl und in der industriellen Arbeitswoche, als der Sonntag der einzige freie Tag war; das Fleisch kam vor dem Kirchgang in den Ofen und wurde nach dem Gottesdienst fertig gegart."]},{"heading":"Regionale Aromen und kollektives Gedächtnis","paragraphs":["Die Beilagen variieren regional: Yorkshire Pudding zum Rind, Salbei-Zwiebel-Füllung zum Schwein, Minzsoße zum Lamm und Meerrettich zum Rind.","Pub-Carverys und Sonntagsmenüs halten die Tradition kommerziell am Leben, und viele Familien treffen sich weiterhin dazu, obwohl der wöchentliche Kirchbesuch zurückgegangen ist; das Essen trägt starke Nostalgie.","Die Gewohnheit unterscheidet sich je nach Region und Generation; in Städten haben karibische und südasiatische Sonntagsessen das Bild der Mahlzeit verändert, während viele Haushalte sie nie kochen."]}],"en":[{"heading":"From medieval feasting to family tables","paragraphs":["The Sunday roast is a British meal of roast meat with potatoes, vegetables and gravy, often Yorkshire pudding, traditionally eaten at mid-day on Sunday.","Its roots lie in medieval Sunday feasting and the industrial workweek, when Sunday was the one day off; meat went into the oven before church and was finished after the service."]},{"heading":"Regional flavours and shared memory","paragraphs":["Pairings matter by region: Yorkshire pudding with beef, sage and onion stuffing with pork, mint sauce with lamb, and horseradish with beef.","The pub carvery and Sunday lunch menu keep the tradition commercial, and many families still gather for it even as weekly church attendance has declined; the meal carries strong nostalgia in British culture.","The habit varies by region and generation; in cities Caribbean and South Asian Sunday lunches have reshaped what the meal looks like, while many households never cook it at all."]}]},"context":{"countries":["GB"],"region":"England","continent":"europe","languages":["en"],"period":"contemporary"},"tags":["food-and-hospitality","England"],"sources":[{"organization":"Wikipedia","title":{"ar":"Sunday roast","de":"Sunday roast","en":"Sunday roast"},"url":"https://en.wikipedia.org/wiki/Sunday_roast","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of England","de":"Culture of England","en":"Culture of England"},"url":"https://en.wikipedia.org/wiki/Culture_of_England","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في يوم أحد ممطر في شيفيلد، تجلس ثلاثة أجيال على المائدة عند الواحدة لتناول لحم البقر وبودينغ يوركشير والمرق، ويُترك غسل الأطباق حتى فيلم بعد الظهر.","de":"An einem regnerischen Sonntag in Sheffield sitzen drei Generationen um eins bei Rindfleisch, Yorkshire Puddings und Soße am Tisch, und das Abwaschen wartet bis zum Nachmittagsfilm.","en":"On a rainy Sunday in Sheffield, three generations sit down at one o'clock to beef, Yorkshire puddings and gravy, and the washing-up is left until the afternoon film."},"misunderstanding":{"ar":"يُظنّ أحياناً أن غداء الأحد تقليد ثابت في كل بريطانيا، لكن اسكتلندا وويلز وإيرلندا الشمالية لها تقاليد طعام مختلفة، وكثير من الأسر لا تطبخه أبداً.","de":"Manchmal wird angenommen, der Sunday Roast sei in ganz Großbritannien fest verankert, doch Schottland, Wales und Nordirland haben eigene Essenstraditionen, und viele Haushalte kochen ihn nie.","en":"It is sometimes assumed the Sunday roast is universal across Britain, but Scotland, Wales and Northern Ireland have distinct food traditions, and many British households never cook it."},"comparison":{"ar":"يشبه غداء الأحد موائد العائلة الأسبوعية في ثقافات أخرى، حيث يجتمع الناس في يوم راحة محدد حول طعام مشترك، لكن تفاصيله تبقى بريطانية بخاصة.","de":"Der Sunday Roast ähnelt wöchentlichen Familientischen anderer Kulturen, an denen man sich an einem Ruhetag um gemeinsames Essen versammelt, bleibt aber in seinen Details britisch.","en":"The Sunday roast resembles weekly family tables in other cultures, where people gather around shared food on a rest day, yet its details remain distinctly British."}},{"id":"tra-041","version":2,"slug":"the-eisteddfod-a-language-kept-by-competition","contentType":"note","category":"music-and-dance","title":{"ar":"الإستيدفود: لغة تُحفظ بالتنافس","de":"Der Eisteddfod: eine Sprache im Wettstreit","en":"The Eisteddfod: a language kept by competition"},"deck":{"ar":"مهرجان ويلزي سنوي يجمع الشعر والغناء والرقص، ويُدار أساساً باللغة الويلزية، فيتنقّل بين شمال ويلز وجنوبها كل صيف.","de":"Ein walisisches Festival für Literatur, Musik und Bühnenkunst, das weitgehend auf Walisisch stattfindet und jeden August zwischen Nord- und Südwales wandert.","en":"A Welsh festival of literature, music and performance held largely in Welsh, moving each August between north and south Wales."},"teaser":{"ar":"في خيمة مكتظّة يُنادى على الشاعر الفائز، فيقف الجمهور احتراماً؛ هكذا يبقى الإستيدفود قلب اللغة الويلزية النابض.","de":"Im vollen Zelt wird der siegreiche Dichter zum Stuhl geführt, das Publikum erhebt sich – so bleibt der Eisteddfod ein Herzstück der walisischen Sprache.","en":"In a packed pavilion the winning poet is led to the chair and the audience stands – a small ritual that keeps a language in public use."},"readingMinutes":1,"sections":{"ar":[{"heading":"مهرجان يتنقّل بين الشمال والجنوب","paragraphs":["الإستيدفود مهرجان ويلزي للأدب والموسيقى والأداء، ويُقام الإستيدفود الوطني في أغسطس ويتنقّل بين شمال ويلز وجنوبها، ويُدار في معظمه باللغة الويلزية.","تعود جذوره إلى عام 1861 وقد نما من إستيدفودات أقدم، ويُعدّ مؤسسة أساسية للغة الويلزية ولقاءً اجتماعياً يجمع الناطقين بها من مختلف المناطق.","تختلف التجربة بين الأجيال والمناطق: فبعض العائلات تحضر كل عام كتقليد عائلي، بينما يكتشفه شباب المدينة لأول مرة عبر أصدقاء أو مدارس."]},{"heading":"الكرسي والفنون المتنافسة","paragraphs":["قلب المهرجان هو تنصيب الشاعر على الكرسي، حين يُكرَّم الفائز بمسابقة الشعر ذات الوزن الصارم، الأودل، من قِبل غورسيد الشعراء برداءاتهم البيضاء والزرقاء والخضراء.","تشمل المسابقات الإلقاء والغناء الفردي والكورالي والموسيقى الآلية والرقص الشعبي، ويضمّ الساحة المحيطة، المايس، أكشاكاً وطعاماً والخيمة الكبرى.","وإلى جانب المهرجان الوطني تُقام إستيدفودات محلية ومهرجان الشباب أورد، وقد أثارت مراسم الغورسيد الدرودية قديماً مزيجاً من المودّة والانتقاد."]}],"de":[{"heading":"Ein Festival zwischen Nord und Süd","paragraphs":["Der Eisteddfod ist ein walisisches Festival für Literatur, Musik und Bühnenkunst; der National Eisteddfod findet im August statt, wandert zwischen Nord- und Südwales und wird überwiegend auf Walisisch abgehalten.","Er stammt aus dem Jahr 1861 und entstand aus älteren Eisteddfodau; heute gilt er als Schlüsselinstitution der walisischen Sprache und als gesellschaftliches Wiedersehen für walisische Sprecher.","Die Erfahrung unterscheidet sich je nach Region und Generation: Manche Familien kommen jedes Jahr als Tradition, während Stadtjugendliche ihn über Freunde oder Schulen neu entdecken."]},{"heading":"Der Stuhl und die Wettbewerbe","paragraphs":["Herzstück ist die Stuhlung des Barden, bei der der Gewinner des streng metrischen Gedichtwettbewerbs, der Awdl, von der Gorsedd der Barden in weißen, blauen und grünen Gewändern geehrt wird.","Die Wettbewerbe umfassen Rezitation, Solo- und Chorgesang, Instrumentalmusik und Volkstanz; das umliegende Feld, die Maes, bietet Stände, Essen und das Pavilion.","Neben dem nationalen Eisteddfod gibt es lokale Eisteddfodau und den Jugend-Eisteddfod Urdd; die druidische Zeremonie der Gorsedd erntet seit Langem sowohl Zuneigung als auch Kritik."]}],"en":[{"heading":"A festival that moves between north and south","paragraphs":["An eisteddfod is a Welsh festival of literature, music and performance. The National Eisteddfod is held in August, moves between north and south Wales, and is conducted largely in Welsh.","It dates from 1861 and grew out of earlier eisteddfodau. Today it is a key institution of the Welsh language and a social reunion for Welsh speakers from many places.","Experience varies by region and generation: some families attend every year as tradition, while city teenagers often discover it through friends or school."]},{"heading":"The chair and the competitions","paragraphs":["Its centrepiece is the chairing of the bard, when the winner of the strict-metre poetry competition, the awdl, is honoured by the Gorsedd of Bards in white, blue and green robes.","Competitions cover recitation, solo and choral singing, instrumental music and folk dance, while the surrounding field, the Maes, holds stalls, food and the pavilion.","There are also local eisteddfodau and the Urdd youth eisteddfod; the Gorsedd's druidic ceremonial has long attracted both affection and criticism."]}]},"context":{"countries":["GB"],"region":"Wales","continent":"europe","languages":["cy","en"],"period":"contemporary"},"tags":["music-and-dance","Wales"],"sources":[{"organization":"Wikipedia","title":{"ar":"Eisteddfod","de":"Eisteddfod","en":"Eisteddfod"},"url":"https://en.wikipedia.org/wiki/Eisteddfod","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Wales","de":"Culture of Wales","en":"Culture of Wales"},"url":"https://en.wikipedia.org/wiki/Culture_of_Wales","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في خيمة مكتظّة، يدعو رئيس الشعراء إلى السلام، فيُسمع صوت بوق، ويُصطحب الشاعر الفائز إلى الكرسي والجمهور واقف.","de":"In einem vollen Pavilion ruft der Archdruide zum Frieden auf, eine Trompete erklingt, und der siegreiche Dichter wird zum Stuhl geleitet, während das Publikum steht.","en":"In a packed pavilion, the Archdruid calls for peace, a trumpet sounds, and the winning poet is escorted to the chair while the audience stands."},"misunderstanding":{"ar":"يظنّ بعض الزوّار أنه مهرجان موسيقي عام كأي مهرجان صيفي، لكنه في جوهره حدث لغوي ويلزي بقواعده الخاصة، ويعيشه غير الناطقين بالويلزية بشكل مختلف.","de":"Manche Besucher halten ihn für ein gewöhnliches Sommermusikfestival, doch er ist ein walisisches Sprachereignis mit eigenen Regeln, das Nicht-Walisischsprecher anders erleben.","en":"Some visitors expect an ordinary summer music festival, but this is a Welsh-language event with its own rules, and non-Welsh speakers experience it differently."},"comparison":{"ar":"يشبه في وظيفته الاجتماعية مهرجانات محلية تحفظ تراثاً لغوياً، لكن ما يميّزه أن المنافسة نفسها هي وسيلة الحفاظ على اللغة.","de":"In seiner sozialen Rolle ähnelt er lokalen Festen, die sprachliches Erbe bewahren, doch hier ist der Wettbewerb selbst das Mittel des Erhalts.","en":"It plays a social role similar to local festivals that preserve linguistic heritage, but here the competition itself is the means of keeping the language alive."}},{"id":"tra-042","version":2,"slug":"the-irish-wake-three-days-of-tea-and-stories","contentType":"note","category":"family-and-friendship","title":{"ar":"الاستيقاظ الأيرلندي: ثلاثة أيام من الشاي والحكايات","de":"Die irische Totenwache: drei Tage Tee und Geschichten","en":"The Irish wake: three days of tea and stories"},"deck":{"ar":"بين الموت والحياة، تفتح العائلات الأيرلندية بيوتها للجيران، فيختلط الحزن بالضحك فوق أكواب الشاي.","de":"Zwischen Tod und Beerdigung öffnen irische Familien ihr Haus für die Nachbarschaft, und über den Teetassen liegen Trauer und Lachen nah beieinander.","en":"Between death and burial, Irish families open their homes to neighbours, and over cups of tea grief and laughter sit side by side."},"teaser":{"ar":"في الأيام الفاصلة بين الموت والدفن، يتحول بيت العائلة الأيرلندية إلى مكان للعزاء والضيافة والحكايات.","de":"In den Tagen zwischen Tod und Beerdigung wird das irische Familienhaus zum Ort des Beileids, der Gastfreundschaft und der Erinnerungen.","en":"In the days between death and burial, the Irish family home becomes a place of condolence, hospitality and remembrance."},"readingMinutes":1,"sections":{"ar":[{"heading":"البيت مفتوح للجميع","paragraphs":["يجري الاستيقاظ الأيرلندي تقليدياً في بيت العائلة في الأيام الفاصلة بين الموت والدفن، حيث يُمدّد المتوفى في غرفة ويأتي الجيران لتقديم العزاء.","الضيافة في صميم الأمر: يُقدَّم الشاي والسندويتشات والكعك وغالباً الكحول، ويتبادل الزوار الحكايات عن الراحل، فيختلط الضحك بالحزن.","تختلف الممارسة بحسب الدين والمنطقة والعائلة، كما تتباين بين الأجيال والأرياف والمدن."]},{"heading":"من الندب إلى المقبرة","paragraphs":["شملت العادات القديمة إيقاف الساعات وتغطية المرايا وإشعال الشموع، وكانت النساء يؤدين الندب الرسمي المعروف باسم «كاينيّ».","انقرض الندب إلى حد كبير في القرن العشرين، وانتقلت مراسم الاستيقاظ في المدن تدريجياً إلى دور الجنائز، لكن زيارة العزاء والشاي بقيا.","يتبع الاستيقاظ نقل الجثمان إلى الكنيسة وقداس الجنازة في العرف الكاثوليكي ثم الدفن، وكثيراً ما يوصف بأنه مناسبة اجتماعية بقدر ما هو ديني."]}],"de":[{"heading":"Das Haus steht allen offen","paragraphs":["Die irische Totenwache findet traditionell im Familienhaus in den Tagen zwischen Tod und Beerdigung statt, der Verstorbene wird in einem Zimmer aufgebahrt, und Nachbarn kommen, um ihre Anteilnahme zu zeigen.","Gastfreundschaft steht im Mittelpunkt: Tee, Sandwiches, Kuchen und oft Alkohol werden gereicht, Besucher erzählen Geschichten über den Verstorbenen, und neben der Trauer ist auch Lachen zu hören.","Die Praxis variiert je nach Religion, Region und Familie und unterscheidet sich zwischen Generationen sowie zwischen Stadt und Land."]},{"heading":"Vom Klagen zum Grab","paragraphs":["Ältere Bräuche umfassten das Anhalten der Uhren, das Verhüllen der Spiegel und das Entzünden von Kerzen; Frauen trugen die formelle Totenklage vor, das „Caoineadh“.","Die Totenklage starb im zwanzigsten Jahrhundert weitgehend aus, und in den Städten verlagerte sich die Wache zunehmend in Bestattungsinstitute, doch der Besuch und der Tee blieben.","Auf die Wache folgen die Überführung in die Kirche, in katholischer Praxis eine Totenmesse und die Beerdigung; oft wird sie als gesellschaftliches Ereignis ebenso wie als religiöses beschrieben."]}],"en":[{"heading":"The house stays open","paragraphs":["An Irish wake traditionally takes place in the family home in the days between death and burial, with the deceased laid out in a room and neighbours calling to pay respects.","Hospitality is central: tea, sandwiches, cake and often alcohol are served, and visitors share stories about the deceased, with laughter alongside grief.","Practice varies by religion, region and family, and it shifts between generations and between rural and city life."]},{"heading":"From keening to the grave","paragraphs":["Older customs included stopping clocks, covering mirrors and lighting candles, and keening, the caoineadh, was performed by women as a formal lament.","Keening largely died out in the twentieth century, and city wakes have increasingly moved to funeral homes, but the visitation and the tea remain.","The wake is followed by removal to the church, a funeral Mass in Catholic practice, and burial, and it is often described as a social event as much as a religious one."]}]},"context":{"countries":["IE"],"region":"Ireland","continent":"europe","languages":["en","ga"],"period":"contemporary"},"tags":["family-and-friendship","Ireland"],"sources":[{"organization":"Wikipedia","title":{"ar":"Wake (ceremony)","de":"Wake (ceremony)","en":"Wake (ceremony)"},"url":"https://en.wikipedia.org/wiki/Wake_(ceremony)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Ireland","de":"Culture of Ireland","en":"Culture of Ireland"},"url":"https://en.wikipedia.org/wiki/Culture_of_Ireland","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مطبخ بريف مقاطعة مايو، يصل الجيران بأطباق السندويتشات ويجلسون مع العائلة حتى منتصف الليل، ويروون حكاية عن خروف الراحل الذي فاز بجائزة.","de":"In einer Küche im ländlichen Mayo kommen Nachbarn mit Sandwichplatten, sitzen bis Mitternacht bei der Familie und erzählen eine Geschichte über das preisgekrönte Schaf des Verstorbenen.","en":"In a kitchen in rural Mayo, neighbours arrive with sandwich platters, sit with the family until midnight, and tell a story about the deceased's prize-winning sheep."},"misunderstanding":{"ar":"تضخم صورة «الاستيقاظ الأيرلندي الجامح» الشرب، وتشوّه مناسبة تتسم عادة بالرصانة.","de":"Das Klischee der „wilden irischen Totenwache“ übertreibt das Trinken und verzerrt einen meist besinnlichen Anlass.","en":"The 'wild Irish wake' stereotype exaggerates the drinking and misrepresents a usually sober occasion."},"comparison":{"ar":"يشبه الاستيقاظ في استقباله للجيران العزاء في ثقافات أخرى، لكن ما يميزه هو الحكايات والضحك حول الشاي.","de":"Die Wache ähnelt dem Kondolieren in anderen Kulturen, doch Geschichten und Lachen beim Tee sind ihre besondere Note.","en":"The wake resembles condolence visits in other cultures, but stories and laughter around tea give it its own character."}},{"id":"tra-043","version":2,"slug":"fika-the-coffee-break-you-are-expected-to-take","contentType":"detail","category":"everyday-life","title":{"ar":"فيكا: استراحة القهوة التي يُتوقع منك أخذها","de":"Fika: die Kaffeepause, die man nehmen soll","en":"Fika: the coffee break you are expected to take"},"deck":{"ar":"في السويد، ليست القهوة مجرد مشروب، بل طقس اجتماعي يجمع الزملاء والأصدقاء حول طاولة واحدة.","de":"In Schweden ist Kaffee mehr als ein Getränk – es ist ein soziales Ritual, das Kollegen und Freunde an einen Tisch bringt.","en":"In Sweden, coffee is more than a drink—it is a social ritual that brings colleagues and friends around one table."},"teaser":{"ar":"فيكا ليست مجرد استراحة قهوة، بل مؤسسة اجتماعية سويدية تعزز المساواة وتجمع الناس للتحدث وتناول الكعك.","de":"Fika ist keine bloße Kaffeepause, sondern eine schwedische Institution, die Gleichheit fördert und Menschen zum Reden und Kuchenessen zusammenbringt.","en":"Fika is not just a coffee break; it is a Swedish institution that fosters equality and brings people together to talk and eat cake."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما هي الفيكا؟","paragraphs":["فيكا هي عادة سويدية لأخذ استراحة قهوة، غالبًا مع شيء حلو مثل كانيلبول، كعكة القرفة، وتؤخذ في أوقات محددة في أماكن العمل.","الكلمة هي فعل واسم في آن واحد، 'أت فيكا'، وتعني الجلوس للتحدث بدلًا من شرب القهوة أثناء التنقل.","الكلمة من عامية القرن العشرين، وغالبًا ما تُفسر على أنها قلب مرح لكلمة 'كافي' (قهوة)، وأصبحت شائعة في أوائل القرن العشرين."]},{"heading":"الفيكا والحياة اليومية","paragraphs":["العديد من أماكن العمل لديها فيكا جماعية مرتين يوميًا، وإحضار كعكة أو كعك إلى المكتب في عيد الميلاد واجب شائع.","تحمل الفيكا روح المساواة: يجلس المديرون والموظفون معًا، والاستراحة مكان يُفترض أن تخفف فيه التسلسل الهرمي.","تختلف الممارسة حسب المنطقة والأجيال؛ فليس كل سويدي يأخذ فيكا يوميًا، وصورة 'أسلوب حياة الفيكا' التجارية تبسط عادة تتفاوت حسب مكان العمل والمنطقة."]}],"de":[{"heading":"Was ist Fika?","paragraphs":["Fika ist die schwedische Institution einer Kaffeepause, meist mit etwas Süßem wie einer Kanelbulle, der Zimtschnecke, und oft zu festen Zeiten am Arbeitsplatz.","Es ist Verb und Nomen zugleich, „att fika“, und bedeutet, sich zum Reden hinzusetzen, statt Kaffee unterwegs zu trinken.","Das Wort stammt aus dem Slang des 20. Jahrhunderts und wird oft als spielerische Umkehrung von „kaffe“ erklärt; Anfang des 20. Jahrhunderts wurde es allgemein gebräuchlich."]},{"heading":"Fika im Alltag","paragraphs":["Viele Arbeitsplätze haben zweimal täglich eine gemeinsame Fika, und zum Geburtstag Kuchen oder Brötchen mitzubringen, ist eine verbreitete Pflicht.","Fika trägt ein egalitäres Ethos: Manager und Mitarbeiter sitzen zusammen, und die Pause soll Hierarchie abschwächen.","Die Praxis variiert regional und generationell; nicht jeder Schwede fikat täglich, und das kommerzielle Bild vom „Fika-Lifestyle“ vereinfacht einen Brauch, der je nach Arbeitsplatz und Region unterschiedlich ist."]}],"en":[{"heading":"What is fika?","paragraphs":["Fika is the Swedish institution of a coffee break, usually with something sweet such as a kanelbulle, the cinnamon bun, and often taken at set times in workplaces.","It is a verb as well as a noun, att fika, and it implies sitting down to talk rather than drinking coffee on the move.","The word is twentieth-century slang, often explained as a playful reversal of kaffe, coffee, and it became general in the early 1900s."]},{"heading":"Fika in everyday life","paragraphs":["Many workplaces have a collective fika twice a day, and bringing cake or buns to the office for a birthday is a common obligation.","Fika carries an egalitarian ethos: managers and staff sit together, and the break is a place where hierarchy is supposed to soften.","The practice varies by region and generation; not every Swede fikas daily, and the commercial 'fika lifestyle' image oversimplifies a practice that varies by workplace and region."]}]},"context":{"countries":["SE"],"region":"Sweden","continent":"europe","languages":["sv"],"period":"contemporary"},"tags":["everyday-life","Sweden"],"sources":[{"organization":"Wikipedia","title":{"ar":"Fika","de":"Fika","en":"Fika"},"url":"https://en.wikipedia.org/wiki/Fika","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Sweden","de":"Culture of Sweden","en":"Culture of Sweden"},"url":"https://en.wikipedia.org/wiki/Culture_of_Sweden","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في الساعة الثالثة بعد الظهر، تمتلئ مطبخ المكتب لأجل الفيكا، يقطع أحدهم كعكة الأميرة، ويؤجل الاجتماع الذي طال حتى بعد القهوة.","de":"Um 15 Uhr füllt sich die Büroküche zur Fika, jemand schneidet eine Prinzessinnentorte an, und das Meeting, das sich verzogen hat, wird auf nach dem Kaffee verschoben.","en":"At 3 p.m. the office kitchen fills for fika, someone cuts a princess cake, and the meeting that ran late is postponed until after the coffee."},"misunderstanding":{"ar":"يعتقد البعض أن الفيكا مجرد شرب قهوة سريعة، لكنها في الحقيقة جلوس وتواصل اجتماعي.","de":"Manche halten Fika für einen schnellen Kaffee, doch es geht ums Hinsetzen und Miteinanderreden.","en":"Some think fika is just a quick coffee, but it is really about sitting down and talking together."},"comparison":{"ar":"على عكس استراحات القهوة السريعة في بعض الثقافات، تشجع الفيكا على التوقف والتحدث وتعزيز الروابط.","de":"Anders als schnelle Kaffeepausen in manchen Kulturen lädt Fika zum Innehalten und Gespräch ein.","en":"Unlike quick coffee breaks in some cultures, fika encourages pausing and conversation."}},{"id":"tra-044","version":2,"slug":"sauna-finland-s-everyday-room","contentType":"note","category":"everyday-life","title":{"ar":"الساونا: غرفة فنلندا اليومية","de":"Sauna: Finnlands alltäglicher Raum","en":"Sauna: Finland's everyday room"},"deck":{"ar":"ثلاثة ملايين ساونا لشعبٍ من 5.5 مليون نسمة تجعل الحمّام الخشبي جزءاً من البيت لا رفاهية.","de":"Drei Millionen Saunen für 5,5 Millionen Menschen machen die Sauna zur Hausausstattung statt zum Luxus.","en":"Three million saunas for 5.5 million people make the sauna a household fixture rather than a luxury."},"teaser":{"ar":"في فنلندا تُدفأ الساونا بالحطب، ويتبادل الناس الحرارة والبرودة، ويجلسون صامتين تقريباً احتراماً لمساحة الآخر.","de":"In Finnland wird die Sauna mit Holz beheizt, Hitze und Abkühlung wechseln sich ab, und man sitzt fast schweigend aus Respekt vor dem Raum der anderen.","en":"In Finland the sauna is heated with wood, heat alternates with cooling, and people sit in near silence out of respect for each other's space."},"readingMinutes":1,"sections":{"ar":[{"heading":"بيت من الخشب والحرارة","paragraphs":["في فنلندا نحو ثلاثة ملايين ساونا لسكانٍ يبلغون حوالي 5.5 مليون، فالساونا تجهيزة منزل أو مبنى لا ترفاً. والساونا الكلاسيكية تُدفأ بالحطب، وأقدم أشكالها ساونا الدخان «سافوساونا»، والحرارة عادة بين 80 و100 درجة مئوية.","يتبادل الجلوس إيقاعاً بين الحرارة والتبريد: الخروج إلى الهواء، والتقلّب في الثلج، والسباحة في بحيرة أو دشّ بارد بين الجولات. وتختلف هذه العادات بين الأجيال وبين المدن والأرياف."]},{"heading":"مكان للغسل والمناسبات","paragraphs":["استُخدمت الساونا للغسل والشفاء ولمناسبات الحياة الكبرى؛ فتاريخياً وُلد الأطفال فيها وجهّز الموتى فيها. وفي 2020 أُدرجت ثقافة الساونا الفنلندية في قائمة التراث غير المادي لليونسكو.","تشمل آدابها منشفةً وحديثاً هادئاً واحترام مساحة الآخرين. وتتبع الساونا العامة وقواعد المنزل قواعد مختلفة، وتتفاوت الثقافة بين فنلندا والسويد وروسيا ودول البلطيق."]}],"de":[{"heading":"Ein Raum aus Holz und Hitze","paragraphs":["Finnland hat rund drei Millionen Saunen bei etwa 5,5 Millionen Einwohnern, die Sauna ist also Haus- oder Gebäudeausstattung, kein Luxus. Die klassische Sauna wird mit Holz beheizt, die älteste Form ist die Rauchsauna, savusauna; die Temperaturen liegen meist zwischen 80 und 100 Grad Celsius.","Der Rhythmus wechselt Hitze und Abkühlung: hinaustreten, im Schnee wälzen, im See schwimmen oder kalt duschen zwischen den Runden. Diese Gewohnheiten unterscheiden sich je nach Generation sowie zwischen Stadt und Land."]},{"heading":"Ort für Waschen und Lebensereignisse","paragraphs":["Saunen dienten dem Waschen, dem Heilen und großen Lebensereignissen; historisch wurden Babys dort geboren und Verstorbene dort vorbereitet. 2020 wurde die finnische Saunakultur in die UNESCO-Liste des immateriellen Erbes aufgenommen.","Zur Etikette gehören ein Handtuch, leises Sprechen und Respekt vor der Distanz anderer. Öffentliche und häusliche Saunen folgen unterschiedlichen Regeln, und die Kultur unterscheidet sich zwischen Finnland, Schweden, Russland und dem Baltikum."]}],"en":[{"heading":"A room of wood and heat","paragraphs":["Finland has around three million saunas for a population of about 5.5 million, so the sauna is a household or building fixture rather than a luxury. The classic Finnish sauna is heated by wood, with the smoke sauna, savusauna, as the oldest form; temperatures are usually between 80 and 100 degrees Celsius.","The rhythm alternates heat with cooling: stepping outside, rolling in snow, swimming in a lake or taking a cold shower between rounds. These habits vary between generations and between town and countryside."]},{"heading":"A place for washing and life events","paragraphs":["Saunas have been used for washing, healing and major life events; historically babies were born in them and the dead were prepared there. In 2020 Finnish sauna culture was inscribed on UNESCO's intangible heritage list.","Etiquette includes a towel, quiet talk and respecting others' space. Public saunas and home saunas follow different rules, and sauna culture varies between Finland, Sweden, Russia and the Baltic states."]}]},"context":{"countries":["FI"],"region":"Finland","continent":"europe","languages":["fi","sv"],"period":"contemporary"},"tags":["everyday-life","Finland"],"sources":[{"organization":"Wikipedia","title":{"ar":"Finnish sauna","de":"Finnish sauna","en":"Finnish sauna"},"url":"https://en.wikipedia.org/wiki/Finnish_sauna","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Sauna","de":"Sauna","en":"Sauna"},"url":"https://en.wikipedia.org/wiki/Sauna","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في أمسية صيفية عند كوخ على البحيرة، تُدفئ عائلة الساونا الخشبية، وتجلس داخلها بأحزمة أغصان البتولا، ثم تركض إلى الرصيف لتقفز في البحيرة.","de":"An einem Sommerabend an einer Seehütte heizt eine Familie die Holzsauna, sitzt mit Birkenwedeln darin und läuft dann zum Steg, um in den See zu springen.","en":"On a summer evening at a lakeside cottage, a family heats the wood sauna, sits inside with birch whisk bundles, then runs down the jetty to jump into the lake."},"misunderstanding":{"ar":"يظن كثيرون أن الساونا مكان للصخب أو للعراء الجماعي، لكن الآداب الفنلندية تقدّر الهدوء والمساحة الشخصية.","de":"Viele halten die Sauna für einen lauten oder gemeinschaftlichen Nacktraum, doch finnische Etikette schätzt Ruhe und persönlichen Abstand.","en":"Many assume the sauna is loud or a shared naked gathering, yet Finnish etiquette values quiet and personal space."},"comparison":{"ar":"في فنلندا الساونا شبه يومية وفي كل مبنى تقريباً، بينما تكون في بلدان أخرى مناسبةً استثنائية أو تجربة سياحية.","de":"In Finnland ist die Sauna fast täglich und in beinahe jedem Gebäude, anderswo ist sie ein besonderer Anlass oder eine Tourismus-Erfahrung.","en":"In Finland the sauna is almost daily and in nearly every building, while elsewhere it is a special occasion or a tourist experience."}},{"id":"tra-045","version":2,"slug":"hygge-the-ordinary-practice-of-shelter","contentType":"note","category":"everyday-life","title":{"ar":"هيغة: دفء العادي في الدنمارك","de":"Hygge: Wärme im ganz Gewöhnlichen","en":"Hygge: the ordinary practice of shelter"},"deck":{"ar":"كيف يصنع الدنماركيون مأوى من الشموع والبطاطين والوقت غير المستعجل مع الآخرين، لا من الرفاهية.","de":"Wie Däninnen und Dänen mit Kerzen, Decken und ungestörter Zeit ein Gefühl von Obdach schaffen, ohne Luxus.","en":"How Danes use candles, blankets and unhurried time to build a feeling of shelter, not luxury."},"teaser":{"ar":"كلمة دانماركية تعني الأنس الدافئ، تُستدعى في الشتاء القصير النهار، وتحدّد من يجلس إلى الطاولة.","de":"Ein dänisches Wort für gemütliches Beisammensein, das im kurzen Winterlicht aufkommt und zugleich bestimmt, wer am Tisch sitzt.","en":"A Danish word for comfortable togetherness, called on in the short winter light and quietly deciding who belongs at the table."},"readingMinutes":1,"sections":{"ar":[{"heading":"معنى يسكن العادي","paragraphs":["تصف «هيغة» مزاجًا من المأوى والدفء والراحة: شموع على الطاولة، بطاطين، مشروب ساخن، ووقت غير مستعجل مع آخرين. الكلمة مرتبطة بمصطلح نرويجي قديم يعني المأوى والعافية، ودخلت الدنماركية في القرن التاسع عشر ثم صارت كلمة ثقافية مفتاحية في القرن العشرين.","الأمر عادي لا فاخر: وجبة بسيطة مع أصدقاء، وأريكة وبطانية. النسخة التجارية التي انتشرت لاحقًا في تصميم الديكور تصدير متأخر، لا الاستخدام اليومي الذي يعرفه الدنماركيون.","يستدعيها الناس غالبًا في الشتاء حين يقصر النهار، وتُستعمل اسمًا وفعلًا وصفةً هي «هيغليغت». وتختلف حدّتها بين الأجيال والمناطق: بعض الشباب في المدن يوسّعونها لتشمل لقاءً بسيطًا عبر الشاشة، بينما يتمسك كبار السن بالمعنى التقليدي للغرفة الدافئة."]},{"heading":"دائرة دافئة لها حدود","paragraphs":["يلاحظ علماء الأنثروبولوجيا أن «هيغة» تحدد أيضًا من ينتمي ومن يبقى خارجًا؛ فالدائرة الدافئة قد تكون طريقة لرسم حدود الطاولة.","هذا لا يلغي دفأها، بل يوضح أنها ممارسة اجتماعية حيّة تُبنى بالتفاصيل الصغيرة.","في مساء تشرين الثاني المظلم، تشعل عائلة في كوبنهاغن شموعًا وتعدّ قهوة وتجلس تحت البطاطين مع لعبة بدل الخروج."]}],"de":[{"heading":"Ein Gefühl im Alltäglichen","paragraphs":["Hygge beschreibt eine Stimmung von Obdach, Wärme und Leichtigkeit: Kerzen, Decken, warme Getränke und ungestörte Zeit mit anderen. Das Wort hängt mit einem alten norwegischen Begriff für Obdach und Wohlbefinden zusammen, kam im 19. Jahrhundert ins Dänische und wurde im 20. zum kulturellen Schlüsselwort.","Es ist gewöhnlich, nicht luxuriös: eine Kerze auf dem Tisch, ein einfaches Essen mit Freunden, Sofa und Decke. Die kommerzielle Design-Version ist ein späterer Export.","Däninnen und Dänen rufen Hygge oft im Winter auf, wenn das Tageslicht kurz ist, und nutzen das Wort als Substantiv, Verb und Adjektiv, hyggeligt. Je nach Region und Generation verschiebt sich die Grenze: Manche Jüngeren in den Städten beziehen ein schlichtes Treffen über den Bildschirm mit ein, Ältere halten am warmen Zimmer fest."]},{"heading":"Ein warmer Kreis mit Rändern","paragraphs":["Anthropologinnen und Anthropologen bemerken, dass Hygge auch Zugehörigkeit markiert: Der warme Kreis kann festlegen, wer am Tisch dazugehört.","Das nimmt ihm nichts von seiner Wärme, es zeigt nur, dass es gelebte soziale Praxis ist.","An einem dunklen Novemberabend zündet eine Kopenhagener Familie Kerzen an, kocht Kaffee und sitzt mit einem Brettspiel unter Decken, statt auszugehen."]}],"en":[{"heading":"A mood inside the ordinary","paragraphs":["Hygge describes a mood of shelter, warmth and ease: candles, blankets, warm drinks and unhurried time with others. The word is related to an old Norwegian term for shelter and well-being, entered Danish in the nineteenth century and became a cultural keyword in the twentieth.","It is ordinary rather than luxurious: a candle on the table, a simple meal with friends, a sofa and a blanket. The commercial design version is a later export.","Danes often invoke hygge in winter, when daylight is short, and use it as a noun, a verb and an adjective, hyggeligt. Its edges shift by region and generation: some younger city dwellers stretch it to a quiet call on screen, while older people keep the warm room at the centre."]},{"heading":"A warm circle with edges","paragraphs":["Anthropologists note that hygge also marks inclusion and exclusion: the warm circle can define who belongs at the table.","That does not cancel its warmth; it shows hygge is lived social practice, built from small details.","On a dark November evening, a Copenhagen family lights candles, makes a pot of coffee and sits under blankets with a board game instead of going out."]}]},"context":{"countries":["DK"],"region":"Denmark","continent":"europe","languages":["da"],"period":"contemporary"},"tags":["everyday-life","Denmark"],"sources":[{"organization":"Wikipedia","title":{"ar":"Hygge","de":"Hygge","en":"Hygge"},"url":"https://en.wikipedia.org/wiki/Hygge","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Denmark","de":"Culture of Denmark","en":"Culture of Denmark"},"url":"https://en.wikipedia.org/wiki/Culture_of_Denmark","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مساء تشرين الثاني المظلم، تشعل عائلة في كوبنهاغن شموعًا وتعدّ قهوة وتجلس تحت البطاطين مع لعبة بدل الخروج.","de":"An einem dunklen Novemberabend zündet eine Kopenhagener Familie Kerzen an, kocht Kaffee und sitzt mit einem Brettspiel unter Decken, statt auszugehen.","en":"On a dark November evening, a Copenhagen family lights candles, makes a pot of coffee and sits under blankets with a board game instead of going out."},"misunderstanding":{"ar":"ليست «هيغة» منتجًا فاخرًا يُشترى، ولا مرادفًا تامًا للنرويجية «كوسيليغ»؛ النسخة الترفيهية التجارية أبعد ما تكون عن الاستخدام الدنماركي.","de":"Hygge ist kein kaufbares Luxusprodukt und nicht deckungsgleich mit dem norwegischen koselig; die Wellness-Version der Industrie entspricht selten dem dänischen Gebrauch.","en":"Hygge is not a luxury product to buy, and it is not identical to Norwegian koselig; the wellness-industry version is far from everyday Danish use."},"comparison":{"ar":"تقترب من النرويجية «كوسيليغ» لكنها ليست مطابقة، وتشبه في العربية جلسة «سمر» شتوية بلا تكلف.","de":"Nahe am norwegischen koselig, aber nicht identisch; verwandt mit einem winterlichen Zusammensitzen, das ohne Aufwand auskommt.","en":"Close to Norwegian koselig but not the same, and kin to any winter gathering that asks for no effort or display."}},{"id":"tra-046","version":2,"slug":"bunad-wearing-a-region-on-17-may","contentType":"note","category":"clothing-and-design","title":{"ar":"البوناد: ترتدي منطقتك في 17 مايو","de":"Bunad: die Region am 17. Mai tragen","en":"Bunad: wearing your region on 17 May"},"deck":{"ar":"زيّ تقليدي نرويجي يحمل اسم الوادي والتطريز والفضة، ويتجدّد كل عام في مواكب يوم الدستور.","de":"Ein norwegisches Festgewand, das Tal, Stickerei und Silber im Namen trägt und jedes Jahr im Umzug zum Verfassungstag neu auflebt.","en":"A Norwegian costume that carries a valley in its embroidery, silver and wool, and comes out every year for Constitution Day."},"teaser":{"ar":"في السابع عشر من مايو تمتلئ الشوارع بأزياء البوناد إلى جانب البدلات والفرق المدرسية، حيث يحمل كل ثوب حكاية منطقة.","de":"Am 17. Mai füllen sich die Straßen mit Bunaden neben Anzügen und Schulkapellen – und jedes Gewand erzählt von einer bestimmten Gegend.","en":"On 17 May the streets fill with bunads beside suits and school marching bands, and each outfit quietly announces which part of Norway its wearer calls home."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما هو البوناد ولماذا يخصّ مكاناً بعينه","paragraphs":["البوناد زي تقليدي نرويجي يتميّز بالتطريز والمجوهرات الفضية والصوف المنسوج، وتُربط تصاميمه بمناطق وأودية محددة، فيمكن للمتمرّس أن يقرأ من الثوب من أين صاحبه.","معظم هذه الأزياء أُعيد بناؤها في القرنين التاسع عشر والعشرين انطلاقاً من ملابس شعبية أقدم ومن أبحاث رومانسية وطنية، فهي ليست ملابس عصور وسطى بقيت على حالها كما يظن بعض الزوار.","يختلف الاهتمام بها بين الأجيال والمناطق؛ فبعض العائلات تعدّها إرثاً حياً، وأخرى تراها مناسبة تُلبس في المناسبات فقط."]},{"heading":"ثمنها وسوقها ثم يومها الكبير","paragraphs":["البوناد الكامل مكلف، إذ يبلغ سعره غالباً عشرات الآلاف من الكرونات، وقد يستغرق تجميعه سنوات؛ وكثير منها يُورث أو يُخاط حسب الطلب.","مجالس البوناد المحلية تعتمد التصاميم وتقدّم النصح في طريقة اللبس الصحيحة، والمجوهرات الفضية «سوليه» كثيراً ما تكون قطعة عائلية متوارثة.","في 17 مايو، يوم الدستور، تمتلئ الشوارع بالبوناد إلى جانب البدلات والفرق المدرسية، والتحية المتداولة هي «غراتوليرر ميد داغن»، أي تهانينا بهذا اليوم."]}],"de":[{"heading":"Was eine Bunad ist und warum sie zu einem Ort gehört","paragraphs":["Eine Bunad ist eine norwegische traditionelle Tracht, erkennbar an Stickerei, Silberschmuck und gewebter Wolle; die Entwürfe sind an bestimmte Regionen und Täler gebunden, sodass Kundige am Gewand die Herkunft ablesen.","Die meisten Bunaden wurden im 19. und 20. Jahrhundert aus älterer Volkstracht und nationalromantischer Forschung rekonstruiert – sie sind also keine unveränderte mittelalterliche Kleidung, wie manche Besucher annehmen.","Die Bindung an die Tracht variiert regional und zwischen den Generationen: Für manche Familien ist sie lebendiges Erbe, für andere ein Stück für besondere Anlässe."]},{"heading":"Preis, Beratung und der große Tag","paragraphs":["Eine vollständige Bunad ist teuer, oft kostet sie Zehntausende Kronen, und ihr Zusammenstellen kann Jahre dauern; viele werden vererbt oder auf Bestellung gefertigt.","Örtliche Bunad-Räte genehmigen Entwürfe und beraten zur korrekten Trageweise, und der Silberschmuck, die Sølje, ist häufig ein Familienstück.","Am 17. Mai, dem Verfassungstag, füllen sich die Straßen mit Bunaden neben Anzügen und Schulkapellen; der Gruß lautet „Gratulerer med dagen“, herzlichen Glückwunsch zum Tag."]}],"en":[{"heading":"What a bunad is, and why it belongs to a place","paragraphs":["A bunad is a Norwegian traditional costume distinguished by embroidery, silver jewellery and woven wool, and its designs are tied to specific regions and valleys, so the trained eye can read where the wearer comes from.","Most bunads were reconstructed in the nineteenth and twentieth centuries from older folk dress and national-romantic research, so they are not unchanged medieval clothing, as some visitors assume.","Attachment to the costume varies by region and generation: for some families it is living heritage, for others an outfit reserved for special occasions."]},{"heading":"Cost, councils and the big day","paragraphs":["A complete bunad is expensive, often costing tens of thousands of kroner, and can take years to assemble; many are inherited or made to order.","Local bunad councils approve designs and advise on correct use, and the silver jewellery, sølje, is often a family heirloom.","On 17 May, Constitution Day, streets fill with bunads alongside suits and school marching bands, and the greeting is “Gratulerer med dagen”, congratulations on the day."]}]},"context":{"countries":["NO"],"region":"Norway","continent":"europe","languages":["no"],"period":"contemporary"},"tags":["clothing-and-design","Norway"],"sources":[{"organization":"Wikipedia","title":{"ar":"Bunad","de":"Bunad","en":"Bunad"},"url":"https://en.wikipedia.org/wiki/Bunad","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Constitution Day (Norway)","de":"Constitution Day (Norway)","en":"Constitution Day (Norway)"},"url":"https://en.wikipedia.org/wiki/Constitution_Day_(Norway)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في 17 مايو في بيرغن، تُثبّت جدة بروش الفضة لحفيدتها، وتعدّل المريلة، وتنضم إلى موكب المدرسة تحت المطر.","de":"Am 17. Mai in Bergen steckt eine Großmutter ihrer Enkelin die Silberbrosche an, richtet die Schürze und reiht sich im Regen in den Schulzug ein.","en":"On 17 May in Bergen, a grandmother fastens her granddaughter's silver brooch, adjusts the apron and joins the school parade in the rain."},"misunderstanding":{"ar":"ليس كل النرويجيين يملكون بوناد، والزي السامي «غاكتي» لباس قومي مختلف تماماً لا ينبغي الخلط بينه وبين البوناد.","de":"Viele Norweger besitzen keine Bunad, und der samische Gákti ist eine eigene Nationaltracht, die man nicht mit ihr verwechseln sollte.","en":"Many Norwegians do not own a bunad, and the Sámi gákti is a distinct national dress that should not be confused with it."},"comparison":{"ar":"يشبه البوناد في وظيفته الأزياء الإقليمية في أوروبا الوسطى: زي واحد يعلن الانتماء المحلي في يوم وطني جامع.","de":"In ihrer Funktion ähnelt die Bunad regionalen Trachten in Mitteleuropa: ein Gewand, das an einem gemeinsamen Nationalfeiertag lokale Zugehörigkeit zeigt.","en":"In function it resembles regional dress in central Europe: one garment that signals local belonging on a shared national holiday."}},{"id":"tra-047","version":2,"slug":"wigilia-the-empty-chair-at-poland-s-christmas-eve","contentType":"note","category":"traditions","title":{"ar":"الكرسي الفارغ في ليلة عيد الميلاد البولندية","de":"Der leere Stuhl am polnischen Weihnachtsabend","en":"The empty chair at Poland's Christmas Eve"},"deck":{"ar":"عشاء فيغيلية يبدأ مع أول نجمة، ويُترك فيه مقعد لمن لم يحضر، وتُفتح الهدايا بعده.","de":"Das Wigilia-Mahl beginnt mit dem ersten Stern, lässt einen Platz frei und endet mit Geschenken.","en":"Wigilia begins with the first star, leaves one place free and ends with presents under the tree."},"teaser":{"ar":"في بولندا تبدأ ليلة 24 ديسمبر حين تظهر أول نجمة، فيتقاسم أهل البيت رقاقة الخبز المقدّس ويتركون كرسياً فارغاً.","de":"In Polen beginnt der 24. Dezember mit dem ersten Stern: Die Familie teilt Oblaten, wünscht einander Glück und lässt einen Stuhl leer.","en":"On 24 December in Poland, families wait for the first star, share a thin wafer and wishes, and set one chair for someone who may not come."},"readingMinutes":1,"sections":{"ar":[{"heading":"بداية العشاء مع أول نجمة","paragraphs":["يبدأ عشاء فيغيلية في بولندا عند ظهور أول نجمة في السماء، فيتقاسم الحاضرون رقاقة رقيقة تُسمّى أوبفاتيك ويتبادلون التمنيات.","المائدة خالية من اللحم وغالباً ما تحمل اثني عشر طبقاً، بينها الكارب والرنجة وحساء الفطر والبيروغي والملفوف ومشروب الفواكه المجففة.","يُترك مقعد زائد لضيف غير متوقع أو فرد غائب من الأسرة، ويُوضع التبن أحياناً تحت مفرش المائدة تذكيراً بالمذود."]},{"heading":"الهدايا والعيد في اليوم التالي","paragraphs":["تُفتح الهدايا بعد العشاء، أما يوم 25 ديسمبر فهو عيد الكنيسة، واليومان 25 و26 ديسمبر عطلتان رسميتان في بولندا.","يعود هذا التقليد في الثقافة النبيلة البولندية إلى القرنين الثامن عشر والتاسع عشر، وتقوّى مع الحركات الرومانسية الوطنية، مع تنوّعات إقليمية قوية.","تختلف عدد الأطباق وقائمة الطعام بحسب الأسرة والمنطقة، وكثير من البيوت اليوم تبسّط العشاء، كما تتباين العادة بين الأجيال والمناطق."]}],"de":[{"heading":"Beginn beim ersten Stern","paragraphs":["Das Wigilia-Mahl beginnt in Polen, sobald der erste Stern am Himmel erscheint; dann teilen die Anwesenden dünne Weihnachtsoblaten, genannt Opłatek, und tauschen Wünsche aus.","Der Tisch bleibt fleischlos und trägt oft zwölf Gerichte, darunter Karpfen, Hering, Pilzsuppe, Pierogi, Sauerkraut und Kompott aus Trockenfrüchten.","Ein zusätzlicher Platz bleibt für einen unerwarteten Gast oder ein abwesendes Familienmitglied frei, und manchmal liegt Heu unter dem Tischtuch zur Erinnerung an die Krippe."]},{"heading":"Geschenke und der Feiertag danach","paragraphs":["Nach dem Essen werden die Geschenke geöffnet; der 25. Dezember ist der kirchliche Feiertag, und der 25. und 26. Dezember sind in Polen gesetzliche Feiertage.","Der Brauch ist in der polnischen Adelskultur des 18. und 19. Jahrhunderts belegt und wurde durch nationalromantische Bewegungen gestärkt, mit starken regionalen Varianten.","Zahl der Gerichte und genaue Speisenfolge unterscheiden sich je nach Familie und Region, viele Haushalte vereinfachen das Mahl heute, und auch zwischen Generationen und Regionen gibt es Unterschiede."]}],"en":[{"heading":"The supper starts with a star","paragraphs":["Wigilia, the Polish Christmas Eve supper, begins when the first star appears, and it opens with the sharing of opłatek, a thin Christmas wafer, and mutual wishes.","The meal is traditionally meatless and often has twelve dishes, including carp, herring, mushroom soup, pierogi, sauerkraut and dried-fruit compote.","An extra place is set for an unexpected guest or an absent family member, and hay is sometimes placed under the tablecloth in memory of the manger."]},{"heading":"Presents, then the church feast","paragraphs":["Gifts are opened after supper, and Christmas Day is the church feast; 25 and 26 December are public holidays in Poland.","The custom is documented in Polish gentry culture from the eighteenth and nineteenth centuries and was strengthened by national-romantic movements, with strong regional variants.","The number of dishes and the exact menu vary by family and region, and many households now simplify the meal, with differences also showing between generations and regions."]}]},"context":{"countries":["PL"],"region":"Poland (nationwide)","continent":"europe","languages":["pl"],"period":"contemporary"},"tags":["traditions","Poland (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Wigilia","de":"Wigilia","en":"Wigilia"},"url":"https://en.wikipedia.org/wiki/Wigilia","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Polish cuisine","de":"Polish cuisine","en":"Polish cuisine"},"url":"https://en.wikipedia.org/wiki/Polish_cuisine","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عند الغسق في 24 ديسمبر، تتقاسم أسرة في كراكوف رقاقة أوبفاتيك والتمنيات، وتأكل اثني عشر طبقاً بلا لحم، وتترك كرسياً فارغاً، ثم تفتح الهدايا تحت الشجرة.","de":"In der Abenddämmerung des 24. Dezember teilt eine Familie in Krakau Opłatek und Wünsche, isst zwölf fleischlose Gerichte, lässt einen Stuhl leer und öffnet danach die Geschenke unter dem Baum.","en":"At dusk on 24 December, a family in Kraków shares opłatek and wishes, eats twelve meatless dishes, leaves one chair empty and then opens presents under the tree."},"misunderstanding":{"ar":"يُظن أحياناً أن الكرسي الفارغ مجرد تفصيل شكلي، لكنه في الواقع دعوة مفتوحة للضيف غير المتوقع وتذكير بمن غاب.","de":"Manchmal gilt der leere Stuhl nur als Formsache, doch tatsächlich ist er eine offene Einladung für unerwartete Gäste und eine Erinnerung an Abwesende.","en":"The empty chair is sometimes taken as a mere formality, but it is really an open invitation to an unexpected guest and a reminder of someone absent."},"comparison":{"ar":"يشبه هذا العشاء أعياد الميلاد في بلدان أخرى من حيث لمّ شمل الأسرة، لكن غياب اللحم وتعدد الأطباق وطقس الرقاقة يمنحانه طابعه البولندي.","de":"Das Mahl ähnelt Weihnachtsfesten anderer Länder, weil die Familie zusammenkommt, doch Fleischlosigkeit, zwölf Gerichte und der Oblatenritus geben ihm sein polnisches Gepräge.","en":"The supper resembles Christmas celebrations elsewhere in bringing family together, yet its meatless table, twelve dishes and wafer ritual give it a distinctly Polish shape."}},{"id":"tra-048","version":2,"slug":"malanka-masked-carols-in-the-old-new-year","contentType":"scene","category":"traditions","title":{"ar":"مالانكا: أقنعة وتراتيل في رأس السنة القديمة","de":"Malanka: Masken und Lieder zum alten Neujahr","en":"Malanka: Masked Carols in the Old New Year"},"deck":{"ar":"في غرب أوكرانيا، تخرج مجموعات متنكرة من بيت إلى بيت ليلة 13-14 يناير، تجمع بين التراتيل والمسرحيات الهزلية لتجديد العام.","de":"In der Westukraine ziehen in der Nacht vom 13. auf den 14. Januar maskierte Gruppen von Haus zu Haus, singen Lieder und spielen kurze Szenen.","en":"In western Ukraine, masked groups go from house to house on the night of 13–14 January, blending carols and short comic plays to renew the year."},"teaser":{"ar":"احتفال مالانكا يجمع بين الأقنعة والتراتيل والمسرحيات القصيرة، ويُحيي ذكرى القديسة ميلانيا في رأس السنة اليوليانية.","de":"Malanka verbindet Masken, Lieder und kurze Theaterstücke und erinnert an die heilige Melania zum julianischen Neujahr.","en":"Malanka brings together masks, carols and short plays, honoring Saint Melania on the Julian calendar's New Year."},"readingMinutes":1,"sections":{"ar":[{"heading":"ليلة مالانكا: تراتيل وأقنعة","paragraphs":["تقع ليلة مالانكا في 13-14 يناير حسب التقويم اليولياني، وهي رأس السنة الشعبية الأوكرانية، سُميت على اسم القديسة ميلانيا. تخرج مجموعات من القرويين المتنكرين من بيت إلى بيت وهم يرددون تراتيل تسمى شتشيدريفكي ويؤدون مسرحيات هزلية قصيرة، وتكون شخصية العنزة (كوزا) ومالانكا محوريتين.","تتنوع الأزياء بين الدب والغجري والطبيب والأجداد حسب المنطقة، وفي بعض القرى يؤدي دور مالانكا رجل يرتدي زي امرأة. يتزامن الاحتفال مع شتشيدري فيتشير، الأمسية السخية في 13 يناير، حيث تقيم العائلات عشاءً احتفاليًا قبل التجول بالتراتيل."]},{"heading":"من الحظر إلى الإحياء","paragraphs":["خلال الفترة السوفيتية، ثُبطت هذه الطقوس، لكنها عادت بعد عام 1991، خاصة في غرب أوكرانيا حيث تتنافس مجموعات القرى في العروض. يختلف شكل الاحتفال وأسلوبه بين الأجيال والمناطق، كما تتباين تواريخه وأشكاله بعد إصلاح التقويم الأخير في أوكرانيا، وتختلف نسخ الشتات اختلافًا كبيرًا."]}],"de":[{"heading":"Die Nacht der Malanka: Lieder und Masken","paragraphs":["Malanka fällt auf die Nacht vom 13. auf den 14. Januar nach dem julianischen Kalender und ist das ukrainische Volksneujahr, benannt nach der heiligen Melania. Gruppen maskierter Dorfbewohner gehen von Haus zu Haus, singen sogenannte Shchedrivky und führen kurze komische Stücke auf; die Ziege (Koza) und die Figur Malanka stehen im Mittelpunkt.","Die Kostüme von Bär, Zigeuner, Arzt und Großeltern variieren je nach Region, und in manchen Dörfern wird Malanka von einem als Frau verkleideten Mann gespielt. Der Brauch überschneidet sich mit Shchedry Vechir, dem großzügigen Abend des 13. Januar, an dem Familien vor dem Umzug ein festliches Abendessen halten."]},{"heading":"Vom Verbot zur Wiederbelebung","paragraphs":["In der Sowjetzeit wurde das Ritual unterdrückt und nach 1991 wiederbelebt, besonders in der Westukraine, wo Dorfgruppen in Aufführungen gegeneinander antreten. Die Formen und Daten sind nach der jüngsten Kalenderreform umstritten, und regionale sowie Diaspora-Varianten unterscheiden sich erheblich; auch zwischen den Generationen gibt es Unterschiede in der Gestaltung."]}],"en":[{"heading":"The Night of Malanka: Carols and Masks","paragraphs":["Malanka falls on the night of 13 to 14 January in the Julian calendar and is the Ukrainian folk new year, named after Saint Melania. Groups of masked villagers go from house to house with carols called shchedrivky and short comic plays; the Goat, Koza, and a character called Malanka are central figures.","Costumes of bear, gypsy, doctor and grandparents vary by region, and in some villages Malanka is played by a man dressed as a woman. The ritual overlaps with Shchedry Vechir, the generous evening of 13 January, when families hold a festive dinner before the carolling."]},{"heading":"From Suppression to Revival","paragraphs":["The ritual was discouraged during the Soviet period and revived after 1991, especially in western Ukraine, where village groups compete in performances. Malanka's dates and forms are contested after Ukraine's recent calendar reform, and regional and diaspora versions differ considerably; generational differences also shape how the custom is performed today."]}]},"context":{"countries":["UA"],"region":"western Ukraine","continent":"europe","languages":["uk"],"period":"contemporary"},"tags":["traditions","western Ukraine"],"sources":[{"organization":"Wikipedia","title":{"ar":"Malanka","de":"Malanka","en":"Malanka"},"url":"https://en.wikipedia.org/wiki/Malanka","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Koliada","de":"Koliada","en":"Koliada"},"url":"https://en.wikipedia.org/wiki/Koliada","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في قرية كارباتية، تدق مجموعة متنكرة بابًا، وتؤدي مشهدًا هزليًا قصيرًا مع العنزة، وتجمع الحلوى بينما يضحك أهل البيت ويدعونهم للدخول.","de":"In einem Karpatendorf klopft eine maskierte Gruppe an eine Tür, spielt eine kurze komische Szene mit der Ziege und sammelt Süßigkeiten, während die Hausbewohner lachen und sie hereinbitten.","en":"In a Carpathian village, a masked group bangs on a door, performs a short comic scene with the Goat, and collects sweets as the household laughs and invites them in."},"misunderstanding":{"ar":"يُفهم مالانكا أحيانًا على أنه مجرد حفلة تنكرية، لكنه في جوهره طقس تراتيل ومسرح شعبي يجدد العلاقات الاجتماعية في القرية.","de":"Malanka wird manchmal als bloße Kostümparty missverstanden, ist aber im Kern ein Lied- und Volkstheaterritual, das die sozialen Beziehungen im Dorf erneuert.","en":"Malanka is sometimes mistaken for a mere costume party, but it is essentially a carolling and folk-theater ritual that renews village social ties."},"comparison":{"ar":"يشبه مالانكا في بنيته احتفالات الشتاء الأوروبية الأخرى التي تمزج الأقنعة والتراتيل، لكنه يتميز بشخصية العنزة والمسرحيات الهزلية وارتباطه الوثيق بعشاء عائلي في الأمسية السخية.","de":"In seiner Struktur ähnelt Malanka anderen europäischen Winterbräuchen, die Masken und Lieder verbinden, zeichnet sich aber durch die Ziegenfigur, die komischen Stücke und die enge Verbindung zum Familienessen am großzügigen Abend aus.","en":"Structurally, Malanka resembles other European winter customs that mix masks and carols, but it stands out for its Goat figure, comic plays and close tie to a family dinner on the generous evening."}},{"id":"tra-049","version":2,"slug":"maslenitsa-butter-blini-and-the-burning-of-winter","contentType":"note","category":"nature-and-seasons","title":{"ar":"ماسلينيتسا: زبدة وفطائر ووداع الشتاء","de":"Maslenitsa: Butter, Blini und der Abschied vom Winter","en":"Maslenitsa: butter, blini and the burning of winter"},"deck":{"ar":"أسبوع قبل الصوم الكبير تمتلئ فيه الموائد بالفطائر المستديرة وتُحرَق دُمية قشّية ترمز إلى رحيل الشتاء.","de":"Eine Woche vor der Fastenzeit füllen sich die Tische mit runden Blini, und eine Strohfigur brennt als Zeichen des scheidenden Winters.","en":"In the week before Great Lent, tables fill with round blini and a straw effigy burns as a sign that winter is leaving."},"teaser":{"ar":"في روسيا يُعيش هذا الأسبوع بين الزحلقة على الجليد وحلقات الفطائر والزيارات العائلية، ثم تُودَّع الشمس والشتاء معًا.","de":"In Russland liegt zwischen Schlittenfahren, Blini-Runden und Familienbesuchen eine ganze Woche, in der man Sonne und Winter gemeinsam verabschiedet.","en":"Across Russia, a whole week passes between sledding, rounds of blini and family visits, as people see off both the sun and the cold season."},"readingMinutes":1,"sections":{"ar":[{"heading":"أيام لها أسماء وأدوار","paragraphs":["يمتد ماسلينيتسا أسبوعًا كاملًا قبل الصوم الكبير، ولكل يوم فيه اسم ودور: من لقاء الاثنين إلى الخميس الواسع وأحد المغفرة، حين يطلب الناس المغفرة من الأقارب والأصدقاء.","تُقدَّم فيه الأطعمة الحليبية بينما يُستبعد اللحم قبل الصوم، فتُؤكل الفطائر مع الزبدة والقشدة الحامضة والكافيار والمربّى أو السمك.","يختلف العيش في هذا الأسبوع بين المدينة والريف، كما تتباين العادة بين الأجيال: فبعض العائلات الشابة تكتفي بالمعرض والحفلات، بينما تحافظ الأجيال الأكبر على الزيارات المنزلية."]},{"heading":"الشمس والنار والوداع","paragraphs":["تحمل الفطائر المستديرة والنار الرمزية الشمسية ورمزية الربيع، وقد امتزجت جزئيًا بالتقويم الأرثوذكسي.","أعادت الدولة السوفييتية تفسير الأسبوع كوداع دنيوي للشتاء، فبقي الاحتفال حاضرًا لكن بمعنى مختلف.","في القرى تستمر الزحلقة على الجليد وألعاب حصون الثلج والزيارات العائلية، وفي المدن تُقام المعارض والحفلات."]}],"de":[{"heading":"Tage mit Namen und Aufgaben","paragraphs":["Maslenitsa dauert die Woche vor der Großen Fastenzeit, und jeder Tag hat einen Namen und eine Rolle – vom Treffen am Montag über den weiten Donnerstag bis zum Vergebungssonntag, an dem Menschen Verwandte und Freunde um Verzeihung bitten.","Milchspeisen sind erlaubt, Fleisch ist vor der Fastenzeit schon ausgeschlossen, deshalb isst man Blini mit Butter, Sauerrahm, Kaviar, Marmelade oder Fisch.","Wie diese Woche gelebt wird, unterscheidet sich zwischen Stadt und Dorf und ebenso zwischen den Generationen: Jüngere bleiben oft beim Jahrmarkt und Konzert, Ältere pflegen die Besuche zu Hause."]},{"heading":"Sonne, Feuer und Abschied","paragraphs":["Die runden Blini und das Feuer tragen vorchristliche Sonnen- und Frühlingssymbolik, die teilweise in den orthodoxen Kalender aufgenommen wurde.","Der sowjetische Staat deutete die Woche als weltliches Verabschieden des Winters um, sodass das Feiern blieb, aber anders gedeutet wurde.","Auf dem Land halten sich Schlittenfahrten, Spiele um Schneefestungen und Familienbesuche, in den Städten gibt es Jahrmärkte und Konzerte."]}],"en":[{"heading":"Days with names and roles","paragraphs":["Maslenitsa runs through the week before Great Lent, and each day has a name and a role, from the Monday meeting to Wide Thursday and Forgiveness Sunday, when people ask forgiveness of relatives and friends.","Dairy foods are allowed while meat is already excluded before Lent, so blini are eaten with butter, sour cream, caviar, jam or fish.","How the week is lived varies between city and village and across generations: younger families often stay with the fair and concerts, while older relatives keep up home visits."]},{"heading":"Sun, fire and farewell","paragraphs":["The round blini and the bonfire carry pre-Christian sun and spring symbolism, partly absorbed into the Orthodox calendar.","The Soviet state reframed the week as a secular seeing-off of winter, so the celebration remained but carried a different meaning.","In villages, sledding, snow-fort games and family visits persist, while cities mark the week with fairs and concerts."]}]},"context":{"countries":["RU"],"region":"Russia (nationwide)","continent":"europe","languages":["ru"],"period":"contemporary"},"tags":["nature-and-seasons","Russia (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Maslenitsa","de":"Maslenitsa","en":"Maslenitsa"},"url":"https://en.wikipedia.org/wiki/Maslenitsa","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Russian traditions","de":"Russian traditions","en":"Russian traditions"},"url":"https://en.wikipedia.org/wiki/Russian_traditions","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في أحد المغفرة تأكل العائلة الفطائر مع القشدة الحامضة، ويطلب كل واحد المغفرة من الآخر، وفي المساء تُحرَق دُمية قشّية في حقل خارج القرية.","de":"Am Vergebungssonntag isst eine Familie Blini mit Sauerrahm, bittet einander um Verzeihung, und am Abend brennt draußen vor dem Dorf eine Strohfigur im Feld.","en":"On Forgiveness Sunday a family eats blini with sour cream, asks each other's forgiveness, and in the evening a straw effigy burns in a field outside the village."},"misunderstanding":{"ar":"يظنّ بعض الزوار أن ماسلينيتسا مناسبة دينية بحتة، لكن كثيرين يعيشونها اليوم كمعرض شعبي ووداع موسمي للشتاء.","de":"Manche Besucher halten Maslenitsa für ein rein religiöses Fest, doch viele erleben es heute als Volksfest und saisonalen Abschied vom Winter.","en":"Some visitors assume Maslenitsa is purely religious, but many Russians today treat it as a folk fair and a seasonal goodbye to winter."},"comparison":{"ar":"يشبه هذا الأسبوع أعياد نهاية الشتاء في مجتمعات أخرى، حيث يجتمع الطعام واللعب الجماعي على عتبة موسم جديد.","de":"Ähnlich wie andere Winterausklänge verbindet diese Woche gemeinsames Essen und Spiel am Übergang in eine neue Jahreszeit.","en":"Like other end-of-winter customs, this week joins shared food and play at the threshold of a new season."}},{"id":"tra-050","version":2,"slug":"the-altar-at-the-end-of-october-dia-de-muertos","contentType":"note","category":"traditions","title":{"ar":"مذبح في نهاية أكتوبر: يوم الموتى","de":"Der Altar am Ende des Oktobers: Día de Muertos","en":"The altar at the end of October: Día de Muertos"},"deck":{"ar":"في الأول والثاني من نوفمبر تفتح العائلات في وسط وجنوب المكسيك بيوتها لمن تعتقد أنهم يعودون للزيارة، فتضع صورهم وأطعمتهم المفضلة.","de":"Am 1. und 2. November öffnen Familien in Mittel- und Südmexiko ihre Häuser für die Toten, die sie zu Besuch glauben, und stellen deren Fotos und Lieblingsspeisen auf.","en":"On 1 and 2 November families across central and southern Mexico open their homes to the dead they believe return to visit, setting out photographs and favourite foods."},"teaser":{"ar":"بين مذابح البيوت ومقابر تُزيَّن وتُسهر فيها العائلات، يحمل يوم الموتى وجوهاً محلية كثيرة، من ميتشواكان إلى أواكساكا إلى العاصمة.","de":"Zwischen Hausaltären und geschmückten Gräbern, an denen Familien die Nacht verbringen, zeigt sich der Día de Muertos von Michoacán bis Oaxaca und Mexiko-Stadt sehr verschieden.","en":"Between home altars and decorated graves where families spend the night, Día de Muertos looks different from Michoacán to Oaxaca to Mexico City."},"readingMinutes":1,"sections":{"ar":[{"heading":"بيوت تُفتح للزائرين","paragraphs":["يُحتفل بيوم الموتى في الأول والثاني من نوفمبر، مع امتدادات إقليمية في بعض المناطق، حين تعتقد العائلات أن الموتى يعودون لزيارة الأحياء.","تُقام في البيوت، وأحياناً في المقابر، مذابح تُسمّى أوفينداس، تحمل صوراً وأطعمة ومشروبات مفضلة وأزهار الأقحوان المخملي والشموع وأعلاماً ورقية وجماجم سكرية.","في بعض المجتمعات تنظّف العائلات القبور وتزيّنها وتبيت الليل في المقبرة، ولكل من ميتشواكان وأواكساكا ومكسيكو سيتي تقاليدها المميزة."]},{"heading":"جذور مختلطة وصورة ساخرة","paragraphs":["يمتزج المهرجان بممارسات الأسلاف في أمريكا الوسطى مع عيدي جميع القديسين والمؤمنين الكاثوليكيين، وقد أدرجته اليونسكو في قائمة التراث غير المادي عام 2008.","شخصية لا كاترينا، الهيكل العظمي الأنيق، أتت من مطبوعات ساخرة لخوسيه غوادالوبي بوسادا في مطلع القرن العشرين، لا من لباس ما قبل الإسبان.","تختلف الممارسة بين الأجيال والمناطق: فبعض العائلات الشابة تحييها في المدينة بأسلوب احتفالي، بينما تبقى في بلدات أخرى quieter وأكثر بيتوتية."]}],"de":[{"heading":"Häuser, die sich für Besuch öffnen","paragraphs":["Der Día de Muertos wird am 1. und 2. November gefeiert, mit regionalen Erweiterungen, wenn Familien glauben, dass die Toten zu Besuch zu den Lebenden zurückkehren.","Ofrendas, Altäre in Häusern und manchmal auf Friedhöfen, tragen Fotografien, Lieblingsspeisen und -getränke, Ringelblumen, Kerzen, Papel Picado und Zucker-Totenköpfe.","In manchen Gemeinden reinigen und schmücken Familien die Gräber und verbringen die Nacht auf dem Friedhof; Michoacán, Oaxaca und Mexiko-Stadt haben jeweils eigene Traditionen."]},{"heading":"Gemischte Wurzeln und eine satirische Figur","paragraphs":["Das Fest verbindet mesoamerikanische Ahnenpraktiken mit den katholischen Allerheiligen- und Allerseelentagen; 2008 nahm die UNESCO es in die Liste des immateriellen Erbes auf.","La Catrina, das elegante Skelett, stammt aus satirischen Drucken von José Guadalupe Posada im frühen 20. Jahrhundert, nicht aus vorspanischer Kleidung.","Die Praxis variiert je nach Region und Generation: Manche junge Familien feiern in der Stadt laut und öffentlich, in anderen Orten bleibt es stiller und häuslicher."]}],"en":[{"heading":"Homes that open for visitors","paragraphs":["Día de Muertos is celebrated on 1 and 2 November, with regional extensions, when families believe the dead return to visit the living.","Ofrendas, altars built in homes and sometimes in cemeteries, hold photographs, favourite foods and drinks, marigolds, candles, papel picado and sugar skulls.","In some communities families clean and decorate graves and spend the night at the cemetery; Michoacán, Oaxaca and Mexico City each have distinct traditions."]},{"heading":"Mixed roots and a satirical figure","paragraphs":["The festival mixes Mesoamerican ancestor practices with Catholic All Saints' and All Souls' days, and UNESCO inscribed it on its intangible heritage list in 2008.","La Catrina, the elegant skeleton, comes from the satirical prints of José Guadalupe Posada in the early twentieth century, not from pre-Hispanic dress.","Practice shifts with region and generation: some younger families celebrate loudly and publicly in the city, while in other towns it stays quieter and more domestic."]}]},"context":{"countries":["MX"],"region":"central and southern Mexico","continent":"north-america","languages":["es"],"period":"contemporary"},"tags":["traditions","central and southern Mexico"],"sources":[{"organization":"Wikipedia","title":{"ar":"Day of the Dead","de":"Day of the Dead","en":"Day of the Dead"},"url":"https://en.wikipedia.org/wiki/Day_of_the_Dead","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Calavera","de":"Calavera","en":"Calavera"},"url":"https://en.wikipedia.org/wiki/Calavera","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عائلة في أواكساكا تبني أوفيندا عليها صورة الجدة وطبق من المولي وأزهار الأقحوان وكأس من الميزكال، وتملأ رائحة الكوبال الغرفة.","de":"Eine Familie in Oaxaca baut eine Ofrenda mit dem Foto der Großmutter, einem Teller Mole, Ringelblumen und einem Glas Mezcal; der Duft von Copal füllt den Raum.","en":"A family in Oaxaca builds an ofrenda with a grandmother's photograph, a plate of mole, marigolds and a glass of mezcal, and the scent of copal fills the room."},"misunderstanding":{"ar":"يوم الموتى ليس هالوين مكسيكياً: فهو متنوّع إقليمياً، وجزئياً ديني، وفي بعض البلدات أهدأ وأكثر بيتوتية من نسخته الشارعية.","de":"Día de Muertos ist nicht der mexikanische Halloween: Er ist regional verschieden, teils religiös und in manchen Orten stiller und häuslicher als die Straßenversion.","en":"Día de Muertos is not Mexican Halloween: it is regionally varied, partly religious, and in some towns quieter and more domestic than the street version."},"comparison":{"ar":"حيث تُقام المذابح في البيوت تبقى الذكرى شأناً عائلياً، وحيث تُزيَّن المقابر وتُسهر تصبح الشارع امتداداً للبيت؛ والتقاليد تتباين بين الأجيال والمناطق.","de":"Wo Altäre in Häusern stehen, bleibt das Gedenken Familiensache; wo Gräber geschmückt und nächtlich besucht werden, wird der Friedhof zum erweiterten Wohnzimmer.","en":"Where altars stand in homes, remembrance stays a family affair; where graves are decorated and kept overnight, the cemetery becomes an extension of the living room."}},{"id":"tra-051","version":2,"slug":"quinceanera-fifteen-a-mass-and-a-first-dance","contentType":"note","category":"family-and-friendship","title":{"ar":"الكينسيانيرا: خمسة عشر عامًا وقداس ورقصة أولى","de":"Quinceañera: fünfzehn, eine Messe und der erste Tanz","en":"Quinceañera: fifteen, a Mass and a first dance"},"deck":{"ar":"احتفال بلوغ الفتاة الخامسة عشرة في المكسيك، يجمع بين القداس والرقصة والتقاليد العائلية.","de":"Ein Fest zum 15. Geburtstag in Mexiko, das Messe, Tanz und Familientraditionen verbindet.","en":"A coming-of-age celebration in Mexico that blends a Catholic Mass, a waltz and family traditions."},"teaser":{"ar":"في المكسيك، تحتفل الفتيات ببلوغهن الخامسة عشرة بحفل قداس ورقصة، تعبيرًا عن الانتقال إلى سن الرشد.","de":"In Mexiko feiern Mädchen ihren 15. Geburtstag mit einer Messe und einem Tanz, als Übergang ins Erwachsenenalter.","en":"In Mexico, girls celebrate their fifteenth birthday with a Mass and a dance, marking the transition to adulthood."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقوس الانتقال","paragraphs":["تحتفل الكينسيانيرا بعيد ميلاد الفتاة الخامسة عشر، غالبًا بقداس شكر كاثوليكي وحفلة، وهي احتفال بلوغ سن الرشد في جميع أنحاء المكسيك وأمريكا اللاتينية.","يشمل الاحتفال محكمة شرف من الأصدقاء والشامبيلانيس، ورقصة الفالس، وتغيير الأحذية المسطحة إلى الكعب العالي، والرقصة الأولى مع الأب."]},{"heading":"تنوع الممارسات","paragraphs":["غالبًا ما يكون القداس والبركة محوريين، رغم أن الحفلة قد تكون دنيوية إلى حد كبير؛ تختار بعض العائلات رحلة أو وجبة أصغر بدلاً من حدث كبير. تمتزج التقاليد بعناصر استعمارية إسبانية وسكانية أصلية وكاثوليكية، وفي المجتمعات المكسيكية الأمريكية غالبًا ما تختلط مع حفل Sweet 16 الأمريكي. الفستان ونخب البرينديس والدمية الأخيرة، última muñeca، سمات مألوفة، رغم قوة المتغيرات المحلية والعائلية. يختلف الاحتفال أيضًا حسب المنطقة والجيل، فبعض العائلات الشابة تفضل احتفالات أصغر أو أكثر شخصية."]}],"de":[{"heading":"Rituale des Übergangs","paragraphs":["Eine Quinceañera markiert den 15. Geburtstag eines Mädchens, meist mit einer katholischen Dankmesse und einer Party, und ist ein Coming-of-Age-Fest in ganz Mexiko und Lateinamerika.","Die Feier umfasst einen Hofstaat aus Freunden und Chambelanes, einen Walzer, den Wechsel von flachen Schuhen zu Absätzen und einen ersten Tanz mit dem Vater."]},{"heading":"Vielfalt der Praktiken","paragraphs":["Die Messe und der Segen sind oft zentral, obwohl die Party weitgehend säkular sein kann; manche Familien wählen eine Reise oder ein kleineres Essen statt eines großen Events. Die Tradition verbindet spanisch-koloniale, indigene und katholische Elemente und vermischt sich in mexikanisch-amerikanischen Gemeinschaften oft mit dem amerikanischen Sweet 16. Das Kleid, der Brindis-Trinkspruch und die letzte Puppe, die última muñeca, sind bekannte Merkmale, wobei lokale und familiäre Varianten stark sind. Die Feier variiert auch regional und generationell, da jüngere Familien oft kleinere oder persönlichere Feiern bevorzugen."]}],"en":[{"heading":"Rituals of transition","paragraphs":["A quinceañera marks a girl's fifteenth birthday, usually with a Catholic thanksgiving Mass and a party, and is a coming-of-age celebration across Mexico and Latin America.","The celebration includes a court of honour of friends and chambelanes, a waltz, a change from flat shoes to heels and a first dance with the father."]},{"heading":"Variations in practice","paragraphs":["The Mass and blessing are often central, though the party may be largely secular; some families choose a trip or a smaller meal instead of a large event. The tradition blends Spanish colonial, Indigenous and Catholic elements, and in Mexican-American communities it often mixes with the American Sweet 16. The dress, the brindis toast and the last doll, the última muñeca, are familiar features, though local and family variants are strong. The celebration also varies by region and generation, with younger families often opting for smaller or more personal events."]}]},"context":{"countries":["MX"],"region":"Mexico (nationwide)","continent":"north-america","languages":["es"],"period":"contemporary"},"tags":["family-and-friendship","Mexico (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Quinceañera","de":"Quinceañera","en":"Quinceañera"},"url":"https://en.wikipedia.org/wiki/Quincea%C3%B1era","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Mexico","de":"Culture of Mexico","en":"Culture of Mexico"},"url":"https://en.wikipedia.org/wiki/Culture_of_Mexico","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في قاعة أبرشية في مونتيري، تصل الفتاة المحتفى بها بفستان واسع، ويباركها الكاهن، وبعد القداس تغير حذاءها وترقص الفالس مع والدها والمحكمة.","de":"In einem Gemeindesaal in Monterrey kommt die Geburtstagsfeiernde in einem weiten Kleid an, der Priester segnet sie, und nach der Messe wechselt sie die Schuhe und tanzt einen Walzer mit ihrem Vater und dem Hofstaat.","en":"In a Monterrey parish hall, the birthday girl arrives in a wide dress, the priest blesses her, and after Mass she changes shoes and dances a waltz with her father and the court."},"misunderstanding":{"ar":"ليس كل فتاة مكسيكية لديها كينسيانيرا، فالتكاليف قد تكون مرتفعة، وكثير من العائلات تحتفل بشكل أبسط أو لا تحتفل على الإطلاق.","de":"Nicht jedes mexikanische Mädchen hat eine Quinceañera, die Kosten können hoch sein, und viele Familien feiern einfacher oder gar nicht.","en":"Not every Mexican girl has a quinceañera, costs can be high, and many families celebrate more simply or not at all."},"comparison":{"ar":"بينما تركز الكينسيانيرا على القداس والرقصة الأولى مع الأب، فإن حفلات عيد الميلاد الخامس عشر في cultures أخرى قد تركز على الحفلة فقط.","de":"Während die Quinceañera Messe und ersten Tanz mit dem Vater betont, konzentrieren sich 15. Geburtstagsfeiern in anderen Kulturen oft nur auf die Party.","en":"While the quinceañera emphasizes the Mass and first dance with the father, 15th birthday parties in other cultures often focus only on the party."}},{"id":"tra-052","version":2,"slug":"potlatch-the-feast-where-wealth-is-given-away","contentType":"note","category":"social-behaviour","title":{"ar":"البوتلاتش: وليمة يُهدى فيها الثراء","de":"Potlatch: das Fest des Verschenkens","en":"Potlatch: the feast where wealth is given away"},"deck":{"ar":"احتفال ساحلي يوزّع فيه المضيفون الطعام والبضائع ويعلنون حقوقهم الموروثة أمام الشهود.","de":"Ein Küstenfest, bei dem Gastgeber Essen und Güter verteilen und ihre ererbten Rechte vor Zeugen verkünden.","en":"A coastal ceremony where hosts distribute food and goods and announce inherited rights before witnesses."},"teaser":{"ar":"بين شعوب الساحل الشمالي الغربي للمحيط الهادئ، ليس جمع الثروة غاية بحد ذاته، بل توزيعها أمام الشهود هو ما يمنح المكانة.","de":"An der Nordwestküste des Pazifik ist Reichtum nicht zum Horten da: Wer vor Zeugen gibt, festigt seinen Status und ehrt die Toten.","en":"On the Pacific Northwest coast, wealth is not for hoarding: giving it away in front of witnesses is what confirms status and honours the dead."},"readingMinutes":1,"sections":{"ar":[{"heading":"وليمة تُثبت المكانة","paragraphs":["البوتلاتش وليمة احتفالية وممارسة لإهداء الأشياء بين الشعوب الأصلية في الساحل الشمالي الغربي للمحيط الهادئ، ومنها كواكواكاواكوال وتلينغيت وهايدا ونوو-تشا-نولث. يوزّع المضيفون الطعام والبضائع على الضيوف، ويعرضون حقوقهم الموروثة في الأسماء والأغاني والأقنعة والتواريخ، فيثبت الحدث المكانة ويكرّم الموتى.","تفهم الأنثروبولوجيا المبكرة هذا السلوك أحياناً كاستهلاك استعراضي، لكنه أقرب إلى مؤسسة قانونية واجتماعية تنظّم الألقاب والزواج والتبادل.","تختلف البروتوكولات بين الأمم، وبعض الاحتفالات مقيّدة لا تُقام أمام الجمهور، كما تتباين الممارسة بين الأجيال والمناطق الساحلية."]},{"heading":"الحظر والعودة","paragraphs":["حظرت الحكومة الكندية البوتلاتش عام 1885، وأدت ملاحقات مثل اعتقال ضيوف الزعيم دان كرامن عام 1921 إلى مصادرة الأزياء والرموز الاحتفالية، ثم رُفع الحظر عام 1951.","بقي الاحتفال حياً في السر، وما زال ممارسة معاصرة، وقد أعادت المتاحف والحكومات في العقود الأخيرة كثيراً من تلك الرموز إلى أصحابها."]}],"de":[{"heading":"Ein Fest, das Rang belegt","paragraphs":["Potlatch ist ein zeremonielles Fest und eine Praxis des Schenkens bei indigenen Völkern der Nordwestküste des Pazifik, darunter Kwakwakaʼwakw, Tlingit, Haida und Nuu-chah-nulth. Gastgeber verteilen Speisen und Güter an Gäste und zeigen ererbte Rechte an Namen, Liedern, Masken und Geschichten; so bestätigt das Ereignis Status und ehrt die Toten.","Frühe Anthropologen deuteten dies als demonstrativen Konsum, doch besser versteht man es als rechtliche und soziale Institution, die Titel, Heirat und Gegenseitigkeit regelt.","Die Protokolle unterscheiden sich von Nation zu Nation, manche Zeremonien sind nicht öffentlich, und die Praxis variiert regional und zwischen Generationen."]},{"heading":"Verbot und Rückkehr","paragraphs":["1885 verbot die kanadische Regierung den Potlatch; Verfahren wie die Verhaftung der Gäste von Häuptling Dan Cranmer 1921 führten zur Beschlagnahme von Regalia, 1951 wurde das Verbot aufgehoben.","Die Zeremonie überlebte im Verborgenen und ist lebendige Praxis; Museen und Regierungen haben in den letzten Jahrzehnten Regalia zurückgegeben."]}],"en":[{"heading":"A feast that validates standing","paragraphs":["Potlatch is a ceremonial feast and gift-giving practice among Indigenous peoples of the Pacific Northwest, including the Kwakwakaʼwakw, Tlingit, Haida and Nuu-chah-nulth. Hosts distribute food and goods to guests and display inherited rights to names, songs, masks and histories, so the event validates status and honours the dead.","Early anthropologists read it as conspicuous consumption, but it is better understood as a legal and social institution regulating titles, marriage and reciprocity.","Protocols differ between Nations, some ceremonies are restricted rather than public, and practice varies by region and generation."]},{"heading":"Ban and return","paragraphs":["The Canadian government banned potlatch in 1885, and prosecutions such as the 1921 arrest of Chief Dan Cranmer's guests led to confiscation of regalia; the ban was lifted in 1951.","The ceremony survived underground and remains a living practice; museums and governments have repatriated regalia in recent decades."]}]},"context":{"countries":["CA","US"],"region":"Pacific Northwest coast","community":"Kwakwakaʼwakw and other First Nations","continent":"north-america","languages":[],"period":"contemporary"},"tags":["social-behaviour","Pacific Northwest coast"],"sources":[{"organization":"Wikipedia","title":{"ar":"Potlatch","de":"Potlatch","en":"Potlatch"},"url":"https://en.wikipedia.org/wiki/Potlatch","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Kwakwakaʼwakw","de":"Kwakwakaʼwakw","en":"Kwakwakaʼwakw"},"url":"https://en.wikipedia.org/wiki/Kwakwaka%CA%BCwakw","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في تجمّع بقروية ساحلية، يستضيف أحد الأسر مئات الضيوف، ويوزّع البطانيات والطعام، ويعلن أمام الشهود اسماً موروثاً لحفيدة.","de":"Bei einem Treffen im Küstendorf bewirtet eine Familie Hunderte Gäste, verschenkt Decken und Essen und verkündet vor Zeugen einen ererbten Namen für eine Enkelin.","en":"At a coastal village gathering, a family hosts hundreds of guests, gives away blankets and food, and announces an inherited name for a granddaughter in front of witnesses."},"misunderstanding":{"ar":"يُظن أحياناً أنه مجرد عرض باذخ للثراء أو إعادة تمثيل تاريخية، لكنه مؤسسة حيّة تنظّم الحقوق والعلاقات.","de":"Man hält den Potlatch oft für bloße Prahlerei oder eine historische Aufführung, doch er ist eine lebendige Institution für Rechte und Beziehungen.","en":"It is often mistaken for mere display of excess or a historical re-enactment, yet it is a living institution that regulates rights and relationships."},"comparison":{"ar":"حيث تُقاس المكانة عادةً بما يُجمع، يُقاس هنا بما يُوزّع أمام الشهود.","de":"Wo Status sonst am Besitz gemessen wird, misst man ihn hier am Verteilen vor Zeugen.","en":"Where status is usually measured by what is kept, here it is measured by what is given away before witnesses."}},{"id":"tra-053","version":2,"slug":"rumspringa-the-amish-years-before-baptism","contentType":"note","category":"family-and-friendship","title":{"ar":"رومشبرينغا: سنوات المراهقة قبل المعمودية","de":"Rumspringa: Die Amish-Jahre vor der Taufe","en":"Rumspringa: The Amish Years Before Baptism"},"deck":{"ar":"فترة حرية نسبية للشباب الأميش قبل الالتزام الكنسي، تختلف باختلاف الجماعة والعائلة.","de":"Eine Zeit relativer Freiheit für junge Amische vor der kirchlichen Bindung, die je nach Gemeinschaft und Familie variiert.","en":"A period of relative freedom for Amish youth before church commitment, varying by community and family."},"teaser":{"ar":"في بعض مجتمعات الأميش، يمر المراهقون بفترة رومشبرينغا حيث يتسكعون ويتخذون قراراتهم قبل المعمودية.","de":"In einigen amischen Gemeinschaften durchlaufen Jugendliche die Rumspringa, in der sie sich freier bewegen und Entscheidungen treffen, bevor sie getauft werden.","en":"In some Amish communities, teenagers experience Rumspringa, a time of greater social freedom before they choose baptism."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما هي رومشبرينغا؟","paragraphs":["رومشبرينغا، وهي كلمة من اللغة الهولندية البنسلفانية تعني 'التسكع'، هي الفترة التي يمر بها بعض المراهقين الأميش حول سن السادسة عشرة، حيث لم يعتمدوا بعد ويمكنهم الاختلاط بحرية أكبر.","ليست مؤسسة أميشية عالمية: طولها ومحتواها يختلفان حسب الانتماء والمستوطنة والعائلة، وبعض المجتمعات لديها القليل منها."]},{"heading":"الممارسة والتنوع","paragraphs":["قد يحضر الشباب جلسات الغناء، ويستخدمون هاتفًا محدودًا أو يمتلكون عربة، ويواعدون؛ وعادة ما تأتي المعمودية في أواخر المراهقة أو أوائل العشرينات. المعمودية تعني قبول الأوردنانغ، قواعد الكنيسة؛ ومن يغادر بعد المعمودية قد يواجه النبذ، ميدونغ.","الصورة الشعبية للتمرد الجامح مبالغ فيها: معظم شباب الأميش ينضمون إلى الكنيسة في النهاية. يختلف الأمر بين جماعات الأولد أوردر ونيو أوردر وسفارتزينتروبر، ولانكستر ليست ممثلة للجميع."]}],"de":[{"heading":"Was ist die Rumspringa?","paragraphs":["Rumspringa, pennsylvaniadeutsch für 'Herumspringen', ist die Zeit in einigen amischen Gemeinschaften, in der Jugendliche um die sechzehn noch nicht getauft sind und sich freier bewegen dürfen.","Sie ist keine universelle amische Einrichtung: Länge und Inhalt variieren je nach Glaubensrichtung, Siedlung und Familie, und manche Gemeinschaften kennen sie kaum."]},{"heading":"Praxis und Vielfalt","paragraphs":["Junge Leute besuchen Singings, nutzen ein begrenztes Telefon oder besitzen eine Kutsche und gehen aus; die Taufe folgt meist im späten Teenageralter oder frühen Zwanzigern. Taufe bedeutet die Annahme der Ordnung, der Kirchenregeln; wer nach der Taufe austritt, kann mit Meidung rechnen.","Das populäre Bild der wilden Rebellion ist übertrieben: Die meisten amischen Jugendlichen treten schließlich der Kirche bei. Die Praxis unterscheidet sich zwischen Old Order, New Order und Swartzentruber, und Lancaster County ist nicht repräsentativ für alle."]}],"en":[{"heading":"What Is Rumspringa?","paragraphs":["Rumspringa, Pennsylvania Dutch for 'running around', is the period in some Amish communities when adolescents around sixteen are not yet baptised and may socialise more freely.","It is not a universal Amish institution: its length and content vary by affiliation, settlement and family, and some communities have little of it."]},{"heading":"Practice and Variation","paragraphs":["Young people may attend singings, use a limited phone or own a buggy, and date; baptism usually follows in the late teens or early twenties. Baptism means accepting the Ordnung, the church's rules; those who leave after baptism may face shunning, Meidung.","The popular image of wild rebellion is exaggerated: most Amish youth eventually join the church. Practice differs between Old Order, New Order and Swartzentruber communities, and Lancaster County is not representative of all."]}]},"context":{"countries":["US"],"region":"Pennsylvania and the Midwest","community":"Old Order Amish","continent":"north-america","languages":["en"],"period":"contemporary"},"tags":["family-and-friendship","Pennsylvania and the Midwest"],"sources":[{"organization":"Wikipedia","title":{"ar":"Amish","de":"Amish","en":"Amish"},"url":"https://en.wikipedia.org/wiki/Amish","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Rumspringa","de":"Rumspringa","en":"Rumspringa"},"url":"https://en.wikipedia.org/wiki/Rumspringa","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"مراهق من مقاطعة لانكستر يقضي أمسيات الأحد في جلسة غناء في حظيرة، ويستعير هاتف ابن عمه، ويعتمد بعد عامين أمام الجماعة.","de":"Ein Teenager aus Lancaster County verbringt Sonntagabende bei einem Singing in einer Scheune, leiht sich das Telefon eines Cousins und wird zwei Jahre später vor der Gemeinde getauft.","en":"A Lancaster County teenager spends Sunday evenings at a singing in a barn, borrows a cousin's phone, and is baptised two years later in front of the congregation."},"misunderstanding":{"ar":"يعتقد الكثيرون أن رومشبرينغا هي فترة تمرد جامح، لكن الواقع أن معظم الشباب يختارون المعمودية والانضمام إلى الكنيسة.","de":"Viele glauben, Rumspringa sei eine Zeit wilder Rebellion, doch die meisten Jugendlichen entscheiden sich für die Taufe und den Verbleib in der Kirche.","en":"Many believe Rumspringa is a time of wild rebellion, but most Amish youth ultimately choose baptism and remain in the church."},"comparison":{"ar":"على عكس فكرة الحرية المطلقة، فإن رومشبرينغا هي فترة اختبار محدودة تسبق التزامًا دينيًا طويل الأمد.","de":"Anders als die Vorstellung völliger Freiheit ist die Rumspringa eine begrenzte Probephase vor einer langfristigen religiösen Bindung.","en":"Unlike the idea of complete freedom, Rumspringa is a limited testing period before a long-term religious commitment."}},{"id":"tra-054","version":2,"slug":"kwanzaa-seven-days-of-names-and-principles","contentType":"note","category":"migration-and-identity","title":{"ar":"سبعة أيام من الأسماء والمبادئ","de":"Sieben Tage voller Namen und Grundsätze","en":"Seven days of names and principles"},"deck":{"ar":"كوانزا عيد ثقافي أميركي أفريقي يمتد من 26 ديسمبر إلى 1 يناير، يحيي سبعة مبادئ بالأسماء السواحيلية ويجمع الأسر حول مائدة الوحدة.","de":"Kwanzaa ist ein kulturelles Fest afroamerikanischer Familien vom 26. Dezember bis 1. Januar, das sieben Grundsätze mit Swahili-Namen und einen gemeinsamen Becher in den Mittelpunkt stellt.","en":"Kwanzaa is a cultural holiday kept by some African American families from 26 December to 1 January, built on seven Swahili-named principles and a shared cup of unity."},"teaser":{"ar":"أسرة في لوس أنجلوس تشعل شمعة كل ليلة وتجيب على تحية واحدة باسم مبدأ اليوم؛ هكذا يعيش بعض الأميركيين الأفارقة كوانزا.","de":"Eine Familie in Los Angeles zündet jeden Abend eine Kerze an und antwortet auf einen einzigen Gruß mit dem Namen des Tages; so leben manche Afroamerikaner Kwanzaa.","en":"A family in Los Angeles lights one candle each night and answers a single greeting with the name of that day's principle; this is how some African Americans keep Kwanzaa."},"readingMinutes":1,"sections":{"ar":[{"heading":"ليلة بعد ليلة، مبدأ بعد مبدأ","paragraphs":["ابتدع مولانا كارينغا، أستاذ الدراسات الأفريقية، كوانزا عام 1966 في لوس أنجلوس، ويُحتفل به من 26 ديسمبر إلى 1 يناير. تقوم الأمسيات على سبعة مبادئ تُسمى نغوزو سابا: الوحدة، وتقرير المصير، والعمل الجماعي، والاقتصاد التعاوني، والهدف، والإبداع، والإيمان.","توضع سبع شموع في حامل يُسمى كينارا، شمعة لكل مبدأ، إلى جانب حصيرة مكيكا ومحاصيل وذرة وكأس وحدة. ويُفتتح اللقاء بتحية «هاباري غاني؟» فيجيب الحاضرون باسم مبدأ تلك الليلة."]},{"heading":"هدايا صغيرة ومعنى كبير","paragraphs":["الهدايا غالبًا مصنوعة يدويًا أو تعليمية، ويستعير الاحتفال مفردات سواحيلية وزخارف أفريقية واسعة وصور حصاد. وهو عيد ثقافي لا ديني، يحييه عدد محدود من الأميركيين الأفارقة، وقد تعرض لانتقادات بسبب حداثة اختراعه وسياسات مؤسسه.","تختلف الممارسة بين الأسر والأجيال، فبعض الشبان يكتفون بالتحية والمائدة، بينما تتمسك الأجيال الأكبر بالطقوس كاملة."]}],"de":[{"heading":"Abend für Abend, Grundsatz für Grundsatz","paragraphs":["Maulana Karenga, Professor für Africana Studies, schuf Kwanzaa 1966 in Los Angeles; gefeiert wird vom 26. Dezember bis 1. Januar. Die Abende ruhen auf sieben Grundsätzen, den Nguzo Saba: Einheit, Selbstbestimmung, gemeinsame Arbeit, gemeinschaftliche Wirtschaft, Ziel, Kreativität und Glaube.","Sieben Kerzen stehen im Kinara, eine für jeden Grundsatz, dazu eine Mkeka-Matte, Feldfrüchte, Mais und ein Einheitsbecher. Der Gruß „Habari gani?“ eröffnet den Abend, und die Anwesenden antworten mit dem Grundsatz des Tages."]},{"heading":"Kleine Gaben, große Bedeutung","paragraphs":["Geschenke sind oft handgemacht oder lehrreich; das Fest bedient sich swahilischer Begriffe, panafrikanischer Motive und Erntebilder. Es ist kulturell, nicht religiös, wird von einer Minderheit der Afroamerikaner begangen und steht wegen seiner modernen Erfindung und der Politik seines Gründers in der Kritik.","Die Praxis variiert nach Region und Generation: Manche Jüngere bleiben beim Gruß und der Tafel, ältere Familien halten an allen Riten fest."]}],"en":[{"heading":"Night by night, principle by principle","paragraphs":["Maulana Karenga, a professor of Africana studies, created Kwanzaa in 1966 in Los Angeles, and it runs from 26 December to 1 January. The evenings rest on seven principles, the Nguzo Saba: unity, self-determination, collective work, cooperative economics, purpose, creativity and faith.","Seven candles stand in a kinara, one for each principle, beside a mkeka mat, crops, corn and a unity cup. The greeting \"Habari gani?\" opens the evening, and those present answer with that night's principle."]},{"heading":"Small gifts, larger meaning","paragraphs":["Gifts are often handmade or educational, and the celebration borrows Swahili terms, pan-African motifs and harvest imagery. It is cultural rather than religious, observed by a minority of African Americans, and has been criticised both for its modern invention and for its founder's politics.","Practice varies by region and generation: some younger families keep only the greeting and the table, while older relatives hold to the full ritual."]}]},"context":{"countries":["US"],"region":"United States","community":"African-American communities","continent":"north-america","languages":["en","sw"],"period":"contemporary"},"tags":["migration-and-identity","United States"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kwanzaa","de":"Kwanzaa","en":"Kwanzaa"},"url":"https://en.wikipedia.org/wiki/Kwanzaa","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"African-American culture","de":"African-American culture","en":"African-American culture"},"url":"https://en.wikipedia.org/wiki/African-American_culture","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في الليلة الثانية تشعل أسرة شمعتين على الكينارا، ويجيب طفل بكلمة «كوجيتشاغوليا» على التحية، ثم يتقاسم الجميع هدية صغيرة مصنوعة يدويًا.","de":"Am zweiten Abend zündet eine Familie zwei Kerzen am Kinara an, ein Kind antwortet „kujichagulia“ auf den Gruß, und alle teilen ein kleines handgemachtes Geschenk.","en":"On the second night a family lights two candles on the kinara, a child answers \"kujichagulia\" to the greeting, and everyone shares a small handmade gift."},"misunderstanding":{"ar":"كوانزا ليس عيدًا أفريقيًا ولا مسيحيًا، ومعظم الأميركيين الأفارقة لا يحتفلون به؛ والممارسة الأسرية تتفاوت كثيرًا.","de":"Kwanzaa ist weder ein afrikanisches noch ein christliches Fest, und die meisten Afroamerikaner begehen es nicht; die familiäre Praxis ist sehr unterschiedlich.","en":"Kwanzaa is not an African or a Christian holiday, and most African Americans do not observe it; family practice varies widely."},"comparison":{"ar":"يشبه كوانزا أعياد الحصاد العائلية التي تجمع الناس حول مائدة ورمز، لكنه يظل تقليدًا أميركيًا حديثًا لا طقسًا قادمًا من قرية أفريقية.","de":"Kwanzaa ähnelt häuslichen Erntefesten, die Menschen um Tafel und Symbol versammeln, bleibt aber eine junge amerikanische Tradition und kein aus einem afrikanischen Dorf übernommener Brauch.","en":"Kwanzaa resembles household harvest gatherings that bring people around a table and a symbol, yet it remains a recent American tradition rather than a custom carried from an African village."}},{"id":"tra-055","version":2,"slug":"juneteenth-the-date-freedom-was-announced-in-texas","contentType":"detail","category":"traditions","title":{"ar":"جونتينث: يوم أُعلن فيه التحرر في تكساس","de":"Juneteenth: Der Tag der Freiheitsverkündung in Texas","en":"Juneteenth: The Day Freedom Was Announced in Texas"},"deck":{"ar":"في 19 يونيو 1865، أعلن اللواء غوردون غرانجر في غالفستون تحرير المستعبدين في تكساس، بعد أكثر من عامين من إعلان التحرر.","de":"Am 19. Juni 1865 verkündete Generalmajor Gordon Granger in Galveston die Freiheit der Versklavten in Texas – mehr als zwei Jahre nach der Emanzipationsproklamation.","en":"On June 19, 1865, Major General Gordon Granger announced in Galveston the freedom of enslaved people in Texas, more than two years after the Emancipation Proclamation."},"teaser":{"ar":"كيف تحوّل إعلان متأخر في تكساس إلى عيد وطني يحتفل به الأمريكيون بالصلاة والموسيقى والطعام الأحمر.","de":"Wie eine verspätete Bekanntmachung in Texas zu einem nationalen Feiertag wurde, der mit Gebet, Musik und rotem Essen begangen wird.","en":"How a delayed announcement in Texas became a national holiday celebrated with prayer, music, and red foods."},"readingMinutes":1,"sections":{"ar":[{"heading":"إعلان متأخر في غالفستون","paragraphs":["في 19 يونيو 1865، وقف اللواء غوردون غرانجر في غالفستون بتكساس ليعلن الأمر العام رقم 3، الذي نص على حرية المستعبدين في الولاية. جاءت الأخبار بعد أكثر من عامين من إعلان التحرر الذي طبّق على الولايات المتمردة، لكن مالكي العبيد في تكساس حجبوها.","تحوّل هذا اليوم إلى ذكرى سنوية تعرف باسم جونتينث، حيث يجتمع الناس للصلاة وقراءة إعلان التحرر والغناء وتناول الطعام. ومن الأطباق التقليدية المشروبات الحمراء وكعكة المخمل الأحمر، في إشارة إلى الدماء والتضحية."]},{"heading":"من جوبيلي داي إلى عطلة فيدرالية","paragraphs":["كانت الاحتفالات المبكرة تسمى جوبيلي داي، وقد بدأت في تكساس ثم انتشرت مع هجرة الأمريكيين الأفارقة. في عام 1980، أصبح جونتينث عطلة رسمية في تكساس، وتلتها ولايات أخرى، وفي عام 2021 أصبح عطلة فيدرالية.","تظل غالفستون وهيوستن مركزين للاحتفال، حيث تستخدم许多 العائلات هذا التاريخ للقاءات الشمل والنزهات المجتمعية. وتختلف مظاهر الاحتفال باختلاف المناطق والأجيال، فبعض العائلات تحيي الذكرى بقراءة الأمر العام رقم 3، بينما يفضل آخرون التجمعات الموسيقية."]}],"de":[{"heading":"Eine verspätete Verkündung in Galveston","paragraphs":["Am 19. Juni 1865 verkündete Generalmajor Gordon Granger in Galveston, Texas, die General Order No. 3, die die Freiheit der Versklavten in diesem Bundesstaat erklärte. Die Nachricht erreichte Texas mehr als zwei Jahre nach der Emanzipationsproklamation, die für die rebellierenden Staaten galt, doch texanische Sklavenhalter hatten sie zurückgehalten.","Dieser Tag wurde als Juneteenth bekannt und wird mit Gebeten, dem Verlesen der Emanzipationsproklamation, Gesang und gemeinsamem Essen begangen. Zu den traditionellen Speisen gehören rote Getränke und Red-Velvet-Kuchen, die an Blut und Opfer erinnern."]},{"heading":"Vom Jubilee Day zum bundesweiten Feiertag","paragraphs":["Frühe Feiern nannte man Jubilee Day; sie begannen in Texas und breiteten sich mit der Migration von Afroamerikanern aus. 1980 machte Texas Juneteenth zum offiziellen Feiertag, andere Staaten folgten, und 2021 wurde er zum bundesweiten Feiertag.","Galveston und Houston bleiben Zentren des Gedenkens, und viele Familien nutzen das Datum für Familientreffen und Gemeinschaftspicknicks. Die Feierlichkeiten variieren je nach Region und Generation: Manche Familien beginnen mit einer Lesung der General Order No. 3, während andere Musikveranstaltungen bevorzugen."]}],"en":[{"heading":"A Delayed Announcement in Galveston","paragraphs":["On June 19, 1865, Major General Gordon Granger stood in Galveston, Texas, and announced General Order No. 3, declaring the freedom of enslaved people in the state. The news came more than two years after the Emancipation Proclamation, which had applied to states in rebellion, but Texas enslavers had withheld it.","The day became known as Juneteenth and is observed with prayer, readings of the Emancipation Proclamation, singing, and food. Traditional dishes include red drinks and red velvet cake, symbolizing blood and sacrifice."]},{"heading":"From Jubilee Day to a Federal Holiday","paragraphs":["Early celebrations were called Jubilee Day; they began in Texas and spread with the migration of African Americans. In 1980, Texas made Juneteenth an official state holiday, other states followed, and in 2021 it became a federal holiday.","Galveston and Houston remain centers of commemoration, and many families use the date for reunions and community picnics. Commemorations vary by region and generation: some families start with a reading of General Order No. 3, while others prefer music festivals."]}]},"context":{"countries":["US"],"region":"Texas and the Gulf Coast","continent":"north-america","languages":["en"],"period":"contemporary"},"tags":["traditions","Texas and the Gulf Coast"],"sources":[{"organization":"Wikipedia","title":{"ar":"Juneteenth","de":"Juneteenth","en":"Juneteenth"},"url":"https://en.wikipedia.org/wiki/Juneteenth","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of the United States","de":"Culture of the United States","en":"Culture of the United States"},"url":"https://en.wikipedia.org/wiki/Culture_of_the_United_States","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في غالفستون، تحضر عائلة قراءة صباحية للأمر الصادر عام 1865 عند اللوحة التاريخية، ثم تنضم إلى نزهة في الحديقة مع صودا حمراء وشواء.","de":"In Galveston nimmt eine Familie an einer morgendlichen Lesung der Verordnung von 1865 an der Gedenktafel teil und geht anschließend zu einem Picknick im Park mit roter Limonade und Barbecue.","en":"In Galveston, a family attends a morning reading of the 1865 order at the historical marker, then joins a park picnic with red soda and barbecue."},"misunderstanding":{"ar":"جونتينث لا يعني نهاية العبودية في جميع أنحاء البلاد، بل يحيي إعلانًا محددًا في تكساس، والاحتفالات تختلف بشكل كبير بين المجتمعات.","de":"Juneteenth markiert nicht das Ende der Sklaverei in den gesamten USA, sondern eine spezifische Verkündung in Texas; die Gedenkfeiern unterscheiden sich stark von Gemeinde zu Gemeinde.","en":"Juneteenth marks a specific Texas announcement, not the single end of slavery nationwide, and commemorations differ widely among communities."},"comparison":{"ar":"بينما تحتفل بعض المجتمعات بالصلاة وقراءة الوثائق، تفضل مجتمعات أخرى الحفلات الموسيقية والنزهات، مما يعكس تنوع التقاليد داخل المجتمع الأمريكي الأفريقي.","de":"Während einige Gemeinden mit Gebet und dem Verlesen von Dokumenten gedenken, ziehen andere Musikveranstaltungen und Picknicks vor – ein Spiegel der Vielfalt innerhalb der afroamerikanischen Gemeinschaft.","en":"While some communities commemorate with prayer and document readings, others favor music festivals and picnics, reflecting the diversity within African American traditions."}},{"id":"tra-056","version":2,"slug":"at-the-sugar-shack-quebec-s-spring-ritual","contentType":"scene","category":"food-and-hospitality","title":{"ar":"في كوخ السكر: طقس الربيع في كيبيك","de":"In der Zuckerhütte: Quebecs Frühlingsritual","en":"At the sugar shack: Quebec's spring ritual"},"deck":{"ar":"عائلات كيبيك تتقاسم وجبة تقليدية في كوخ السكر حين يجري نسغ القيقب بين ذوبان النهار وبرد الليل.","de":"Familien in Quebec teilen im Frühling eine traditionelle Mahlzeit in der Zuckerhütte, wenn der Ahornsaft zwischen Tauwetter und kalten Nächten fließt.","en":"Quebec families share a traditional meal at the sugar shack each spring, when maple sap runs between daytime thaw and cold nights."},"teaser":{"ar":"من مارس إلى أبريل يذهب الناس إلى أكواخ السكر لتناول اللحم والفاصولياء، ثم يلفّون العسل الدافئ على الثلج.","de":"Von März bis April fahren Menschen zur Zuckerhütte, essen Schinken und Bohnen und rollen warmen Sirup auf Schnee.","en":"From March to April people head to sugar shacks for ham and beans, then roll warm syrup on snow in the yard."},"readingMinutes":1,"sections":{"ar":[{"heading":"موسم يجري مع النسغ","paragraphs":["كوخ السكر هو منشأة لمنتِج شراب القيقب، حيث يُغلَى النسغ ويأكل الزوار وجبة تقليدية خلال موسم الربيع.","يمتد الموسم تقريبًا من مارس إلى أبريل، حين يدفع ذوبان النهار وبرد الليل النسغ إلى الجريان، وتشمل الوجبة عادةً لحم الخنزير والفاصولياء المخبوزة والعجّة وقشر لحم الخنزير المقلِي.","يُسكب عسل القيقب الدافئ على الثلج ويُلفّ على عود، ويأخذ الأطفال رحلات مدرسية إلى هذه الأكواخ."]},{"heading":"من الغابة إلى المائدة المشتركة","paragraphs":["كانت الشعوب الأصلية تحصد نسغ القيقب قبل الاستيطان الأوروبي، أما الكوخ كوجبة عامة فمؤسسة فرنسية-كندية لاحقة.","تنتج كيبيك معظم شراب القيقب في العالم، وينظّم القطاع اتحاد للمنتجين يعمل بالحصص.","تختلف التجربة بين الأجيال والمناطق: فبعض الأكواخ مزارع عاملة، وأخرى قاعات كبيرة، كما أن العائلات الشابة قد تفضّل زيارات أقصر."]}],"de":[{"heading":"Eine Saison, die mit dem Saft läuft","paragraphs":["Eine cabane à sucre ist der Betrieb eines Ahornsirup-Produzenten, in dem Saft eingekocht wird und Gäste während der Frühlingssaison ein traditionelles Essen bekommen.","Die Saison läuft etwa von März bis April, wenn Tauwetter am Tag und kalte Nächte den Saft fließen lassen; typisch sind Schinken, gebackene Bohnen, Omelett und oreilles de crisse, Schweinekrusten.","Ahornsirup wird auf Schnee gegossen und auf einem Stiel gerollt, und Kinder fahren auf Schulausflügen zu den Zuckerhütten."]},{"heading":"Vom Wald an den langen Tisch","paragraphs":["Die Ahornsafte­rnte betrieben indigene Völker lange vor der europäischen Besiedlung; die Zuckerhütte als öffentliches Essen ist eine spätere frankokanadische Einrichtung.","Quebec produziert den Großteil des Ahornsirups der Welt, und die Branche wird von einem Produzentenverband mit Quoten reguliert.","Je nach Region und Generation unterscheidet sich das Erlebnis: Manche Hütten sind arbeitende Höfe, andere große Bankettsäle, und jüngere Familien wählen oft kürzere Besuche."]}],"en":[{"heading":"A season that runs with the sap","paragraphs":["A cabane à sucre, or sugar shack, is a maple-syrup producer's establishment where sap is boiled down and visitors eat a traditional meal during the spring sugaring season.","The season runs roughly from March to April, when daytime thaw and cold nights make sap run; the meal typically includes ham, baked beans, omelette and oreilles de crisse, pork rinds.","Maple taffy, tire sur la neige, is poured onto snow and rolled onto a stick, and children are taken to sugar shacks on school trips."]},{"heading":"From the forest to the long table","paragraphs":["Maple sap harvesting was practised by Indigenous peoples before European settlement, and the sugar shack as a public meal is a later French-Canadian institution.","Quebec produces the majority of the world's maple syrup, and the industry is regulated by a producer federation with quotas.","The experience varies by region and generation: some shacks are working farms, others large banquet halls, and younger families often choose shorter visits."]}]},"context":{"countries":["CA"],"region":"Quebec","continent":"north-america","languages":["fr","en"],"period":"contemporary"},"tags":["food-and-hospitality","Quebec"],"sources":[{"organization":"Wikipedia","title":{"ar":"Sugar shack","de":"Sugar shack","en":"Sugar shack"},"url":"https://en.wikipedia.org/wiki/Sugar_shack","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Quebec","de":"Culture of Quebec","en":"Culture of Quebec"},"url":"https://en.wikipedia.org/wiki/Culture_of_Quebec","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في أبريل تقود عائلة سيارتها إلى كوخ خارج تروا-ريفيير، وتأكل حساء البازلاء ولحم الخنزير على طاولات طويلة مشتركة، ثم تلفّ العسل الدافئ على الثلج في الفناء.","de":"Im April fährt eine Familie zu einer Hütte bei Trois-Rivières, isst Erbsensuppe und Schinken an langen Gemeinschaftstischen und rollt danach warmen Sirup im Hof auf Schnee.","en":"In April, a family drives to a shack outside Trois-Rivières, eats pea soup and ham at long communal tables, then rolls warm syrup on snow in the yard."},"misunderstanding":{"ar":"يظن بعض الزوار أن كوخ السكر تقليد كندي عام، لكنه في الواقع تقليد خاص بكيبيك ومنطقة الأبلاش.","de":"Viele halten die Zuckerhütte für eine gesamtkanadische Tradition, doch sie gehört zu Quebec und den Appalachen.","en":"Many visitors assume the sugar shack is a nationwide Canadian tradition, but it belongs to Quebec and the Appalachian region."},"comparison":{"ar":"يشبه كوخ السكر المطاعم الموسمية في أوروبا، لكن الوجبة هنا تُؤكل في مكان الإنتاج نفسه وبين الثلج.","de":"Sie ähnelt saisonalen Lokalen in Europa, doch gegessen wird hier am Produktionsort, mitten im Schnee.","en":"It resembles seasonal eating places in Europe, but here the meal happens where the syrup is made, out among the snow."}},{"id":"tra-057","version":2,"slug":"vodou-serving-the-lwa-in-haiti","contentType":"note","category":"beliefs-and-folklore","title":{"ar":"خدمة اللوا في الهايتي","de":"Den Lwa in Haiti dienen","en":"Serving the lwa in Haiti"},"deck":{"ar":"الفودو دين حي في هايتي والمهجر، يقوم على خدمة الأرواح عبر الطبول والرقص والتقدمة داخل مجتمعات محلية.","de":"Vodou ist eine lebendige Religion in Haiti und der Diaspora, getragen von Trommeln, Tanz, Gesang und Gaben in lokalen Gemeinschaften.","en":"Vodou is a living religion in Haiti and its diaspora, carried by drumming, dancing, singing and offerings within local communities."},"teaser":{"ar":"كيف يعيش الناس في هايتي دين الفودو بعيداً عن صورة هوليوود؟ نظرة على الطبول والكهنة والأرواح في الحياة اليومية.","de":"Wie Menschen in Haiti Vodou jenseits des Hollywood-Klischees leben: Trommeln, Priesterinnen und Geister im Alltag einer Gemeinschaft.","en":"How people in Haiti live Vodou beyond the Hollywood stereotype: drummers, priestesses and spirits woven into everyday community life."},"readingMinutes":1,"sections":{"ar":[{"heading":"من العبودية إلى دين حي","paragraphs":["تطوّر الفودو الهايتي بين الأفارقة المستعبدين وذريتهم، فامتزجت تقاليد غرب أفريقيا، خصوصاً الفون واليوروبا والكونغو، بعناصر كاثوليكية.","يحتفل الناس بإله خالق بعيد اسمه بوندي، وبأرواح تُسمى لوا، تُخدم بالطبول والرقص والغناء والتقدمات.","يختلف العمر والجيل في طريقة المشاركة، فبعض الشباب في المهجر يتعلم الطقوس عبر العائلة والمجموعات الصغيرة."]},{"heading":"الكهنة والمجتمع","paragraphs":["تقود المانبو أو الأونغان المجتمع، وتتبع الاحتفالات تقويماً طقسياً، وكثيراً ما تُربط قديسون كاثوليك بأرواح معينة.","حظرت السلطات الاستعمارية الممارسات الأفريقية بموجب قانون نوير عام 1685، ثم شوّهت السينما وأدب الرحلات صورتها.","تتنوع الطقوس بين البيوت والمناطق وبين الأجيال، وبعضها محدود لا يُروى للغريب."]}],"de":[{"heading":"Von der Sklaverei zur gelebten Religion","paragraphs":["Der haitianische Vodou entstand unter versklavten Afrikanern und ihren Nachkommen und verband westafrikanische Traditionen, besonders Fon, Yoruba und Kongo, mit katholischen Elementen.","Im Zentrum stehen ein ferner Schöpfer namens Bondye und Geister, die Lwa, denen man mit Trommeln, Tanz, Gesang und Gaben dient.","Je nach Alter und Generation unterscheidet sich die Teilnahme, und junge Menschen in der Diaspora lernen die Riten oft über Familie und kleine Gruppen."]},{"heading":"Priesterinnen und Gemeinschaft","paragraphs":["Eine Manbo oder ein Oungan leitet die Gemeinschaft; Zeremonien folgen einem rituellen Kalender, und katholische Heilige werden oft bestimmten Lwa zugeordnet.","Kolonialbehörden verboten afrikanische Religionsausübung durch den Code Noir von 1685, später verzerrten Filme und Reiseliteratur das Bild.","Rituale variieren zwischen Häusern, Regionen und Generationen, und manche sind begrenzt und nicht für Außenstehende bestimmt."]}],"en":[{"heading":"From slavery to a living faith","paragraphs":["Haitian Vodou developed among enslaved Africans and their descendants, blending West African traditions, especially Fon, Yoruba and Kongo, with Catholic elements.","It centres on a distant creator, Bondye, and on spirits called lwa, served through drumming, dancing, singing and offerings.","Participation varies by age and generation, and young people in the diaspora often learn rituals through family and small groups."]},{"heading":"Priests and community","paragraphs":["A manbo, priestess, or oungan, priest, leads a community; ceremonies follow ritual calendars, and Catholic saints are often associated with particular lwa.","Colonial authorities banned African religious practice under the 1685 Code Noir, and films and travel writing later misrepresented the religion.","Rituals vary between houses, regions and generations, and some are restricted and not shared with outsiders."]}]},"context":{"countries":["HT"],"region":"Haiti","community":"Haitian Vodou communities","continent":"north-america","languages":["ht","fr"],"period":"contemporary"},"tags":["beliefs-and-folklore","Haiti"],"sources":[{"organization":"Wikipedia","title":{"ar":"Haitian Vodou","de":"Haitian Vodou","en":"Haitian Vodou"},"url":"https://en.wikipedia.org/wiki/Haitian_Vodou","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Haiti","de":"Culture of Haiti","en":"Culture of Haiti"},"url":"https://en.wikipedia.org/wiki/Culture_of_Haiti","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في بيريستيل في بورت أو برنس، يبني عازفو الطبول إيقاعاً، فتبدأ امرأة بثياب بيضاء بالارتجاف، فيعرف المجتمع أي لوا وصل ويستقبله بالأغاني والتقدمات.","de":"In einem Peristyl in Port-au-Prince bauen Trommler einen Rhythmus auf, eine Frau in Weiß beginnt zu zittern, und die Gemeinde erkennt den angekommenen Lwa und begrüßt ihn mit Liedern und Gaben.","en":"At a peristyle in Port-au-Prince, drummers build a rhythm, a woman in white begins to shake, and the community recognises the lwa who has arrived and greets it with songs and offerings."},"misunderstanding":{"ar":"كثيرون يظنون أن دمى الفودو جزء من الدين، لكنها اختراع تجاري لا علاقة له بممارسة الفودو الهايتي.","de":"Viele halten die Voodoo-Puppe für Teil der Religion, doch sie ist eine kommerzielle Erfindung ohne Bezug zur haitianischen Vodou-Praxis.","en":"Many assume the 'voodoo doll' belongs to the religion, but it is a commercial invention, not a Haitian Vodou practice."},"comparison":{"ar":"يشبه الفودو في تنظيمه المحلي كثيراً من التقاليد الدينية الشعبية، حيث يقود المجتمع شخص موثوق وتتناقل المعرفة شفهياً.","de":"In seiner lokalen Organisation ähnelt Vodou vielen Volksreligionen, in denen eine vertrauenswürdige Person die Gemeinschaft führt und Wissen mündlich weitergegeben wird.","en":"In its local organisation, Vodou resembles many folk religions where a trusted person leads the community and knowledge passes on orally."}},{"id":"tra-058","version":2,"slug":"festa-junina-bonfires-and-square-dances-in-june","contentType":"note","category":"traditions","title":{"ar":"احتفالات يونينا: نيران ودبكات في يونيو","de":"Festa Junina: Lagerfeuer und Vierecktänze im Juni","en":"Festa Junina: Bonfires and Square Dances in June"},"deck":{"ar":"مهرجان يونيو البرازيلي يمزج الإيمان الكاثوليكي بالحياة الريفية، ويحتفل بالقديسين أنطونيو ويوحنا وبطرس.","de":"Brasilianisches Junifest verbindet katholische Frömmigkeit mit ländlichem Leben und ehrt die Heiligen Antonius, Johannes und Petrus.","en":"Brazil's June festival blends Catholic devotion with rural life, honouring Saints Anthony, John and Peter."},"teaser":{"ar":"في يونيو، تتحول الساحات والمدارس البرازيلية إلى مسارح ريفية: نيران، رقصات، وأطعمة من الذرة.","de":"Im Juni verwandeln sich Plätze und Schulen in Brasilien in ländliche Bühnen: Feuer, Tänze und Speisen aus Mais.","en":"In June, Brazilian squares and schools become rural stages: bonfires, dances, and foods made from corn."},"readingMinutes":1,"sections":{"ar":[{"heading":"جذور برتغالية وروح ريفية","paragraphs":["وصل مهرجان يونيو إلى البرازيل مع المستعمرين البرتغاليين، وهو يكرم القديس أنطونيو في 13 يونيو، والقديس يوحنا في 24 يونيو، والقديس بطرس في 29 يونيو. يمزج الاحتفال بين التعبد الكاثوليكي والثقافة الريفية: رقصة الكوادريلا، وموسيقى الفورو، والنيران، وأعلام ورقية وقبعات قش.","يرتدي المشاركون أزياء الكايبيرا، سكان الريف، بقمصان مربعة وقبعات قش ونمش مرسوم، مما يجعل المهرجان حدثًا مدرسيًا وحوريًا بقدر ما هو ديني. تختلف الاحتفالات بين البلدات الصغيرة والمدن الكبرى، وتتباين بين الأجيال في حماسها للرقص التقليدي."]},{"heading":"الذرة والنيران في قلب الاحتفال","paragraphs":["الذرة هي النجم الموسمي: بامونيا، كوراو، كانجيكا، ميلو وباسوكا، مع مشروب الكوينتاو المصنوع من الزنجبيل والكاشاسا، والنبيذ الساخن. في الشمال الشرقي، وخاصة في كامبينا غراندي وكاروارو، تقام أكبر الاحتفالات، بينما تشهد الأمازون مهرجانات بوي-بومبا في بارينتينس في الموسم نفسه."]}],"de":[{"heading":"Portugiesische Wurzeln und ländlicher Geist","paragraphs":["Die Festa Junina kam mit portugiesischen Kolonisatoren nach Brasilien und ehrt den heiligen Antonius am 13. Juni, den heiligen Johannes am 24. Juni und den heiligen Petrus am 29. Juni. Das Fest mischt katholische Andacht mit ländlicher Kultur: Quadrilha-Tanz, Forró, Lagerfeuer, Papierfähnchen und Strohhüte.","Die Teilnehmer kleiden sich als Caipiras, Landbewohner, mit karierten Hemden, Strohhüten und aufgemalten Sommersprossen, was das Fest ebenso zu einem Schul- und Nachbarschaftsereignis wie zu einem religiösen macht. Die Feiern unterscheiden sich zwischen kleinen Orten und Großstädten und variieren je nach Generation in der Begeisterung für traditionelle Tänze."]},{"heading":"Mais und Feuer im Mittelpunkt","paragraphs":["Mais ist der saisonale Star: Pamonha, Curau, Canjica, Milho und Paçoca, dazu Quentão aus Ingwer und Cachaça sowie Glühwein. Im Nordosten, besonders in Campina Grande und Caruaru, finden die größten Feiern statt, während Amazonien in derselben Saison die Boi-Bumbá-Feste von Parintins erlebt."]}],"en":[{"heading":"Portuguese Roots and Rural Spirit","paragraphs":["Festa Junina came to Brazil with Portuguese colonisers and honours Saint Anthony on 13 June, Saint John on 24 June and Saint Peter on 29 June. The festival mixes Catholic devotion with rural culture: quadrilha square dancing, forró, bonfires, paper flags and straw hats.","Participants dress as caipiras, country people, in checked shirts, straw hats and painted freckles, making the festival as much a school and neighbourhood event as a religious one. Celebrations range from small town parties to huge festivals, and the caipira costume carries rural stereotypes that are sometimes contested."]},{"heading":"Corn and Bonfires at the Heart","paragraphs":["Corn is the seasonal centrepiece: pamonha, curau, canjica, milho and paçoca, with quentão, a ginger and cachaça drink, and mulled wine. The Northeast holds the largest celebrations, especially Campina Grande and Caruaru, while the Amazon has the Boi-Bumbá festivals of Parintins in the same season."]}]},"context":{"countries":["BR"],"region":"Brazil (nationwide)","continent":"south-america","languages":["pt"],"period":"contemporary"},"tags":["traditions","Brazil (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Festa Junina","de":"Festa Junina","en":"Festa Junina"},"url":"https://en.wikipedia.org/wiki/Festa_Junina","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Brazil","de":"Culture of Brazil","en":"Culture of Brazil"},"url":"https://en.wikipedia.org/wiki/Culture_of_Brazil","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مدرسة في ريسيفي، يرقص الأطفال بقبعات قش رقصة الكوادريلا حول نار مصنوعة من ورق ملون، ويشتري الآباء كعك الذرة والكوينتاو من الأكشاك.","de":"In einer Schule in Recife tanzen Kinder in Strohhüten Quadrilha um ein Feuer aus buntem Papier, und Eltern kaufen Maiskuchen und Quentão an Ständen.","en":"At a school in Recife, children in straw hats dance quadrilha around a bonfire made of coloured paper, and parents buy corn cakes and quentão from stalls."},"misunderstanding":{"ar":"قد يظن البعض أن المهرجان ديني بحت، لكنه في الواقع يجمع بين الاحتفال الديني والاحتفال المجتمعي والثقافي.","de":"Man könnte denken, das Fest sei rein religiös, doch es verbindet religiöse Feier mit Gemeinschafts- und Kulturfest.","en":"Some might think the festival is purely religious, but it actually combines religious celebration with community and cultural festivity."},"comparison":{"ar":"يشبه المهرجان الكرنفال في بعده المجتمعي، لكنه يركز على الحياة الريفية والقديسين بدلاً من الاستعراضات الكبيرة.","de":"Das Fest ähnelt dem Karneval in seiner gesellschaftlichen Dimension, konzentriert sich aber auf ländliches Leben und Heilige statt auf große Paraden.","en":"The festival resembles Carnival in its community dimension, but focuses on rural life and saints rather than large parades."}},{"id":"tra-059","version":2,"slug":"mate-the-gourd-that-goes-round-the-circle","contentType":"detail","category":"food-and-hospitality","title":{"ar":"المتة: القرعة التي تدور في الحلقة","de":"Mate: der Kürbis, der die Runde macht","en":"Mate: the gourd that goes round the circle"},"deck":{"ar":"في الأرجنتين وأوروغواي وباراغواي، المتة مشروب يُشارك في دائرة، حيث يملأ المضيف القرعة ويوزعها بالدور.","de":"In Argentinien, Uruguay und Paraguay wird Mate aus einem Kürbis getrunken und in einer Runde geteilt – der Gastgeber füllt und reicht weiter.","en":"In Argentina, Uruguay and Paraguay, mate is an infusion shared in a circle, with the host pouring and passing the gourd in turn."},"teaser":{"ar":"طقس اجتماعي حول القرعة والمصاصة المعدنية: من يشرب أولاً، وماذا يعني أن تقول 'شكراً'، وكيف تنتقل المتة بين الأيدي.","de":"Ein soziales Ritual mit Kürbis und Metallstrohhalm: Wer zuerst trinkt, was 'gracias' bedeutet und wie die Mate von Hand zu Hand geht.","en":"A social ritual around a gourd and metal straw: who drinks first, what 'gracias' means, and how the mate travels from hand to hand."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقس المشاركة","paragraphs":["يُحضر المتة من نبات البهشية البرازيلية، ويُشرب من قرعة تُسمى 'mate' عبر مصاصة معدنية 'bombilla'. في الأرجنتين وأوروغواي وباراغواي وجنوب البرازيل، يُشارك عادة في دائرة.","المضيف، ويُسمى 'cebador'، يصب الماء الساخن، ويشرب أول قرعة لاختبارها، ثم يعيد ملأها ويمررها بالدور. كل شخص ينهي القرعة قبل أن تعود إلى المضيف."]},{"heading":"آداب الكلمة والصمت","paragraphs":["قول 'gracias' يعني 'لا مزيد، شكراً'؛ أما قبول القرعة وإعادتها دون كلمة فيعني أنك تريد جولة أخرى. تحذر الآداب من تحريك المصاصة أو استعجال المضيف أو إضافة السكر دون سؤال، وحمل الترمس والطقم أمر عادي. تختلف القواعد بين البلدان والعائلات، والمتة اجتماعية جداً لكنها تُشرب أيضاً بشكل فردي."]}],"de":[{"heading":"Das Ritual des Teilens","paragraphs":["Mate wird aus den Blättern des Stechpalmengewächses gewonnen und aus einem Kürbis, dem 'mate', durch ein Metallrohr, die 'bombilla', getrunken. In Argentinien, Uruguay, Paraguay und Südbrasilien wird er meist in einer Runde geteilt.","Der Gastgeber, der 'cebador', gießt heißes Wasser ein, trinkt den ersten Kürbis zur Probe, füllt nach und reicht die Mate der Reihe nach weiter; jeder leert den Kürbis, bevor er zurückgeht."]},{"heading":"Worte und Schweigen","paragraphs":["Sagt man 'gracias', heißt das 'nicht mehr, danke'; nimmt man den Kürbis an und gibt ihn wortlos zurück, möchte man eine weitere Runde. Die Etikette rät davon ab, die Bombilla umzurühren, den Cebador zu drängen oder ungefragt Zucker hinzuzufügen; Thermoskanne und Mate-Set mitzutragen ist normal. Die Regeln unterscheiden sich je nach Land und Familie, und Mate ist sehr gesellig, wird aber auch oft allein getrunken."]}],"en":[{"heading":"The ritual of sharing","paragraphs":["Yerba mate is an infusion drunk from a gourd, the mate, through a metal straw, the bombilla. In Argentina, Uruguay, Paraguay and southern Brazil, it is usually shared in a circle.","The host, the cebador, pours hot water, drinks the first gourd to test it, then refills and passes the mate in turn; each person finishes the gourd before it returns."]},{"heading":"Words and silence","paragraphs":["Saying 'gracias' means 'no more, thank you'; accepting and passing the gourd back without a word means you want another round. Etiquette warns against stirring the bombilla, rushing the cebador or adding sugar without asking, and carrying a thermos and mate set is ordinary. Rules differ across the four countries and between families, and mate is deeply sociable but also frequently drunk alone."]}]},"context":{"countries":["AR","UY","PY"],"region":"Río de la Plata and Paraguay","continent":"south-america","languages":["es"],"period":"contemporary"},"tags":["food-and-hospitality","Río de la Plata and Paraguay"],"sources":[{"organization":"Wikipedia","title":{"ar":"Mate (drink)","de":"Mate (drink)","en":"Mate (drink)"},"url":"https://en.wikipedia.org/wiki/Mate_(drink)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Gaucho","de":"Gaucho","en":"Gaucho"},"url":"https://en.wikipedia.org/wiki/Gaucho","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في صف الحافلة في بوينس آيرس، يملأ رجل قرعته من ترمس تحت ذراعه، ويعرضها على صديق، فيقول الصديق 'gracias' بعد جولة واحدة إشارة إلى أنه انتهى.","de":"In einer Bushalteschlange in Buenos Aires füllt ein Mann seinen Kürbis aus einer Thermoskanne unter dem Arm, bietet ihn einem Freund an, und der Freund sagt nach einer Runde 'gracias', um zu signalisieren, dass er fertig ist.","en":"On a Buenos Aires bus queue, a man fills his gourd from a thermos under his arm, offers it to a friend, and the friend says gracias after one round to signal he is done."},"misunderstanding":{"ar":"قد يظن البعض أن 'gracias' تعني الشكر فقط، لكنها في سياق المتة تعني رفض المزيد.","de":"Manche denken, 'gracias' sei nur ein Dank, doch beim Mate bedeutet es die Ablehnung einer weiteren Runde.","en":"Some think 'gracias' is only thanks, but in mate it means you are declining another round."},"comparison":{"ar":"في باراغواي، غالباً ما تُشرب المتة باردة كـ 'tereré'، بينما في الأرجنتين وأوروغواي تُشرب ساخنة.","de":"In Paraguay wird Mate oft kalt als 'tereré' getrunken, während er in Argentinien und Uruguay heiß getrunken wird.","en":"In Paraguay, mate is often drunk cold as tereré, while in Argentina and Uruguay it is drunk hot."}},{"id":"tra-060","version":2,"slug":"inti-raymi-cusco-re-stages-the-sun-festival","contentType":"note","category":"traditions","title":{"ar":"إنتي رايمي: كوسكو تعيد إحياء عيد الشمس","de":"Inti Raymi: Cusco inszeniert das Sonnenfest neu","en":"Inti Raymi: Cusco re-stages the sun festival"},"deck":{"ar":"في 24 يونيو، تتحول كوسكو إلى مسرح حي لطقوس الإنكا القديمة، حيث يجتمع السكان والسياح لمشاهدة إعادة تمثيل عيد الشمس.","de":"Am 24. Juni verwandelt sich Cusco in eine lebendige Bühne für alte Inka-Rituale, wenn Einheimische und Touristen die Nachstellung des Sonnenfestes erleben.","en":"On 24 June, Cusco becomes a living stage for ancient Inca rituals as locals and tourists gather to witness the re-enactment of the sun festival."},"teaser":{"ar":"إنتي رايمي هو عيد الشمس عند الإنكا، يُحتفل به قرب الانقلاب الشتوي في يونيو. النسخة الحديثة هي إعادة تمثيل مسرحية تُقام في كوسكو في 24 يونيو.","de":"Inti Raymi ist das Sonnenfest der Inka, das nahe der Junisonnenwende gefeiert wird. Die moderne Version ist eine theatralische Nachstellung, die am 24. Juni in Cusco aufgeführt wird.","en":"Inti Raymi is the Inca festival of the sun, held near the June solstice. The modern version is a theatrical re-enactment staged in Cusco on 24 June."},"readingMinutes":1,"sections":{"ar":[{"heading":"من الطقوس القديمة إلى العرض المسرحي","paragraphs":["كان إنتي رايمي عيد الشمس عند الإنكا، يُحتفل به قرب الانقلاب الشتوي في يونيو، ويكرم الإله إنتي بالقرابين والمواكب. في سبعينيات القرن السادس عشر، قمعت السلطات الاستعمارية الاحتفال تحت حكم نائب الملك فرانسيسكو دي توليدو.","تعود النسخة الحديثة إلى عام 1944، عندما قاد مثقفو كوسكو بقيادة همبرتو فيدال أوندا إحياء الاحتفال كعرض مدني. يبدأ العرض في كوريكانشا، معبد الشمس السابق، ثم ينتقل إلى قلعة ساكسايوامان، حيث يؤدي الممثلون أدوار سابا إنكا والكهنة والنبلاء، معظمهم باللغة الكيتشوا."]},{"heading":"عيد يعيش بين الناس","paragraphs":["اليوم، يُعد إنتي رايمي حدثًا سياحيًا رئيسيًا ومصدرًا للهوية المحلية. تشارك المدارس ومجموعات الرقص ومنظمات الأحياء في الأسابيع التي تسبق الاحتفال، مما يجعله مناسبة مجتمعية تتجاوز العرض المسرحي.","يختلف شكل الاحتفال حسب المنطقة والجيل؛ فبعض المجتمعات الريفية تحافظ على تقاليد محلية أقدم، بينما يشارك الشباب في كوسكو بحماس في العروض والرقصات. هذا التنوع يعكس استمرارية الثقافة الأندية في أشكال متجددة."]}],"de":[{"heading":"Vom alten Ritual zur Theateraufführung","paragraphs":["Inti Raymi war das Sonnenfest der Inka, das nahe der Junisonnenwende gefeiert wurde und den Sonnengott Inti mit Opfern und Prozessionen ehrte. In den 1570er Jahren unterdrückten die Kolonialbehörden unter Vizekönig Francisco de Toledo die Zeremonie.","Die moderne Inszenierung stammt aus dem Jahr 1944, als Cusco-Intellektuelle unter Humberto Vidal Unda die Zeremonie als bürgerschaftliches Spektakel wiederbelebten. Die Aufführung beginnt im Qorikancha, dem ehemaligen Sonnentempel, und zieht zur Festung Sacsayhuamán, wo Schauspieler den Sapa Inca, Priester und Adlige spielen, größtenteils auf Quechua."]},{"heading":"Ein Fest, das unter den Menschen lebt","paragraphs":["Heute ist Inti Raymi ein bedeutendes Touristenevent und eine Quelle lokaler Identität. Schulen, Tanzgruppen und Nachbarschaftsorganisationen beteiligen sich in den Wochen vor der Feier, was es zu einem gemeinschaftlichen Anlass macht, der über die Aufführung hinausgeht.","Die Form der Feier variiert je nach Region und Generation; einige ländliche Gemeinden bewahren ältere lokale Traditionen, während junge Menschen in Cusco begeistert an Aufführungen und Tänzen teilnehmen. Diese Vielfalt spiegelt die Kontinuität der andinen Kultur in sich erneuernden Formen wider."]}],"en":[{"heading":"From ancient ritual to theatrical performance","paragraphs":["Inti Raymi was the Inca festival of the sun, held near the June solstice, honouring the sun god Inti with sacrifices and processions. In the 1570s, colonial authorities suppressed the ceremony under Viceroy Francisco de Toledo.","The modern staging dates from 1944, when Cusco intellectuals led by Humberto Vidal Unda revived the ceremony as a civic spectacle. The performance begins at Qorikancha, the former Sun Temple, and moves to the fortress of Sacsayhuamán, with actors playing the Sapa Inca, priests and nobles, largely in Quechua."]},{"heading":"A festival alive among the people","paragraphs":["Today, Inti Raymi is a major tourist event and a source of local identity. Schools, dance groups and neighbourhood organisations take part in the preceding weeks, making it a community occasion that goes beyond the performance.","The form of celebration varies by region and generation; some rural communities maintain older local traditions, while young people in Cusco enthusiastically join in the performances and dances. This diversity reflects the continuity of Andean culture in renewing forms."]}]},"context":{"countries":["PE"],"region":"Cusco","continent":"south-america","languages":["es","qu"],"period":"contemporary"},"tags":["traditions","Cusco"],"sources":[{"organization":"Wikipedia","title":{"ar":"Inti Raymi","de":"Inti Raymi","en":"Inti Raymi"},"url":"https://en.wikipedia.org/wiki/Inti_Raymi","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Peru","de":"Culture of Peru","en":"Culture of Peru"},"url":"https://en.wikipedia.org/wiki/Culture_of_Peru","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في 24 يونيو، تصطف الحشود على الطريق من كوريكانشا إلى ساكسايوامان بينما يحمل موكب بأزياء منسوجة سابا إنكا على محفة، مع دوي الأصداف البحرية.","de":"Am 24. Juni säumen Menschenmengen die Straße vom Qorikancha nach Sacsayhuamán, während eine Prozession in gewebten Kostümen den Sapa Inca auf einer Sänfte trägt und Muscheln erklingen.","en":"On 24 June, crowds line the road from Qorikancha to Sacsayhuamán as a procession in woven costumes carries the Sapa Inca on a litter, with conch shells sounding."},"misunderstanding":{"ar":"إنتي رايمي الحديث هو إحياء مسرحي من القرن العشرين، وليس طقسًا إنكيًا متواصلًا دون انقطاع، وهو واحد من العديد من المهرجانات الأندية.","de":"Der moderne Inti Raymi ist eine theatralische Wiederbelebung aus dem 20. Jahrhundert, kein ununterbrochenes Inka-Ritual, und eines von vielen andinen Festen.","en":"The modern Inti Raymi is a twentieth-century theatrical revival, not an unbroken Inca rite, and it is one Andean festival among many."},"comparison":{"ar":"بينما كان الاحتفال الأصلي طقسًا دينيًا مركزيًا في إمبراطورية الإنكا، أصبح اليوم عرضًا ثقافيًا وسياحيًا يعزز الهوية المحلية.","de":"Während das ursprüngliche Fest ein zentrales religiöses Ritual im Inka-Reich war, ist es heute eine kulturelle und touristische Aufführung, die die lokale Identität stärkt.","en":"While the original festival was a central religious ritual in the Inca Empire, today it is a cultural and tourist performance that reinforces local identity."}},{"id":"tra-061","version":2,"slug":"alasitas-buying-next-year-in-miniature","contentType":"scene","category":"beliefs-and-folklore","title":{"ar":"ألاسيتاس: شراء العام القادم في صورة مصغرة","de":"Alasitas: das nächste Jahr im Miniaturformat kaufen","en":"Alasitas: buying next year in miniature"},"deck":{"ar":"في لاباز، يحوّل مهرجان يناير الرغبات إلى أشياء صغيرة تُبارَك وتُحفظ في البيت.","de":"In La Paz verwandelt ein Januarmarkt Wünsche in kleine Dinge, die gesegnet und zu Hause aufbewahrt werden.","en":"In La Paz, a January fair turns hopes into tiny objects that are blessed and kept at home."},"teaser":{"ar":"في مهرجان ألاسيتاس، يشتري المشاركون نماذج صغيرة لما يطمحون إليه في العام المقبل، من بيوت وسيارات وشهادات، وينالون بركتها.","de":"Beim Alasitas-Festival kaufen die Menschen Miniaturmodelle ihrer Hoffnungen für das kommende Jahr – Häuser, Autos, Diplome – und lassen sie segnen.","en":"At the Alasitas festival, people buy miniature models of what they hope to gain in the coming year—houses, cars, degrees—and have them blessed."},"readingMinutes":1,"sections":{"ar":[{"heading":"سوق الأحلام المصغرة","paragraphs":["في يناير، تتحول شوارع لاباز إلى سوق ضخم يعج بالحرفيين الذين يبيعون نماذج مصغرة: بيوت، سيارات، نقود ورقية، عقود ملكية، شهادات جامعية وجوازات سفر. يشتري الناس ما لا يستطيعون تحمله بالحجم الكامل، ثم يأخذونه للتبارك.","ترتبط التقاليد بجذور أندية سابقة للهسبان، ثم ارتبطت بعيد سيدة لاباز، فامتزجت العناصر الكاثوليكية والأصلية. ويُعتبر إيكيكو، الشخصية الأندية المبتسمة للوفرة، محور الاحتفال، ويُقدَّم عادة كهدية تجلب الرخاء لمن يحسن معاملته."]},{"heading":"بين الاعتقاد والتجارة","paragraphs":["المهرجان من أكبر الأحداث التجارية في المدينة، حيث يلتقي الإيمان بالاقتصاد في مكان واحد. يشتري الطلاب شهادات مصغرة، وتشتري الأسر منازل صغيرة، ويباركها الياتيري بالبخور قبل أن تُوضع على رف في البيت."]}],"de":[{"heading":"Der Markt der kleinen Träume","paragraphs":["Im Januar verwandeln sich die Straßen von La Paz in einen riesigen Markt, auf dem Kunsthandwerker Miniaturen verkaufen: Häuser, Autos, Geldscheine, Grundbucheinträge, Uni-Diplome und Pässe. Die Menschen kaufen, was sie sich in voller Größe noch nicht leisten können, und lassen es segnen.","Die Tradition hat präkolumbische andine Wurzeln und wurde später mit dem Fest Unserer Lieben Frau von La Paz verbunden, sodass katholische und indigene Elemente verschmelzen. Der Ekeko, die lächelnde andine Figur des Überflusses, steht im Mittelpunkt und wird traditionell verschenkt; gut behandelt soll er Wohlstand bringen."]},{"heading":"Zwischen Glaube und Handel","paragraphs":["Das Fest ist eines der größten Handelsereignisse der Stadt, bei dem Glaube und Wirtschaft aufeinandertreffen. Studierende kaufen Miniaturdiplome, Familien kleine Häuser, und ein Yatiri segnet sie mit Weihrauch, bevor sie zu Hause auf ein Regal gestellt werden."]}],"en":[{"heading":"The market of tiny dreams","paragraphs":["In January, the streets of La Paz become a huge market where artisans sell miniatures: houses, cars, banknotes, property deeds, university degrees and passports. People buy what they cannot yet afford in full size, then take it to be blessed.","The tradition has pre-Hispanic Andean roots and was later linked to the feast of Our Lady of La Paz, mixing Catholic and Indigenous elements. The Ekeko, the smiling Andean figure of abundance, is central and is traditionally given as a gift; treated well, it is believed to bring prosperity."]},{"heading":"Between faith and commerce","paragraphs":["The festival is one of the city's biggest commercial events, where belief and economy meet. Students buy miniature diplomas, families buy tiny houses, and a yatiri blesses them with incense before they are placed on a shelf at home."]}]},"context":{"countries":["BO"],"region":"La Paz","continent":"south-america","languages":["es","ay"],"period":"contemporary"},"tags":["beliefs-and-folklore","La Paz"],"sources":[{"organization":"Wikipedia","title":{"ar":"Alasitas","de":"Alasitas","en":"Alasitas"},"url":"https://en.wikipedia.org/wiki/Alasitas","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Pachamama","de":"Pachamama","en":"Pachamama"},"url":"https://en.wikipedia.org/wiki/Pachamama","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طالب يشتري شهادة مصغرة وبيتًا صغيرًا في سوق يناير، ويأخذهما إلى ياتيري للتبارك بالبخور، ثم يحتفظ بهما على رف في المنزل.","de":"Eine Studentin kauft auf dem Januarmarkt ein Miniaturdiplom und ein winziges Haus, lässt sie von einem Yatiri mit Weihrauch segnen und bewahrt sie zu Hause auf einem Regal auf.","en":"A student buys a miniature diploma and a tiny house at the January fair, takes them to a yatiri for a blessing with incense, and keeps them on a shelf at home."},"misunderstanding":{"ar":"يظن البعض أن ألاسيتاس مجرد سوق للهدايا التذكارية، لكنه في جوهره طقس شعبي لطلب الرخاء.","de":"Manche halten Alasitas für einen reinen Souvenirmarkt, doch im Kern ist es ein Volksritual zur Erlangung von Wohlstand.","en":"Some think Alasitas is just a souvenir market, but at heart it is a folk ritual for seeking prosperity."},"comparison":{"ar":"يشبه ألاسيتاس في فكرته تمائم العام الجديد في ثقافات أخرى، لكنه يتميز بكونه سوقًا حيًا وطقسًا جماعيًا.","de":"Alasitas ähnelt Neujahrsamuletten anderer Kulturen, ist aber ein lebendiger Markt und gemeinschaftliches Ritual.","en":"Alasitas resembles New Year amulets in other cultures, but it is distinct as a living market and collective ritual."}},{"id":"tra-062","version":2,"slug":"barranquilla-four-days-of-carnival-on-the-caribbean-coast","contentType":"note","category":"music-and-dance","title":{"ar":"كرنفال بارانكيا: أربعة أيام على الساحل الكاريبي","de":"Barranquilla: Vier Karnevalstage an der Karibikküste","en":"Barranquilla: Four Days of Carnival on the Caribbean Coast"},"deck":{"ar":"مدينة بارانكيا الكولومبية تحتفل بأكبر كرنفال في البلاد، حيث تختلط الألوان والرقصات والهوية الكاريبية في أربعة أيام قبل أربعاء الرماد.","de":"Kolumbiens größter Karneval verwandelt Barranquilla in ein Meer aus Farben, Tänzen und karibischer Identität – vier Tage vor Aschermittwoch.","en":"Colombia's largest carnival transforms Barranquilla into a whirl of color, dance and Caribbean identity in the four days before Ash Wednesday."},"teaser":{"ar":"في بارانكيا، يستعد الجيران طوال العام لكرنفال يملأ الشوارع بالرقص والأقنعة، ويودعون شخصية خوسيلتو كارنفال في نهاية المهرجان.","de":"In Barranquilla planen Nachbarschaftsgruppen das ganze Jahr für den Karneval, der die Straßen mit Tanz und Masken füllt und am Ende Joselito Carnaval verabschiedet.","en":"In Barranquilla, neighborhood groups plan all year for a carnival that fills the streets with dance and masks, bidding farewell to Joselito Carnaval at the end."},"readingMinutes":1,"sections":{"ar":[{"heading":"أربعة أيام من الاحتفال","paragraphs":["يُقام كرنفال بارانكيا في الأيام الأربعة التي تسبق أربعاء الرماد، عادة في فبراير أو مارس، وهو الأكبر في كولومبيا. يفتتح بمعركة الزهور، ثم يتبعه العرض الكبير وعرض غواتشيرنا الليلي.","تشارك مجموعات الأحياء، grupos de barrio، في التخطيط والمنافسة طوال العام. وفي نهاية الاحتفالات، \"يموت\" خوسيلتو كارنفال، الشخصية الكرنفالية المحبوبة، في مشهد وداعي مؤثر."]},{"heading":"رقصات وأقنعة كاريبية","paragraphs":["الماريموندا، المهرج المقنع، هو رمز الكرنفال، إلى جانب رقصات وموسيقى الكومبيا والماباليه وتشاندي. وقد أعلنت اليونسكو الكرنفال تحفة من التراث الشفهي وغير المادي في عام 2003، حيث تشكل هوية المدينة كميناء كاريبي مزيجًا من العناصر الأوروبية والأفريقية والأصلية.","يختلف الكرنفال عن غيره من التقاليد الكولومبية، فهو خاص ببارانكيا والساحل الكاريبي. كما تختلف مظاهره بين الأجيال والأحياء، إذ يحافظ الكبار على التقاليد بينما يضيف الشباب لمساتهم."]}],"de":[{"heading":"Vier Tage des Feierns","paragraphs":["Der Karneval von Barranquilla findet an den vier Tagen vor Aschermittwoch statt, meist im Februar oder März, und ist der größte Kolumbiens. Er beginnt mit der Batalla de Flores, der Schlacht der Blumen, gefolgt von der Gran Parada und der nächtlichen Guacherna-Parade.","Nachbarschaftsgruppen, grupos de barrio, planen und konkurrieren das ganze Jahr über. Am Ende der Feierlichkeiten „stirbt“ Joselito Carnaval, die beliebte Karnevalsfigur, in einer emotionalen Abschiedsszene."]},{"heading":"Karibische Tänze und Masken","paragraphs":["Die Marimonda, ein maskierter Narr, ist das Wahrzeichen des Karnevals, zusammen mit den Tänzen und der Musik von Cumbia, Mapalé und Chandé. Die UNESCO erklärte den Karneval 2003 zum Meisterwerk des mündlichen und immateriellen Erbes, wobei die Hafenidentität der Stadt europäische, afrikanische und indigene Elemente vereint.","Der Karneval unterscheidet sich von anderen kolumbianischen Traditionen, da er spezifisch für Barranquilla und die Karibikküste ist. Auch zwischen den Generationen und Vierteln gibt es Unterschiede: Ältere bewahren Traditionen, während Jüngere eigene Akzente setzen."]}],"en":[{"heading":"Four Days of Celebration","paragraphs":["The Carnival of Barranquilla is held in the four days before Ash Wednesday, usually in February or March, and is Colombia's largest carnival. It opens with the Batalla de Flores, the Battle of Flowers parade, and includes the Gran Parada and the Guacherna night parade.","Neighborhood groups, grupos de barrio, plan and compete all year. At the end of the festivities, the character Joselito Carnaval 'dies' in an emotional farewell scene."]},{"heading":"Caribbean Dances and Masks","paragraphs":["The marimonda, a masked jester figure, is the emblem of the carnival, alongside cumbia, mapalé and chandé dances and music. UNESCO declared it a Masterpiece of Oral and Intangible Heritage in 2003, and the city's Caribbean port identity shapes the mix of European, African and Indigenous elements.","The carnival is specific to Barranquilla and the Caribbean coast rather than a national Colombian custom. It also varies between generations and neighborhoods, with older residents preserving traditions while younger ones add their own touches."]}]},"context":{"countries":["CO"],"region":"Caribbean coast","continent":"south-america","languages":["es"],"period":"contemporary"},"tags":["music-and-dance","Caribbean coast"],"sources":[{"organization":"Wikipedia","title":{"ar":"Carnival of Barranquilla","de":"Carnival of Barranquilla","en":"Carnival of Barranquilla"},"url":"https://en.wikipedia.org/wiki/Carnival_of_Barranquilla","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Cumbia","de":"Cumbia","en":"Cumbia"},"url":"https://en.wikipedia.org/wiki/Cumbia","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في السبت الذي يسبق أربعاء الرماد، تحتجز عائلة مكانًا على الرصيف في شارع 40 لمشاهدة معركة الزهور، بينما ترقص شخصيات الماريموندا بأقنعة طويلة الأنف بجانب العربات.","de":"Am Samstag vor Aschermittwoch sichert sich eine Familie einen Platz am Bordstein der Via 40, um die Batalla de Flores zu sehen, während Marimonda-Figuren mit langnasigen Masken an den Festwagen vorbeitanzen.","en":"On the Saturday before Ash Wednesday, a family stakes out a curb on Via 40 to watch the Batalla de Flores, while marimonda figures in long-nosed masks dance past the floats."},"misunderstanding":{"ar":"يعتقد البعض أن الكرنفال تقليد وطني في كل كولومبيا، لكنه في الواقع خاص ببارانكيا والساحل الكاريبي، وتتغير تواريخه تبعًا لأربعاء الرماد.","de":"Manche glauben, der Karneval sei ein nationaler Brauch in ganz Kolumbien, doch er ist spezifisch für Barranquilla und die Karibikküste, und seine Termine richten sich nach Aschermittwoch.","en":"Some assume the carnival is a nationwide Colombian tradition, but it is specific to Barranquilla and the Caribbean coast, and its dates shift with Ash Wednesday."},"comparison":{"ar":"بينما تشتهر كرنفالات أخرى في أمريكا اللاتينية بعروضها الضخمة، يتميز كرنفال بارانكيا بمشاركة مجموعات الأحياء والرقصات الشعبية مثل الكومبيا والماباليه.","de":"Während andere lateinamerikanische Karnevale für ihre großen Umzüge bekannt sind, zeichnet sich Barranquilla durch die Beteiligung von Nachbarschaftsgruppen und Volkstänze wie Cumbia und Mapalé aus.","en":"While other Latin American carnivals are known for massive parades, Barranquilla's stands out for neighborhood group participation and folk dances like cumbia and mapalé."}},{"id":"tra-063","version":2,"slug":"fiestas-patrias-the-eighteenth-of-september","contentType":"note","category":"traditions","title":{"ar":"عيد الوطن في تشيلي: الثامن عشر من سبتمبر","de":"Fiestas Patrias in Chile: Der 18. September","en":"Fiestas Patrias: Chile's Eighteenth of September"},"deck":{"ar":"تحتفل تشيلي في 18 و19 سبتمبر بذكرى أول مجلس حكم عام 1810، حيث تتحول الأماكن العامة إلى قاعات مؤقتة للرقص والأكل، وتُرفع الطائرات الورقية في السماء.","de":"Am 18. und 19. September feiert Chile den ersten Regierungsrat von 1810. Öffentliche Plätze verwandeln sich in temporäre Hallen mit Tanz und Essen, und Drachen steigen in den Himmel.","en":"On 18 and 19 September, Chile marks the 1810 junta that began independence. Public spaces become temporary halls for dance and food, and kites fill the sky."},"teaser":{"ar":"من الفوندات إلى الكويكا، يجتمع التشيليون حول الطعام والموسيقى في أسبوع عائلي وسياحي كبير.","de":"Von Fondas bis Cueca kommen die Chilenen zu einem großen Familien- und Reisefest zusammen, das von Essen und Musik geprägt ist.","en":"From fondas to cueca, Chileans gather around food and music for a major family and travel week."},"readingMinutes":1,"sections":{"ar":[{"heading":"الفوندات والكويكا: قلب الاحتفال","paragraphs":["تُقام الاحتفالات في الفوندات والراماداس، وهي قاعات وأكشاك مؤقتة تقدم الطعام والموسيقى والرقص. هناك يؤدي الناس رقصة الكويكا، الرقصة الوطنية، وسط أجواء من المرح العائلي.","تشمل الأطعمة النموذجية الإمباناداس والأنتيكوتشوس، ويشرب الكبار تشيتشا أو تيريموتو، وهو كوكتيل نبيذ حلو. وفي هذه الفترة، يطير الأطفال الطائرات الورقية (فولانتينس) في الحدائق."]},{"heading":"ذكرى الاستقلال والعروض العسكرية","paragraphs":["تُحيي هذه التواريخ ذكرى مجلس الحكم الأول الذي بدأ عملية الاستقلال عام 1810، ولهذا يُسمى العيد 'الثامن عشر'. وفي 19 سبتمبر، تقام عروض عسكرية في سانتياغو ومدن أخرى.","يُعد هذا الأسبوع فترة سفر ولقاءات عائلية كبرى. وتختلف العادات بين شمال الأيمارا وجنوب المابوتشي، كما ينتقد بعض التشيليين ثقافة الشرب والمظاهر الوطنية المفرطة."]}],"de":[{"heading":"Fondas und Cueca: Das Herz der Feier","paragraphs":["Die Feierlichkeiten finden in Fondas und Ramadas statt, temporären Hallen und Ständen mit Essen, Musik und Tanz. Dort tanzen die Menschen Cueca, den Nationaltanz, in ausgelassener Familienatmosphäre.","Zu den typischen Speisen gehören Empanadas und Anticuchos, und Erwachsene trinken Chicha oder Terremoto, einen süßen Weincocktail. In dieser Zeit lassen Kinder Drachen (Volantines) in Parks steigen."]},{"heading":"Unabhängigkeit und Militärparaden","paragraphs":["Die Daten erinnern an den ersten Regierungsrat, der 1810 den Unabhängigkeitsprozess einleitete, weshalb das Fest 'Der Achtzehnte' genannt wird. Am 19. September finden Militärparaden in Santiago und anderen Städten statt.","Die Woche ist eine wichtige Reise- und Familienzeit. Die Bräuche unterscheiden sich vom Aymara-Norden bis zum Mapuche-Süden, und einige Chilenen kritisieren die Trinkkultur und nationalistische Zurschaustellung."]}],"en":[{"heading":"Fondas and Cueca: The Heart of the Celebration","paragraphs":["Celebrations centre on fondas and ramadas, temporary halls and stalls with food, music and dancing. There people perform cueca, the national dance, in a lively family atmosphere.","Typical foods include empanadas and anticuchos, and adults drink chicha or terremoto, a sweet wine cocktail. During this time, children fly kites (volantines) in parks."]},{"heading":"Independence and Military Parades","paragraphs":["The dates commemorate the first governing junta that began the independence process in 1810, which is why the holiday is called the eighteenth. On 19 September, military parades take place in Santiago and other cities.","The week is a major travel and family period. Customs differ from the Aymara north to the Mapuche south, and some Chileans criticise the holiday's drinking culture and nationalist display."]}]},"context":{"countries":["CL"],"region":"Chile (nationwide)","continent":"south-america","languages":["es"],"period":"contemporary"},"tags":["traditions","Chile (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Fiestas Patrias (Chile)","de":"Fiestas Patrias (Chile)","en":"Fiestas Patrias (Chile)"},"url":"https://en.wikipedia.org/wiki/Fiestas_Patrias_(Chile)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Cueca","de":"Cueca","en":"Cueca"},"url":"https://en.wikipedia.org/wiki/Cueca","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في فترة بعد ظهر الثامن عشر، تقود عائلة من سانتياغو إلى فوندا في حديقة، وتأكل الإمباناداس، وترقص الكويكا مرة واحدة، وتدع الأطفال يطيرون طائرة ورقية.","de":"Am Nachmittag des 18. fährt eine Familie aus Santiago zu einer Fonda in einem Park, isst Empanadas, tanzt eine Cueca und lässt die Kinder einen Drachen steigen.","en":"On the afternoon of the 18th, a Santiago family drives to a fonda in a park, eats empanadas, dances one cueca and lets the children fly a kite."},"misunderstanding":{"ar":"يعتقد البعض أن العيد يحتفل بتوقيع إعلان الاستقلال في فبراير 1818، لكنه في الواقع يحيي ذكرى مجلس الحكم الأول في 1810.","de":"Manche glauben, das Fest feiere die Unterzeichnung der Unabhängigkeitserklärung im Februar 1818, doch tatsächlich ehrt es den ersten Regierungsrat von 1810.","en":"Some believe the holiday celebrates the signing of the declaration of independence in February 1818, but it actually honours the first junta of 1810."},"comparison":{"ar":"بينما تحتفل دول أخرى باستقلالها بعروض عسكرية فقط، تجمع تشيلي بين الاحتفال الشعبي بالطعام والرقص والعروض الرسمية في مزيج فريد.","de":"Während andere Länder ihre Unabhängigkeit nur mit Militärparaden feiern, verbindet Chile Volksfest mit Essen, Tanz und offiziellen Paraden zu einer einzigartigen Mischung.","en":"While other countries celebrate independence with military parades alone, Chile combines popular festivity with food, dance and official parades in a unique mix."}},{"id":"tra-064","version":2,"slug":"candombe-the-drums-that-belong-to-a-neighbourhood","contentType":"note","category":"music-and-dance","title":{"ar":"طبول الكاندومبي في حيّها","de":"Candombe: Trommeln, die einem Viertel gehören","en":"Candombe: drums that belong to a neighbourhood"},"deck":{"ar":"في مونتيفيديو، يجتمع سكان بارّيو سور وباليرمو حول الطبول كل فبراير، فيحمل الحيّ إيقاعه بنفسه.","de":"In Montevideo versammeln sich die Menschen in Barrio Sur und Palermo jeden Februar um die Trommeln – der Rhythmus gehört dem Viertel.","en":"In Montevideo, people gather around the drums in Barrio Sur and Palermo every February, and the rhythm stays with the neighbourhood."},"teaser":{"ar":"الكاندومبي تقليد أفرو-أوروغوياني يعيش في الأحياء ويُعزف في الشوارع، حيث تلتقي الفرَق بالجمهور سنويًا.","de":"Candombe ist eine afro-uruguayische Musik- und Tanztradition, die in den Straßen von Montevideo lebt und jedes Jahr beim Llamadas-Fest erklingt.","en":"Candombe is an Afro-Uruguayan music and dance tradition that lives in the streets of Montevideo and fills them each February during Llamadas."},"readingMinutes":1,"sections":{"ar":[{"heading":"إيقاع من قلب الحيّ","paragraphs":["الكاندومبي تقليد موسيقي ورقصي أفرو-أوروغوياني، تعود جذوره إلى الأفارقة المستعبدين الذين جُلبوا إلى مونتيفيديو ومنطقة ريو دي لا بلاتا.","تعزفه فرَق تُسمّى كومبارساس بثلاث طبول: تشيكو وريبيكي وبيانو، مع قسم إيقاعي من ماديرا وراقصين بأزياء ملوّنة.","ويختلف حضور التقليد بين الأجيال: بعض الشباب يتعلمه في ورش الأحياء، بينما يحمله كبار السن في الذاكرة والمناسبات."]},{"heading":"شوارع تحتفل كل فبراير","paragraphs":["كل فبراير يملأ مهرجان الّاماداس السنوي شوارع بارّيو سور وباليرمو بالطبول، ويبقى هذان الحيان قلب التقليد النابض.","وفي 2009 أدرجت اليونسكو الكاندومبي الأوروغوياني في قائمتها التمثيلية للتراث الثقافي غير المادي.","يرتبط التقليد بحياة المجتمع الأفرو-أوروغوياني، وقد دخل الهوية الوطنية، ما أثار نقاشات حول الاستحواذ والتسويق."]}],"de":[{"heading":"Ein Rhythmus aus dem Viertel","paragraphs":["Candombe ist eine afro-uruguayische Musik- und Tanztradition; ihre Wurzeln liegen bei den versklavten Afrikanern, die nach Montevideo und an den Río de la Plata gebracht wurden.","Gespeilt wird sie von Comparsas mit drei Trommeln – chico, repique und piano –, dazu eine Madera-Rhythmusgruppe und Tänzerinnen und Tänzer in farbenfrohen Kostümen.","Wie stark der Brauch gelebt wird, unterscheidet sich je nach Region und Generation: Manche Jugendliche lernen ihn in Nachbarschaftswerkstätten, ältere Menschen tragen ihn in Erinnerung und Festen weiter."]},{"heading":"Straßen feiern im Februar","paragraphs":["Jedes Jahr im Februar füllt das Llamadas-Festival die Straßen von Barrio Sur und Palermo mit Trommeln; diese Viertel bleiben das Herz der Tradition.","2009 nahm die UNESCO den uruguayischen Candombe in die Repräsentative Liste des immateriellen Kulturerbes auf.","Die Tradition ist eng mit dem Leben der afro-uruguayischen Gemeinschaft verbunden und wurde Teil der nationalen Identität – was Debatten über Aneignung und Kommerzialisierung auslöste."]}],"en":[{"heading":"A rhythm rooted in the neighbourhood","paragraphs":["Candombe is an Afro-Uruguayan music and dance tradition with roots among enslaved Africans brought to Montevideo and the Río de la Plata.","Comparsas perform it with three drums — chico, repique and piano — plus a madera rhythm section and dancers in colourful costumes.","How strongly the tradition is lived varies by region and generation: some young people learn it in neighbourhood workshops, while older residents carry it through memory and local gatherings."]},{"heading":"Streets that celebrate every February","paragraphs":["The annual Llamadas festival in February fills the streets of Barrio Sur and Palermo with drumming, and those areas remain the tradition's heart.","In 2009 UNESCO inscribed Uruguayan candombe on its Representative List of Intangible Cultural Heritage.","The tradition is tied to Afro-Uruguayan community life and has been incorporated into national identity, prompting debates about appropriation and commercialisation."]}]},"context":{"countries":["UY"],"region":"Montevideo","continent":"south-america","languages":["es"],"period":"contemporary"},"tags":["music-and-dance","Montevideo"],"sources":[{"organization":"Wikipedia","title":{"ar":"Candombe","de":"Candombe","en":"Candombe"},"url":"https://en.wikipedia.org/wiki/Candombe","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Uruguay","de":"Culture of Uruguay","en":"Culture of Uruguay"},"url":"https://en.wikipedia.org/wiki/Culture_of_Uruguay","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"خلال الّاماداس، تستدير فرقة من بارّيو سور عند زاوية بأربعين عازف طبل في تشكيلة، تحفظ طبول التشيكو المنخفضة الإيقاع بينما يرتجل الريبيكي.","de":"Während der Llamadas biegt eine Comparsa aus Barrio Sur um die Ecke: vierzig Trommler in Formation, die tiefen chico-Trommeln halten den Takt, während das repique improvisiert.","en":"During the Llamadas, a comparsa from Barrio Sur turns a corner with forty drummers in formation, the low chico drums keeping time while the repique improvises."},"misunderstanding":{"ar":"ليس الكاندومبي حفلًا سياحيًا منفصلًا عن الناس؛ إنه ممارسة حيّة داخل أحياء محددة، وحضوره في المسارح لا يلغي انتماءه المجتمعي.","de":"Candombe ist keine touristische Show ohne Bezug zu den Menschen; er ist gelebte Praxis in bestimmten Vierteln, und ein Auftritt auf der Bühne hebt seine Verwurzelung nicht auf.","en":"Candombe is not a tourist show detached from people; it is a living practice within specific neighbourhoods, and a stage performance does not erase its community roots."},"comparison":{"ar":"يشبه الكاندومبي في وظيفته الاجتماعية فرق السامبا في البرازيل، لكنه يبقى مرتبطًا بأحياء مونتيفيديو وبطبوله الثلاثة المميزة.","de":"In seiner sozialen Funktion ähnelt Candombe den Samba-Gruppen Brasiliens, bleibt aber an die Viertel Montevideos und seine drei besonderen Trommeln gebunden.","en":"In its social role, candombe resembles Brazilian samba groups, yet it stays tied to Montevideo's neighbourhoods and its three distinctive drums."}},{"id":"tra-065","version":2,"slug":"welcome-to-country-what-the-words-actually-do","contentType":"note","category":"social-behaviour","title":{"ar":"كلمة ترحيب على الأرض","de":"Willkommen auf dem Land","en":"Welcome to Country, spoken and owned"},"deck":{"ar":"بروتوكول يفتتح المناسبات في أستراليا، يقدّمه أصحاب الأرض التقليديون، ويختلف عن الاعتراف الذي يقدّمه أي حاضر.","de":"Ein Protokoll eröffnet in Australien wichtige Anlässe: Traditionelle Eigentümer heißen Gäste willkommen, alle anderen können nur anerkennen.","en":"A formal protocol opens Australian events: Traditional Owners welcome visitors to their Country, while everyone else can only acknowledge."},"teaser":{"ar":"ما معنى أن تُفتتح مناسبة رسمية بترحيب من أصحاب الأرض؟ وكيف يختلف عن الاعتراف الذي يقدّمه الحاضرون؟","de":"Was geschieht, wenn eine Veranstaltung mit einem Willkommen der Traditionellen Eigentümer beginnt – und warum ist das nicht dasselbe wie eine Anerkennung?","en":"What happens when an event opens with a Welcome from Traditional Owners, and why is it not the same as an Acknowledgement?"},"readingMinutes":1,"sections":{"ar":[{"heading":"من يملك حق الترحيب","paragraphs":["الترحيب بالأرض بروتوكول رسمي يقدّمه أصحاب الأرض التقليديون في بداية مناسبة مهمة على أرضهم، وقد يشمل كلاماً أو غناءً أو دخاناً أو رقصاً.","السلطة هنا جوهرية: يجب أن يصدر الترحيب من الأشخاص الصحيحين لتلك الأرض، لا من أي شخص من السكان الأصليين، واستخدامه بلا سلطة قد يسبّب إساءة."]},{"heading":"الاعتراف وانتشار البروتوكول","paragraphs":["يختلف الترحيب عن الاعتراف بالأرض، الذي يمكن لأي حاضر أن يقدّمه بذكر أصحاب الأرض التقليديين ورعايتهم المستمرة.","انتشر البروتوكول في المؤسسات العامة الأسترالية منذ التسعينيات والألفينيات، وصار افتتاح البرلمان يتضمنه عادة.","تتباين البروتوكولات كثيراً بين المجموعات اللغوية، ولا تشمل كل مناسبة ترحيباً؛ والزائرون يقدّمون اعترافاً لا ترحيباً.","وتختلف الممارسة أيضاً بين المناطق والأجيال، إذ يتمسّك بعض الشيوخ بالصيغة الدقيقة بينما يبسّطها الشباب في المدن."]}],"de":[{"heading":"Wem das Willkommen gehört","paragraphs":["Ein Welcome to Country ist ein formelles Protokoll, das Traditionelle Eigentümer zu Beginn eines bedeutenden Anlasses auf ihrem Land halten; es kann Rede, Gesang, Rauch oder Tanz umfassen.","Die Befugnis zählt: Ein Willkommen muss von den richtigen Menschen für dieses Land kommen, nicht von irgendeiner indigenen Person; ohne Befugnis kann es kränken."]},{"heading":"Anerkennung und Verbreitung","paragraphs":["Davon zu unterscheiden ist die Acknowledgement of Country, die jeder Anwesende anbieten kann, indem er die Traditionellen Eigentümer und ihre fortbestehende Obhut nennt.","Seit den 1990er und 2000er Jahren verbreitete sich das Protokoll in australischen öffentlichen Institutionen; die Parlamentseröffnung enthält es heute oft.","Protokolle unterscheiden sich stark zwischen Sprachgruppen, und nicht jede Veranstaltung umfasst eines; Besucher geben eine Anerkennung, niemals ein Willkommen.","Auch regional und zwischen Generationen variiert die Praxis: Manche Älteste bestehen auf der genauen Form, jüngere Stadtbewohner vereinfachen sie."]}],"en":[{"heading":"Who holds the authority","paragraphs":["A Welcome to Country is a formal protocol delivered by Traditional Owners at the start of a significant event on their Country, and may include speech, song, smoke or dance.","Authority matters: a Welcome must come from the right people for that Country, not from any Aboriginal person, and using it without authority can cause offence."]},{"heading":"Acknowledgement and spread","paragraphs":["It is distinct from an Acknowledgement of Country, which anyone present can offer, naming the Traditional Owners and their continuing custodianship.","The protocol spread through Australian public institutions from the 1990s and 2000s, and the opening of parliament now commonly includes one.","Protocols vary enormously between language groups, and not every event includes one; visitors may give an Acknowledgement, never a Welcome.","Practice also shifts by region and generation, with some Elders insisting on exact form while younger city dwellers simplify it."]}]},"context":{"countries":["AU"],"region":"Australia (nationwide)","community":"Aboriginal and Torres Strait Islander peoples","continent":"oceania","languages":[],"period":"contemporary"},"tags":["social-behaviour","Australia (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Welcome to Country","de":"Welcome to Country","en":"Welcome to Country"},"url":"https://en.wikipedia.org/wiki/Welcome_to_Country","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Australian Aboriginal culture","de":"Australian Aboriginal culture","en":"Australian Aboriginal culture"},"url":"https://en.wikipedia.org/wiki/Australian_Aboriginal_culture","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في حفل تخرّج جامعي، يرحّب شيخ من الأمة المحلية بالحضور بلغته وبالإنجليزية قبل أن تبدأ المراسم.","de":"Bei einer Universitätsfeier heißt ein Ältester der lokalen Nation das Publikum erst in seiner Sprache, dann auf Englisch willkommen, bevor die Zeremonie beginnt.","en":"At a university graduation, an Elder from the local nation welcomes the audience in language and English before the ceremony begins."},"misunderstanding":{"ar":"ثمة فهم خاطئ شائع بأن أي شخص من السكان الأصليين يستطيع تقديم ترحيب في أي مكان، لكن الحق مرتبط بأصحاب تلك الأرض تحديداً.","de":"Oft wird angenommen, jede indigene Person könne überall ein Willkommen sprechen; doch das Recht ist an die Eigentümer jenes Landes gebunden.","en":"A common mistake is assuming any Aboriginal person can deliver a Welcome anywhere; the right belongs to the owners of that particular Country."},"comparison":{"ar":"يشبه الأمر مضيفاً يفتح باب بيته، لا ضيفاً يلقي تحية عامة؛ فالترحيب حقّ لأصحاب المكان والاعتراف واجب على الحاضرين.","de":"Es ist wie ein Gastgeber, der die Tür öffnet, nicht wie ein Gast, der grüßt: Das Willkommen gehört den Eigentümern, die Anerkennung den Anwesenden.","en":"Think of a host opening their own door rather than a guest offering a general greeting: the Welcome belongs to owners, the Acknowledgement to those present."}},{"id":"tra-066","version":2,"slug":"tangihanga-three-days-on-the-marae","contentType":"note","category":"family-and-friendship","title":{"ar":"تانهيهانغا: ثلاثة أيام على الماراي","de":"Tangihanga: drei Tage auf dem Marae","en":"Tangihanga: three days on the marae"},"deck":{"ar":"في نيوزيلندا، تجمع طقوس الدفن الماورية الأهل والأصدقاء لعدة أيام في الماراي، حيث يُودَّع الموتى بالكلمات والأغاني.","de":"In Neuseeland versammelt die māorische Bestattungszeremonie Familie und Freunde über mehrere Tage auf dem Marae, wo die Verstorbenen mit Worten und Liedern verabschiedet werden.","en":"In New Zealand, the Māori funeral rite brings family and friends together for several days on the marae, where the deceased are farewelled with speeches and songs."},"teaser":{"ar":"تانهيهانغا هي طقس الدفن الماوري الذي يستمر عدة أيام على الماراي، حيث يرقد المتوفى في التابوت المفتوح بينما يزور المعزون لتقديم الاحترام.","de":"Tangihanga ist die māorische Bestattungszeremonie, die meist mehrere Tage auf einem Marae dauert, während der Verstorbene in einem offenen Sarg im Wharenui liegt und Besucher ihre Ehre erweisen.","en":"Tangihanga is the Māori funeral rite, usually lasting several days on a marae, with the deceased lying in an open casket in the wharenui while visitors pay respects."},"readingMinutes":1,"sections":{"ar":[{"heading":"بروتوكول اللقاء والوداع","paragraphs":["تانهيهانغا هو طقس الدفن الماوري، ويستمر عادة عدة أيام على الماراي. يرقد المتوفى في تابوت مفتوح داخل الوارينوي، بيت الاجتماع، بينما يأتي الزوار لتقديم الاحترام. يُستقبل الجثمان بالخطب، والوايكوريرو، والأغاني، والواياتا، والكارانغا، وهي النداءات الاحتفالية التي تُؤديها النساء عادةً.","يبيت المعزون في كثير من الأحيان ويشتركون في الطعام. يتم الدفن عادة في اليوم الثالث، يتبعه حفل هاكاري، ثم في وقت لاحق هورا كوهاتو، وهو كشف النقاب عن شاهد القبر.","يختلف البروتوكول بين القبائل والجماعات الفرعية، وليس كل العائلات الماورية تتبع الشكل نفسه، لذا يجب على الزوار أن يسألوا بدلاً من أن يفترضوا. كما يتباين الأمر بين الأجيال والمناطق، إذ تتكيف العائلات في المدن مع تقاليد الماراي."]},{"heading":"التكيف في المدينة والشتات","paragraphs":["يستمر الطقس في الحياة الحضرية وحياة الشتات، مع تانهيهانغا القائمة على الماراي والتكيفات. كثير من الباكيه ي encounteringه من خلال العمل أو المجتمع.","يحكم التيكانغا، البروتوكول، ترتيب الجلوس وترتيب التحدث وأدوار المانهيري، الزوار، والتانغاتا وينوا، المضيفين.","في ماراي خارج روتوروا، يُدعى الزوار إلى الساحة، وينزعون أحذيتهم، ويحيون المتوفى بخطبة وأغنية، ثم يتشاركون وجبة في قاعة الطعام."]}],"de":[{"heading":"Protokoll der Begegnung und des Abschieds","paragraphs":["Tangihanga ist die māorische Bestattungszeremonie und dauert gewöhnlich mehrere Tage auf einem Marae. Der Verstorbene liegt in einem offenen Sarg im Wharenui, dem Versammlungshaus, während Besucher ihre Ehre erweisen. Der Leichnam wird mit Reden, Whaikōrero, Liedern, Waiata und Karanga, den zeremoniellen Rufen, die meist von Frauen gegeben werden, begrüßt.","Trauernde bleiben oft über Nacht und teilen das Essen. Die Beerdigung findet meist am dritten Tag statt, gefolgt von einem Hākari-Festmahl und später einem Hura Kōhatu, der Enthüllung des Grabsteins.","Das Protokoll unterscheidet sich zwischen Iwi und Hapū, und nicht alle māorischen Whānau folgen demselben Format, daher sollten Besucher fragen statt anzunehmen. Auch zwischen Generationen und Regionen gibt es Unterschiede, da städtische Familien die Marae-Traditionen anpassen."]},{"heading":"Anpassung in Stadt und Diaspora","paragraphs":["Das Ritual lebt im städtischen und diasporischen Leben weiter, mit marae-basierten Tangihanga und Anpassungen. Viele Pākehā begegnen ihm durch Arbeit oder Gemeinschaft.","Tikanga, das Protokoll, regelt Sitzordnung, Redereihenfolge und die Rollen von Manuhiri, den Besuchern, und Tangata Whenua, den Gastgebern.","Auf einem Marae außerhalb von Rotorua werden Besucher auf den Hof gerufen, ziehen ihre Schuhe aus, begrüßen den Verstorbenen mit einer Rede und einem Lied und teilen dann eine Mahlzeit im Speisesaal."]}],"en":[{"heading":"Protocol of encounter and farewell","paragraphs":["Tangihanga is the Māori funeral rite, usually lasting several days on a marae. The deceased lies in an open casket in the wharenui, the meeting house, while visitors pay respects. The body is greeted with speeches, whaikōrero, songs, waiata, and karanga, the ceremonial calls usually given by women.","Mourners often stay overnight and share food. Burial usually occurs on the third day, followed by a hākari feast and later a hura kōhatu, the unveiling of the headstone.","Protocol differs between iwi and hapū, and not all Māori whānau follow the same format, so visitors should ask rather than assume. It also varies between generations and regions, as urban families adapt marae-based traditions."]},{"heading":"Adaptation in city and diaspora","paragraphs":["The ritual continues in urban and diaspora life, with marae-based tangihanga and adaptations. Many Pākehā encounter it through work or community.","Tikanga, protocol, governs seating, speaking order and the roles of manuhiri, visitors, and tangata whenua, hosts.","At a marae outside Rotorua, visitors are called onto the courtyard, remove their shoes, greet the deceased with a speech and song, then share a meal in the dining hall."]}]},"context":{"countries":["NZ"],"region":"Aotearoa New Zealand","community":"Māori","continent":"oceania","languages":["mi","en"],"period":"contemporary"},"tags":["family-and-friendship","Aotearoa New Zealand"],"sources":[{"organization":"Wikipedia","title":{"ar":"Tangihanga","de":"Tangihanga","en":"Tangihanga"},"url":"https://en.wikipedia.org/wiki/Tangihanga","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Māori culture","de":"Māori culture","en":"Māori culture"},"url":"https://en.wikipedia.org/wiki/M%C4%81ori_culture","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في ماراي خارج روتوروا، يُدعى الزوار إلى الساحة، وينزعون أحذيتهم، ويحيون المتوفى بخطبة وأغنية، ثم يتشاركون وجبة في قاعة الطعام.","de":"Auf einem Marae außerhalb von Rotorua werden Besucher auf den Hof gerufen, ziehen ihre Schuhe aus, begrüßen den Verstorbenen mit einer Rede und einem Lied und teilen dann eine Mahlzeit im Speisesaal.","en":"At a marae outside Rotorua, visitors are called onto the courtyard, remove their shoes, greet the deceased with a speech and song, then share a meal in the dining hall."},"misunderstanding":{"ar":"قد يظن البعض أن تانهيهانغا مناسبة حزينة فقط، لكنها تجمع أيضاً بين الأهل والمجتمع في رعاية مشتركة.","de":"Manche mögen denken, Tangihanga sei nur eine traurige Angelegenheit, doch sie bringt auch Familie und Gemeinschaft in gemeinsamer Fürsorge zusammen.","en":"Some may think tangihanga is only a sombre occasion, but it also brings family and community together in shared care."},"comparison":{"ar":"مثل العديد من طقوس الحداد، تمنح تانهيهانغا وقتاً للتعبير عن الحزن والدعم، لكنها تتميز بالبروتوكول الصارم على الماراي.","de":"Wie viele Trauerrituale gibt Tangihanga Zeit, Trauer und Unterstützung auszudrücken, zeichnet sich aber durch strenges Protokoll auf dem Marae aus.","en":"Like many mourning rituals, tangihanga gives time to express grief and support, but it is distinguished by strict protocol on the marae."}},{"id":"tra-067","version":2,"slug":"fa-a-samoa-the-values-behind-the-welcome","contentType":"note","category":"social-behaviour","title":{"ar":"فآ ساموا: قيم الترحيب","de":"Fa'a Samoa: Werte der Gastfreundschaft","en":"Fa'a Samoa: The Values Behind the Welcome"},"deck":{"ar":"في ساموا، الترحيب ليس مجرد عادة، بل هو تعبير عن نظام حياة كامل يقوم على الاحترام والمحبة والعهد المقدس.","de":"In Samoa ist Gastfreundschaft kein bloßer Brauch, sondern Ausdruck einer Lebensweise, die auf Respekt, Liebe und heiligem Bund beruht.","en":"In Samoa, welcoming is not just a custom but an expression of a whole way of life built on respect, love, and sacred covenant."},"teaser":{"ar":"كيف يعيش السامويون قيم فآ ساموا في حياتهم اليومية؟ من نظام الماتاي إلى طقوس الكافا، تعرف على ثقافة الترحيب.","de":"Wie leben Samoaner die Werte von Fa'a Samoa im Alltag? Vom Matai-System bis zur Kava-Zeremonie – entdecken Sie die Kultur des Willkommens.","en":"How do Samoans live the values of Fa'a Samoa in daily life? From the matai system to kava ceremonies, explore the culture of welcome."},"readingMinutes":1,"sections":{"ar":[{"heading":"الاحترام والمحبة: أسس فآ ساموا","paragraphs":["فآ ساموا، أو الطريقة الساموية، هي نمط حياة يقوم على ثلاثة أعمدة: الاحترام (فآألوا)، والمحبة والرحمة (ألوفا)، والعهد المقدس بين الأخ والأخت (فيغايغا). هذه القيم تحكم العلاقات اليومية وتوجه السلوك في المجتمع.","ينظم نظام الماتاي (الزعماء) حياة القرية؛ حيث تُمنح ألقاب الماتاي من قبل مجالس العائلة، بينما تنظم مجالس القرية (فونو) الأرض والسلوك والاحترام. العائلة الممتدة (آيغا) تجمع الموارد وتحويلات الأقارب في الخارج، والحياة الكنسية ويوم الأحد محوريان في معظم القرى."]},{"heading":"الترحيب والخدمة: طقوس الضيافة","paragraphs":["تشمل الترحيبات الرسمية طقوس الكافا (آفا) وتبادل الحصائر الثمينة (إي توغا)، بينما يؤدي الشباب غير الحاصلين على ألقاب (تاوليآليآ) خدمة (تاوتوا) لعائلاتهم وزعمائهم. هذه الطقوس تعكس التزامًا جماعيًا بالضيافة والاحترام."]}],"de":[{"heading":"Respekt und Liebe: Die Grundlagen von Fa'a Samoa","paragraphs":["Fa'a Samoa, die samoanische Lebensweise, benennt eine Lebensart, die auf fa'aaloalo (Respekt), alofa (Liebe und Mitgefühl) und feagaiga (dem heiligen Bund zwischen Bruder und Schwester) aufbaut. Diese Werte prägen die täglichen Beziehungen und das Verhalten in der Gesellschaft.","Das Matai-Häuptlingssystem organisiert das Dorfleben: Matai-Titel werden von Familienräten verliehen, und Dorfräte (fono) regeln Land, Verhalten und Zeremonien. Die Großfamilie (aiga) bündelt Ressourcen und Überweisungen von Verwandten im Ausland, und das Kirchenleben sowie die Sonntags observance sind in den meisten Dörfern zentral."]},{"heading":"Willkommen und Dienst: Rituale der Gastfreundschaft","paragraphs":["Formelle Willkommensrituale umfassen die 'ava-Zeremonie (Kava) und den Austausch feiner Matten (ie toga), während junge Männer ohne Titel (taule'ale'a) den Dienst (tautua) für ihre Familien und Häuptlinge verrichten. Diese Rituale spiegeln ein kollektives Engagement für Gastfreundschaft und Respekt."]}],"en":[{"heading":"Respect and Love: The Foundations of Fa'a Samoa","paragraphs":["Fa'a Samoa, the Samoan way, names a way of life built on fa'aaloalo (respect), alofa (love and compassion), and feagaiga (the sacred covenant between brother and sister). These values govern daily relationships and guide behaviour in society.","The matai chiefly system organises village life: matai titles are conferred by family councils, and village fono councils regulate land, behaviour, and ceremonies. The extended family, aiga, pools resources and remittances from relatives overseas, and church life and Sunday observance are central in most villages."]},{"heading":"Welcome and Service: Rituals of Hospitality","paragraphs":["Formal welcomes include the 'ava (kava) ceremony and the exchange of fine mats (ie toga), while untitled young men (taule'ale'a) perform service (tautua) for their families and chiefs. These rituals reflect a collective commitment to hospitality and respect."]}]},"context":{"countries":["WS"],"region":"Samoa","community":"Samoan","continent":"oceania","languages":["sm","en"],"period":"contemporary"},"tags":["social-behaviour","Samoa"],"sources":[{"organization":"Wikipedia","title":{"ar":"Fa'a Samoa","de":"Fa'a Samoa","en":"Fa'a Samoa"},"url":"https://en.wikipedia.org/wiki/Fa'a_Samoa","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Samoa","de":"Culture of Samoa","en":"Culture of Samoa"},"url":"https://en.wikipedia.org/wiki/Culture_of_Samoa","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في جنازة عائلية في أبيا، تُتبادل الحصائر، ويُحضر وعاء الكافا، ويقدم الشباب الطعام ويحملون الماء بينما يتحدث الماتاي حسب رتبهم.","de":"Bei einer Familienbeerdigung in Apia werden Matten ausgetauscht, die 'ava-Schale vorbereitet, und junge Männer servieren Essen und tragen Wasser, während die Matai nach Rang sprechen.","en":"At a family funeral in Apia, mats are exchanged, the 'ava bowl is prepared, and young men serve food and carry water while the matai speak in order of rank."},"misunderstanding":{"ar":"غالبًا ما يُنظر إلى فآ ساموا من قبل الغرباء على أنها مجرد تقاليد فولكلورية، بينما هي نظام قانوني واجتماعي حي. كما أن الممارسة تختلف بين ساموا وساموا الأمريكية وبين العائلات، وقد يتم رومنسيتها من قبل الخارجيين.","de":"Fa'a Samoa wird von Außenstehenden oft als folkloristische Tradition missverstanden, ist aber ein lebendiges rechtliches und soziales System. Die Praxis unterscheidet sich zwischen Samoa und Amerikanisch-Samoa sowie zwischen Familien und kann von Außenstehenden romantisiert werden.","en":"Fa'a Samoa is often seen by outsiders as merely folkloric tradition, but it is a living legal and social system. Practice differs between Samoa and American Samoa and between families, and the concept can be romanticised by outsiders."},"comparison":{"ar":"بينما تركز العديد من الثقافات على الفردية، تؤكد فآ ساموا على الجماعة والخدمة والاحترام الهرمي. هذا يختلف عن المجتمعات الغربية حيث تُتخذ القرارات بشكل فردي.","de":"Während viele Kulturen Individualismus betonen, legt Fa'a Samoa Wert auf Gemeinschaft, Dienst und hierarchischen Respekt. Dies unterscheidet sich von westlichen Gesellschaften, in denen Entscheidungen individuell getroffen werden.","en":"While many cultures emphasise individualism, Fa'a Samoa stresses community, service, and hierarchical respect. This differs from Western societies where decisions are made individually."}},{"id":"tra-068","version":2,"slug":"the-kava-circle-rank-roots-and-quiet-talk","contentType":"note","category":"food-and-hospitality","title":{"ar":"دائرة الكافا: رتبة وجذور وحديث هادئ","de":"Der Kava-Kreis: Rang, Wurzeln und stille Gespräche","en":"The kava circle: rank, roots and quiet talk"},"deck":{"ar":"في بولينيزيا وفيجي، الكافا ليست مجرد مشروب، بل طقس اجتماعي يعكس التسلسل والانتماء.","de":"In Polynesien und Fidschi ist Kava mehr als ein Getränk – es ist ein soziales Ritual, das Hierarchie und Gemeinschaft spiegelt.","en":"In Polynesia and Fiji, kava is more than a drink—it is a social ritual that reflects hierarchy and belonging."},"teaser":{"ar":"دائرة الكافا تجمع الناس حول وعاء واحد، حيث تُقدَّم الكؤوس حسب الرتبة، ويستمر الحديث حتى وقت متأخر من الليل.","de":"Der Kava-Kreis versammelt Menschen um eine Schale, in der die Becher nach Rang gereicht werden und Gespräche bis tief in die Nacht dauern.","en":"The kava circle gathers people around a bowl, where cups are served by rank and conversation flows late into the night."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقس يعكس الرتبة","paragraphs":["في تونغا، تُقام دائرة الكافا الرسمية، فايكافا، حيث يوضع وعاء تانوءا في المركز، ويقوم خادم توءا بتحضير المشروب، بينما يشرف ماتابولي على النظام. يُقدَّم الكأس حسب الرتبة، مما يعكس مكانة كل شخص في المجتمع.","في فيجي، تُعد الياقونا محور الترحيب في القرى، بينما في ساموا، تُقام مراسم الأفا في المناسبات الرسمية، حيث تُقدَّم كأس الرئيس الأعلى أولاً. تختلف البروتوكولات بين هذه البلدان، فدائرة الكافا ليست مؤسسة إقليمية واحدة."]},{"heading":"حديث وموسيقى حتى وقت متأخر","paragraphs":["غالباً ما تستمر الجلسات حتى وقت متأخر من الليل، مع موسيقى الجيتار والمحادثات. في تونغا، تُعد دائرة الكافا مؤسسة اجتماعية حيث تُناقش الأخبار والسياسة، وتُروى الحكايات. يختلف الأسلوب بين الأجيال والمناطق، فبعض الشباب يضيفون لمسات عصرية بينما يتمسك الكبار بالتقاليد."]}],"de":[{"heading":"Ein Ritual, das Rang widerspiegelt","paragraphs":["In Tonga findet der formelle Kava-Kreis, Faikava, statt: Die Tano'a-Schale steht im Zentrum, ein Tou'a-Server bereitet das Getränk zu, und Matāpule-Aufseher achten auf die Ordnung. Die Becher werden nach Rang gereicht, was die Stellung jedes Einzelnen widerspiegelt.","In Fidschi ist Yaqona zentral für Dorfempfänge, während in Samoa die 'Ava-Zeremonie formelle Anlässe markiert, bei der die Tasse des Oberhäuptlings zuerst serviert wird. Die Protokolle unterscheiden sich zwischen Tonga, Fidschi und Samoa; der Kava-Kreis ist keine einheitliche regionale Institution."]},{"heading":"Gespräche und Musik bis spät in die Nacht","paragraphs":["Oft dauern die Sitzungen bis tief in die Nacht, begleitet von Gitarrenmusik und Gesprächen. In Tonga ist der Kava-Kreis eine soziale Institution, in der Nachrichten und Politik diskutiert werden. Der Stil variiert je nach Region und Generation – manche Jugendliche bringen moderne Elemente ein, während Ältere an Traditionen festhalten."]}],"en":[{"heading":"A ritual that reflects rank","paragraphs":["In Tonga, the formal kava circle, faikava, places the tano'a bowl in the centre, with a tou'a server preparing the drink and matāpule attendants overseeing order. Cups are passed according to rank, reflecting each person's standing in the community.","In Fiji, yaqona is central to village welcomes, while in Samoa the 'ava ceremony marks formal occasions, with the high chief's cup served first. Protocols differ between Tonga, Fiji and Samoa; the kava circle is not a single regional institution."]},{"heading":"Talk and music late into the night","paragraphs":["Sessions often run late into the night with guitar music and conversation. In Tonga, the kava circle is a social institution where news and politics are discussed, and stories are shared. The style varies by region and generation—some younger people add modern touches while elders hold to tradition."]}]},"context":{"countries":["TO","FJ","WS"],"region":"Polynesia and Fiji","continent":"oceania","languages":["to","fj","sm","en"],"period":"contemporary"},"tags":["food-and-hospitality","Polynesia and Fiji"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kava","de":"Kava","en":"Kava"},"url":"https://en.wikipedia.org/wiki/Kava","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Tonga","de":"Culture of Tonga","en":"Culture of Tonga"},"url":"https://en.wikipedia.org/wiki/Culture_of_Tonga","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في قاعة village تونغية، يجلس الرجال في دائرة حول التانوءا، يصفقون مرة واحدة قبل الشرب، ويمررون الكأس حسب الرتبة بينما يعزف الجيتار في الزاوية.","de":"In einer tongaischen Dorfhalle sitzen Männer im Kreis um die Tano'a, klatschen einmal vor dem Trinken und reichen die Tasse in Rangordnung weiter, während in der Ecke eine Gitarre spielt.","en":"In a Tongan village hall, men sit in a circle around the tano'a, clap once before drinking, and pass the cup in rank order while a guitar plays in the corner."},"misunderstanding":{"ar":"يعتقد البعض أن الكافا مجرد مشروب مخدر، لكنها في الواقع مشروب اجتماعي قانوني في جميع أنحاء المحيط الهادئ، وله فوائد اقتصادية كمنتج تصديري.","de":"Manche halten Kava für ein Rauschmittel, doch es ist ein legales Gesellschaftsgetränk im gesamten Pazifik und eine Exportpflanze mit wirtschaftlicher Bedeutung.","en":"Some assume kava is an intoxicant, but it is a legal social drink across the Pacific and an export crop with economic value."},"comparison":{"ar":"بينما تشترك تونغا وفيجي وساموا في استخدام الكافا، تختلف الطقوس: ففي تونغا تُعقد الدوائر بانتظام، وفي فيجي ترتبط بالترحيب، وفي ساموا تقتصر على المناسبات الرسمية.","de":"Obwohl Tonga, Fidschi und Samoa Kava nutzen, unterscheiden sich die Rituale: In Tonga sind die Kreise regelmäßig, in Fidschi mit Empfängen verbunden, in Samoa auf formelle Anlässe beschränkt.","en":"While Tonga, Fiji and Samoa all use kava, the rituals differ: in Tonga circles are regular, in Fiji they accompany welcomes, and in Samoa they are reserved for formal occasions."}},{"id":"tra-070","version":2,"slug":"land-diving-a-leap-that-brings-the-yams","contentType":"note","category":"beliefs-and-folklore","title":{"ar":"القفز من البرج: طقس يجلب اليام","de":"Landtauchen: Ein Sprung, der Yamswurzeln bringt","en":"Land Diving: A Leap That Brings the Yams"},"deck":{"ar":"في جزيرة بنتيكوست، يربط الرجال كروم اللبلاب بأقدامهم ويقفزون من أبراج خشبية بعد حصاد اليام.","de":"Auf Pentecost Island binden sich Männer Lianen um die Knöchel und springen nach der Yamsernte von Holztürmen.","en":"On Pentecost Island, men tie liana vines to their ankles and jump from wooden towers after the yam harvest."},"teaser":{"ar":"طقس ناغول في فانواتو: قفزة من أبراج يبلغ ارتفاعها عشرين متراً، يربط فيها الرجال كروم اللبلاب بأقدامهم لتمس شعرهم الأرض.","de":"Das Naghol-Ritual in Vanuatu: Ein Sprung von Türmen, die zwanzig bis dreißig Meter hoch sind, mit Lianen an den Knöcheln, damit das Haar den Boden berührt.","en":"The naghol ritual in Vanuatu: a jump from towers twenty to thirty metres high, with vines tied to ankles so hair touches the ground."},"readingMinutes":1,"sections":{"ar":[{"heading":"الأسطورة والحصاد","paragraphs":["طقس القفز من البرج، المعروف باسم ناغول، يُقام في جزيرة بنتيكوست بفانواتو بين أبريل ويونيو بعد حصاد اليام. ويرتبط بأسطورة امرأة هربت من زوجها بتسلق شجرة والقفز، فأمسكت بها الكروم. كما أنه شكر على الحصاد وطقس عبور للذكور.","يستعد القرويون لهذا الحدث بعناية، فيبنون البرج من الأشجار والكروم دون مواد حديثة، ويلتزمون بفترات تحضير ومحظورات قبل القفز."]},{"heading":"بين التقليد والسياحة","paragraphs":["يقفز الرجال والفتيان من أبراج خشبية يبلغ ارتفاعها نحو عشرين إلى ثلاثين متراً، وهم يهدفون إلى الاقتراب من الأرض بما يكفي لتمس شعرهم التراب. وقد ألهم هذا الطقس رياضة البانجي التجارية، وأصبح الآن عامل جذب سياحي رئيسي، مع العلم أن بعض القرى فقط تؤدي العروض للزوار. ويختلف تنظيم الطقس وأجواؤه بين الأجيال والقرى، إذ يشارك الشباب بحماس بينما يتمسك الكبار بالقواعد المحلية."]}],"de":[{"heading":"Legende und Ernte","paragraphs":["Das Landtauchen, bekannt als Naghol, wird auf Pentecost Island in Vanuatu zwischen April und Juni nach der Yamsernte praktiziert. Es ist mit der Legende einer Frau verbunden, die ihrem Mann entkam, indem sie auf einen Baum kletterte und sprang, wobei die Lianen sie auffingen. Es dient auch als Erntedankfest und männliches Übergangsritual.","Die Dorfbewohner bereiten sich sorgfältig vor, bauen den Turm aus Bäumen und Lianen ohne moderne Materialien und beachten Vorbereitungs- und Tabuphasen vor dem Sprung."]},{"heading":"Zwischen Tradition und Tourismus","paragraphs":["Männer und Jungen springen von Holztürmen, die etwa zwanzig bis dreißig Meter hoch sind, und zielen darauf ab, nahe genug am Boden zu landen, dass ihr Haar die Erde berührt. Das Ritual inspirierte das kommerzielle Bungee-Jumping und ist heute eine wichtige Touristenattraktion, wobei nur einige Dörfer für Besucher auftreten. Die Durchführung und Atmosphäre des Rituals variieren zwischen Generationen und Dörfern, da junge Leute begeistert mitmachen, während Ältere an lokalen Regeln festhalten."]}],"en":[{"heading":"Legend and Harvest","paragraphs":["Land diving, known as naghol, is performed on Pentecost Island, Vanuatu, between April and June after the yam harvest. It is tied to the legend of a woman who escaped her husband by climbing a tree and jumping, and the vines caught her. It also serves as a harvest thanksgiving and a male rite of passage.","Villagers prepare carefully, building the tower from trees and vines without modern materials and observing preparation and taboo periods before jumping."]},{"heading":"Tradition and Tourism","paragraphs":["Men and boys jump from wooden towers roughly twenty to thirty metres high, aiming to land close enough for their hair to touch the ground. The ritual inspired commercial bungee jumping and is now a major tourist draw, with only some villages performing for visitors. The ritual's staging and atmosphere vary by generation and village, as younger people join eagerly while elders uphold local rules."]}]},"context":{"countries":["VU"],"region":"Pentecost Island","community":"southern Pentecost villages","continent":"oceania","languages":["bi","en"],"period":"contemporary"},"tags":["beliefs-and-folklore","Pentecost Island"],"sources":[{"organization":"Wikipedia","title":{"ar":"Land diving","de":"Land diving","en":"Land diving"},"url":"https://en.wikipedia.org/wiki/Land_diving","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Vanuatu","de":"Culture of Vanuatu","en":"Culture of Vanuatu"},"url":"https://en.wikipedia.org/wiki/Culture_of_Vanuatu","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"على منحدر أُعدّ لبناء البرج، يصعد شاب إلى المنصة، ويسلّم على الحضور، ثم يقفز بينما تشد الكروم وتلامس كتفاه الأرض.","de":"An einem für den Turm gerodeten Hang klettert ein junger Mann auf die Plattform, grüßt die Menge und springt, während die Lianen straff werden und seine Schultern die Erde streifen.","en":"On a hillside cleared for the tower, a young man climbs the platform, greets the crowd, and jumps as the vines snap taut and his shoulders brush the earth."},"misunderstanding":{"ar":"يعتقد البعض أن القفز مجرد استعراض خطير، لكنه في جوهره طقس روحي واجتماعي مرتبط بالحصاد والعبور.","de":"Manche halten den Sprung für eine bloße gefährliche Show, doch im Kern ist er ein spirituelles und soziales Ritual, das mit Ernte und Übergang verbunden ist.","en":"Some think the jump is just a dangerous stunt, but it is essentially a spiritual and social ritual linked to harvest and passage."},"comparison":{"ar":"يشبه هذا الطقس طقوس العبور الأخرى في المحيط الهادئ، لكنه يتميز بارتفاع البرج واستخدام الكروم الطبيعية.","de":"Das Ritual ähnelt anderen Übergangsritualen im Pazifik, zeichnet sich aber durch die Höhe des Turms und die Verwendung natürlicher Lianen aus.","en":"The ritual resembles other Pacific rites of passage but stands out for the tower's height and the use of natural vines."}},{"id":"wrk-001","version":2,"slug":"when-german-workers-sit-on-the-board","contentType":"note","category":"work-and-education","title":{"ar":"حين يجلس العمال الألمان على مجلس الإدارة","de":"Wenn deutsche Beschäftigte im Aufsichtsrat sitzen","en":"When German workers sit on the board"},"deck":{"ar":"في حوض الرور، يمنح قانون المشاركة العمال صوتاً في قرارات الشركات الكبرى، لكن هذا الحق يتوقف عند حدود حجم المؤسسة.","de":"Im Ruhrgebiet gibt das Mitbestimmungsrecht den Beschäftigten großer Konzerne eine Stimme – doch diese Rechte enden an der Größe des Betriebs.","en":"In the Ruhr, co-determination gives employees of big firms a voice in company decisions, but those rights stop at the size of the workplace."},"teaser":{"ar":"منذ 1976 ينتخب موظفو الشركات الكبيرة نصف مقاعد مجلس الرقابة، لكن كثيراً من الشركات الصغيرة لا تعرف هذا النظام إطلاقاً.","de":"Seit 1976 wählen Beschäftigte großer Firmen die Hälfte der Aufsichtsratssitze, während viele kleine Betriebe diese Struktur gar nicht kennen.","en":"Since 1976, staff at large German companies elect half the supervisory board seats, yet many small firms and service workplaces have no such body at all."},"readingMinutes":1,"sections":{"ar":[{"heading":"نصف المقاعد وورقة ترجيح","paragraphs":["بموجب قانون المشاركة لعام 1976، ينتخب العاملون في الشركات التي يتجاوز عدد موظفيها ألفين نصف مقاعد مجلس الرقابة، بينما يختار المساهمون الرئيس الذي يملك صوتاً مرجحاً عند التعادل.","أما مجالس العمل فتُنتخب منفصلة عن النقابات وفق قانون 1972، ويجب استشارتها في التسريحات والعمل الإضافي والنقل والتغييرات الكبرى، لكنها لا تستطيع الدعوة إلى الإضراب.","في قطاع الفحم والحديد والصلب تسري قواعد مونتانية أقوى منذ 1951، إذ يحصل العمال على مدير وعلى شبه تكافؤ داخل المجلس."]},{"heading":"ثقة ومفاوضة وأبطأ قرار","paragraphs":["ينسب المؤيدون إلى هذا النظام انخفاض معدل الإضرابات في ألمانيا، وإعادة الهيكلة عبر التفاوض لا عبر الصدام.","ويرى النقاد أن مجالس العمل قد تبطئ القرارات، وأنها تتعاون أحياناً مع الإدارة أكثر مما ينبغي.","يتفاوت التطبيق بين منطقة وأخرى وبين جيل وآخر: فبعض العاملين الشباب في الخدمات لا يعرفون بوجود مجلس عمل في مكانهم أصلاً."]}],"de":[{"heading":"Halbe Sitze und eine zweite Stimme","paragraphs":["Nach dem Mitbestimmungsgesetz von 1976 wählen Beschäftigte in Unternehmen mit mehr als 2000 Mitarbeitenden die Hälfte der Aufsichtsratssitze; den Vorsitzenden bestimmen die Anteilseigner, und bei Stimmengleichheit gibt seine Stimme den Ausschlag.","Betriebsräte werden nach dem Betriebsverfassungsgesetz von 1972 getrennt von den Gewerkschaften gewählt und müssen bei Kündigungen, Überstunden, Versetzungen und größeren Veränderungen angehört werden – streiken dürfen sie nicht.","In Kohle, Eisen und Stahl gelten seit 1951 die stärkeren Montanregeln mit einem Arbeitsdirektor und nahezu paritätischer Besetzung."]},{"heading":"Vertrauen, Verhandlung, langsamere Wege","paragraphs":["Befürworter verbinden das System mit Deutschlands niedriger Streikrate und mit ausgehandelten Umstrukturierungen statt offener Konflikte.","Kritiker sagen, Betriebsräte könnten Entscheidungen verlangsamen und manchmal zu eng mit dem Management zusammenarbeiten.","Regional und generationell unterscheidet sich die Praxis deutlich: Manche jüngeren Beschäftigten im Dienstleistungsbereich wissen nicht einmal, dass es bei ihnen einen Betriebsrat gibt."]}],"en":[{"heading":"Half the seats and a casting vote","paragraphs":["Under the 1976 Co-determination Act, employees of companies with more than 2,000 staff elect half of the supervisory board seats; the chair, chosen by shareholders, holds a casting vote.","Works councils are elected separately from trade unions under the 1972 Works Constitution Act and must be consulted on dismissals, overtime, transfers and major workplace changes, but they cannot call strikes.","Coal, iron and steel firms operate under the stronger 1951 Montan rules, which give labour a director and near-parity on the board."]},{"heading":"Trust, negotiation, slower decisions","paragraphs":["Supporters credit the system with Germany's relatively low strike rate and with negotiated restructuring rather than open conflict.","Critics say works councils can slow decisions and sometimes cooperate too closely with management.","Practice varies by region and generation: some younger service workers do not even know whether their workplace has a works council."]}]},"context":{"countries":["DE"],"region":"Ruhr","continent":"europe","languages":["de"],"period":"contemporary"},"tags":["work-and-education","Ruhr"],"sources":[{"organization":"Wikipedia","title":{"ar":"Worker representation on corporate boards of directors","de":"Worker representation on corporate boards of directors","en":"Worker representation on corporate boards of directors"},"url":"https://en.wikipedia.org/wiki/Worker_representation_on_corporate_boards_of_directors","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Works council","de":"Works council","en":"Works council"},"url":"https://en.wikipedia.org/wiki/Works_council","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تريد شركة لتصنيع الأدوات الآلية في بوخوم إلغاء وردية ليلية. قبل إرسال أي إشعار، يجب على الإدارة عرض الخطة على مجلس العمل المنتخب، الذي يضم مشغلي آلات، والتفاوض على خطة اجتماعية تشمل تعويضات وإعادة تدريب.","de":"Ein Werkzeugmaschinenbetrieb in Bochum will eine Nachtschicht streichen. Bevor Kündigungen verschickt werden, muss die Geschäftsführung den Plan dem gewählten Betriebsrat vorlegen, in dem auch Maschinenbediener sitzen, und einen Sozialplan mit Abfindungen und Umschulung aushandeln.","en":"A machine-tool firm in Bochum wants to cut a night shift. Before any notices go out, managers must bring the plan to the elected works council, whose members include machine operators, and negotiate a social plan with severance and retraining."},"misunderstanding":{"ar":"يظن كثيرون أن مجالس العمل نقابات أو أنها تملك حق الإضراب، لكنها هيئة منتخبة داخل المنشأة تُستشار ولا تُشهر الإضراب.","de":"Viele halten Betriebsräte für Gewerkschaften oder für streikberechtigt, doch sie sind ein gewähltes Gremium im Betrieb, das angehört wird, aber nicht streiken darf.","en":"Many assume works councils are trade unions or can call strikes, but they are an elected body inside the workplace that must be consulted and cannot strike."},"comparison":{"ar":"في بريطانيا وفرنسا يترك التنظيم العمالي غالباً للنقابات خارج الشركة، بينما يبني النموذج الألماني قنوات داخلية إلى جانب النقابة.","de":"In Großbritannien und Frankreich organisieren oft Gewerkschaften von außen die Interessenvertretung, während das deutsche Modell innerbetriebliche Kanäle neben der Gewerkschaft aufbaut.","en":"In Britain and France, unions outside the firm often carry worker representation, while the German model builds internal channels alongside the union."}},{"id":"wrk-002","version":2,"slug":"the-dual-apprenticeship-that-trains-germany-s-trades","contentType":"note","category":"work-and-education","title":{"ar":"التدريب المزدوج في الحرف الألمانية","de":"Die duale Ausbildung in Deutschlands Handwerk","en":"The dual apprenticeship training Germany's trades"},"deck":{"ar":"نظام يجمع بين العمل في الشركة والدراسة في المدرسة المهنية لتأهيل الشباب.","de":"Ein System, das Betrieb und Berufsschule verbindet, um junge Menschen auf das Berufsleben vorzubereiten.","en":"A system combining company work and vocational school to prepare young people for skilled careers."},"teaser":{"ar":"في بادن-فورتمبيرغ، يقضي المتدربون ثلاثة أو أربعة أيام في الشركة ويومًا أو يومين في المدرسة المهنية لمدة تصل إلى ثلاث سنوات ونصف.","de":"In Baden-Württemberg verbringen Auszubildende drei oder vier Tage pro Woche im Betrieb und ein bis zwei Tage in der Berufsschule – bis zu dreieinhalb Jahre lang.","en":"In Baden-Württemberg, apprentices spend three or four days a week in a company and one or two days at a state vocational school for up to three and a half years."},"readingMinutes":1,"sections":{"ar":[{"heading":"كيف يعمل التدريب المزدوج","paragraphs":["في نظام التدريب المزدوج (duale Ausbildung)، يقضي المتدربون ثلاثة أو أربعة أيام أسبوعيًا في شركة ويومًا أو يومين في مدرسة مهنية حكومية (Berufsschule) لمدة تتراوح بين سنتين وثلاث سنوات ونصف. يوجد حوالي 320 مهنة تدريبية معترف بها، من ميكانيكي صناعي إلى موظف بنك، وتنظم عقود التدريب بموجب قانون التدريب المهني لعام 1969.","تسجل غرف التجارة والحرف (IHK وHandwerkskammer) العقود، وتضع معايير الامتحانات، وتصدر الشهادات النهائية. يتلقى المتدربون بدلًا تدريبيًا يرتفع كل عام، وكثير منهم يبقون في الشركة بعد ذلك؛ مؤهل Meister (الحرفي الماهر) مطلوب لتدريب المتدربين في العديد من الحرف."]},{"heading":"التحديات والتفاوت الإقليمي","paragraphs":["كان حوالي نصف المتروكين للمدرسة يدخلون النظام المزدوج سابقًا، لكن النسبة انخفضت مع اختيار المزيد من الشباب للجامعة، والتلاميذ ذوو التحصيل المنخفض والمهاجرون ممثلون بشكل مفرط بين المتسربين. يختلف سوق التدريب الإقليمي بشكل حاد: في المدن الكبرى المنافسة على أفضل الأماكن شديدة، بينما لا تستطيع بعض الشركات الريفية ملء أماكنها."]}],"de":[{"heading":"So funktioniert die duale Ausbildung","paragraphs":["Im dualen System (duale Ausbildung) sind Auszubildende drei oder vier Tage pro Woche in einem Unternehmen und ein bis zwei Tage in einer staatlichen Berufsschule – zwei bis dreieinhalb Jahre lang. Rund 320 anerkannte Ausbildungsberufe gibt es, vom Industriemechaniker bis zum Bankkaufmann, und die Ausbildungsverträge sind durch das Berufsbildungsgesetz von 1969 geregelt.","Die Industrie- und Handelskammern (IHK) und Handwerkskammern registrieren die Verträge, legen Prüfungsstandards fest und stellen die Abschlusszeugnisse aus. Auszubildende erhalten eine Vergütung, die jährlich steigt, und viele bleiben danach im Betrieb; der Meister ist in vielen Handwerken Voraussetzung, um auszubilden."]},{"heading":"Herausforderungen und regionale Unterschiede","paragraphs":["Früher begann etwa die Hälfte der Schulabgänger eine duale Ausbildung, doch der Anteil ist gesunken, da mehr junge Menschen studieren; lernschwächere Schüler und Migranten sind unter den Abbrechern überrepräsentiert. Die regionalen Ausbildungsmärkte unterscheiden sich stark: In Großstädten ist der Wettbewerb um die besten Plätze hart, während manche ländlichen Betriebe ihre Stellen nicht besetzen können."]}],"en":[{"heading":"How the dual system works","paragraphs":["In the dual system (duale Ausbildung), apprentices spend three or four days a week in a company and one or two days at a state vocational school (Berufsschule) for two to three and a half years. Around 320 recognised training occupations exist, from industrial mechanic to bank clerk, and training contracts are regulated by the 1969 Vocational Training Act.","Chambers of commerce and crafts (IHK and Handwerkskammer) register the contracts, set examination standards and issue the final certificates. Apprentices receive a training allowance that rises each year, and many stay on in the company afterwards; the Meister (master craftsperson) qualification is required to train apprentices in many trades."]},{"heading":"Challenges and regional variation","paragraphs":["Around half of school-leavers once entered the dual system, but the share has fallen as more young people choose university, and low-achieving pupils and migrants are over-represented among those who drop out. Regional training markets differ sharply: in big cities competition for the best places is fierce, while some rural firms cannot fill theirs."]}]},"context":{"countries":["DE"],"region":"Baden-Württemberg","continent":"europe","languages":["de"],"period":"contemporary"},"tags":["work-and-education","Baden-Württemberg"],"sources":[{"organization":"Wikipedia","title":{"ar":"Apprenticeship","de":"Apprenticeship","en":"Apprenticeship"},"url":"https://en.wikipedia.org/wiki/Apprenticeship","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Education in Germany","de":"Education in Germany","en":"Education in Germany"},"url":"https://en.wikipedia.org/wiki/Education_in_Germany","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"شاب يبلغ من العمر 16 عامًا من مدرسة Realschule يقضي ثلاثة أيام في الأسبوع لدى مورد لقطع غيار السيارات ويومًا في المدرسة المهنية، ويسجل المهام في سجل تدريب تفحصه الغرفة قبل الامتحان النهائي.","de":"Ein 16-Jähriger von der Realschule verbringt drei Tage pro Woche bei einem Autozulieferer und einen Tag in der Berufsschule; er dokumentiert seine Aufgaben in einem Ausbildungsnachweis, den die Kammer vor der Abschlussprüfung prüft.","en":"A 16-year-old from a Realschule spends three days a week at a car-parts supplier and one day at vocational school, recording tasks in a training logbook that the chamber inspects before the final exam."},"misunderstanding":{"ar":"يعتقد البعض أن التدريب المزدوج أقل قيمة من التعليم الجامعي، لكنه يوفر مهارات عملية وشهادة معترف بها تؤدي إلى وظائف مستقرة.","de":"Manche halten die duale Ausbildung für weniger wert als ein Studium, doch sie vermittelt praktische Fähigkeiten und einen anerkannten Abschluss, der zu stabilen Jobs führt.","en":"Some believe the dual apprenticeship is less valuable than a university degree, but it provides practical skills and a recognised qualification that leads to stable jobs."},"comparison":{"ar":"على عكس الأنظمة التي تعتمد على التدريب المهني فقط في المدارس، يجمع النموذج الألماني بين التعلم النظري والممارسة العملية في الشركات.","de":"Anders als Systeme, die nur schulische Berufsausbildung kennen, kombiniert das deutsche Modell theoretisches Lernen mit praktischer Arbeit im Betrieb.","en":"Unlike systems that rely solely on school-based vocational training, the German model combines theoretical learning with hands-on work in companies."}},{"id":"wrk-003","version":2,"slug":"ossi-wessi-and-the-identity-that-survived-the-wall","contentType":"note","category":"cultural-change","title":{"ar":"أوسي وفيسي: هوية تجاوزت الجدار","de":"Ossi, Wessi und die Identität nach der Mauer","en":"Ossi, Wessi and the identity that survived the Wall"},"deck":{"ar":"بعد عام 1990، أصبحت كلمتا أوسي وفيسي جزءًا من الحياة اليومية في ألمانيا، تعكسان انقسامًا لم يمحه الزمن.","de":"Seit 1990 sind Ossi und Wessi Alltagsbegriffe – und verraten viel über Identität, Wirtschaft und Humor in Deutschland.","en":"Since 1990, Ossi and Wessi have been everyday labels in Germany – revealing much about identity, economy and humour."},"teaser":{"ar":"كيف تعيش تسميات الشرق والغرب بين الألمان اليوم، وما الذي تكشفه عن الهوية والاقتصاد والفكاهة؟","de":"Wie leben die alten Etiketten Ost und West heute weiter, und was sagen sie über Zugehörigkeit, Geld und regionale Unterschiede?","en":"How do the old East-West labels live on today, and what do they say about belonging, money and regional differences?"},"readingMinutes":1,"sections":{"ar":[{"heading":"تسميات من زمن التحول","paragraphs":["بعد انضمام الولايات الخمس الجديدة إلى الجمهورية الفيدرالية عام 1990، أصبح «أوسي» (الشرقي) و«فيسي» (الغربي) كلمتين دارجتين. لم تكونا مجرد وصف جغرافي، بل حملتا دلالات عن الانتماء والخبرة اليومية.","تصف «أوستالغي» الحنين إلى الحياة اليومية في ألمانيا الشرقية، من فيتا كولا وساندمينشن إلى سيارات ترابانت، وتحولت إلى نوع إعلامي مع أفلام مثل «وداعًا لينين!» (2003)."]},{"heading":"فروق لا تزال قائمة","paragraphs":["لم يكتمل التقارب الاقتصادي: فالأجور في الشرق أدنى، ومقار الشركات الكبرى أقل، وفقد الشرق سكانًا عبر الهجرة، خاصة الشابات. تختلف ساكسونيا وبراندنبورغ وتورينغن وبرلين في الاقتصاد واللهجة والسياسة، والحدود القديمة تمر عبر العائلات لا الخرائط فقط. يختلف استخدام التسميات بين الأجيال والمناطق، فالشباب غالبًا يستخدمونها في الدعابة فقط."]}],"de":[{"heading":"Etiketten aus der Wendezeit","paragraphs":["Als 1990 die fünf neuen Länder der Bundesrepublik beitraten, wurden Ossi und Wessi zu geläufigen Bezeichnungen. Sie meinten nicht nur Herkunft, sondern auch Alltagserfahrung und Zugehörigkeit.","Ostalgie beschreibt die Nostalgie für den DDR-Alltag – von Vita Cola und Sandmännchen bis zum Trabant. Als Medien Genre wurde sie mit Filmen wie Good Bye, Lenin! (2003) bekannt."]},{"heading":"Ungleiche Annäherung","paragraphs":["Die wirtschaftliche Angleichung stockte: Die Löhne im Osten sind niedriger, große Konzernzentralen seltener, und Abwanderung – vor allem junger Frauen – hat den Osten geprägt. Sachsen, Brandenburg, Thüringen und Berlin unterscheiden sich in Wirtschaft, Dialekt und Politik; die alte Grenze verläuft auch durch Familien. Je nach Region und Generation werden die Begriffe unterschiedlich verwendet – oft nur als Scherz."]}],"en":[{"heading":"Labels from the turning point","paragraphs":["When the five new Länder joined the Federal Republic in 1990, Ossi (easterner) and Wessi (westerner) became everyday labels. They marked not just geography but everyday experience and belonging.","Ostalgie describes nostalgia for East German everyday life, from Vita Cola and Sandmännchen to Trabant cars; it became a media genre with films such as Good Bye, Lenin! (2003)."]},{"heading":"An uneven convergence","paragraphs":["Economic convergence stalled: eastern wages remain lower, large company headquarters are fewer, and out-migration, especially of young women, has shaped the east. Saxony, Brandenburg, Thuringia and Berlin differ in economy, dialect and politics, and the old border runs through families as well as maps. Use of the labels varies by region and generation – younger Germans often deploy them as jokes."]}]},"context":{"countries":["DE"],"region":"Saxony","continent":"europe","languages":["de"],"period":"contemporary"},"tags":["cultural-change","Saxony"],"sources":[{"organization":"Wikipedia","title":{"ar":"Ostalgie","de":"Ostalgie","en":"Ostalgie"},"url":"https://en.wikipedia.org/wiki/Ostalgie","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"New states of Germany","de":"New states of Germany","en":"New states of Germany"},"url":"https://en.wikipedia.org/wiki/New_states_of_Germany","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مكتب بلايبزيغ، يُلقب زميل جديد من شتوتغارت بـ«بيسرفيسي» بعد أن أعاد كتابة عرض تقديمي، فيرد بسؤال: هل ما زلتم تلتقون في شتوبي بعد العمل؟","de":"In einem Leipziger Büro wird ein neuer Kollege aus Stuttgart nach dem Umschreiben einer Präsentation als Besserwessi aufgezogen; er kontert mit der Frage, ob man sich nach der Arbeit noch am Späti trifft.","en":"In a Leipzig office, a new colleague from Stuttgart is teased as a Besserwessi after rewriting a presentation, and she answers by asking whether everyone still meets at the Späti after work."},"misunderstanding":{"ar":"يظن البعض أن التسميات تصف الشرق والغرب بدقة، لكنها اختزال خشن يخفي فروقًا كبيرة بين المناطق والأجيال، وكثيرون يرفضونها تمامًا.","de":"Viele halten die Begriffe für genaue Beschreibungen von Ost und West, doch sie sind eine grobe Abkürzung, die große Unterschiede zwischen Regionen und Generationen verdeckt; manche lehnen sie ganz ab.","en":"Some assume the labels precisely describe east and west, but they are a rough shorthand that hides big differences between regions and generations; many reject them entirely."},"comparison":{"ar":"بينما يستخدمها البعض في النكات، يراها آخرون إهانة، مثل «يامر-أوسي» (الشرقي المتذمر) و«بيسرفيسي» (الغربي العارف بكل شيء).","de":"Während die einen sie in Witzen nutzen, empfinden andere sie als Beleidigung – etwa Jammer-Ossi oder Besserwessi.","en":"While some use them in jokes, others hear them as insults – such as Jammer-Ossi (whingeing easterner) or Besserwessi (know-it-all westerner)."}},{"id":"wrk-004","version":2,"slug":"rostigraben-switzerland-s-language-border","contentType":"note","category":"communication","title":{"ar":"روستيجرابن: حدود اللغة في سويسرا","de":"Röstigraben: Sprachgrenze in der Schweiz","en":"Röstigraben: Switzerland's Language Border"},"deck":{"ar":"كيف يرسم طبق بطاطس خطاً ثقافياً بين السويسريين الناطقين بالألمانية والفرنسية.","de":"Wie ein Kartoffelgericht eine kulturelle Trennlinie zwischen Deutschschweizern und Romands markiert.","en":"How a potato dish marks a cultural dividing line between German- and French-speaking Swiss."},"teaser":{"ar":"في سويسرا، لا تفصل الجبال بين اللغات فحسب، بل تفصل أيضاً عقلية التصويت وأنماط الحياة اليومية على طول خط غير مرئي.","de":"In der Schweiz trennen nicht nur Berge die Sprachen, sondern auch unterschiedliche Abstimmungsmentalitäten und Alltagsgewohnheiten entlang einer unsichtbaren Linie.","en":"In Switzerland, mountains aren't the only dividers—voting mentalities and daily habits shift along an invisible line between language communities."},"readingMinutes":1,"sections":{"ar":[{"heading":"حدود ثقافية على طبق بطاطس","paragraphs":["روستيجرابن، أو «خندق الروستي»، هو الاسم غير الرسمي للحدود الثقافية والسياسية بين سويسرا الناطقة بالألمانية والفرنسية، نسبةً إلى طبق البطاطس المرتبط بالأسر الناطقة بالألمانية.","انتشر المصطلح خلال الحرب العالمية الأولى، عندما تعاطف ضباط ناطقون بالألمانية مع ألمانيا، بينما دعم الناطقون بالفرنسية فرنسا، مما عمّق الانقسام اللغوي.","يظهر هذا الانقسام في الاستفتاءات: فقد صوّتت كانتونات ناطقة بالفرنسية بشكل مختلف حول قضايا مثل الانضمام إلى الأمم المتحدة (قُبل عام 2002) وتشديد قوانين اللجوء والهجرة."]},{"heading":"لغة يومية وحدود متحركة","paragraphs":["سويسرا لديها أربع لغات وطنية — الألمانية والفرنسية والإيطالية والرومانشية — والناطقون بالألمانية يستخدمون اللهجة (Schweizerdeutsch) في حياتهم اليومية، ويحتفظون بالألمانية الفصحى للكتابة بشكل أساسي.","يمر هذا الحد عبر كانتونات ثنائية اللغة مثل برن وفاليه وفرايبورغ، حيث تتغير أسماء الأماكن ولغات المدارس والسياسة المحلية من قرية إلى أخرى.","يختلف هذا الانقسام بين الأجيال والمناطق: فالمدن الكبرى تشهد تداخلاً أكبر، بينما تبقى الفروق أوضح في المناطق الريفية."]}],"de":[{"heading":"Eine Kulturgrenze auf dem Teller","paragraphs":["Der Röstigraben ist der informelle Name für die kulturelle und politische Grenze zwischen der deutsch- und der französischsprachigen Schweiz, benannt nach dem Kartoffelgericht, das mit deutschsprachigen Haushalten assoziiert wird.","Der Begriff verbreitete sich während des Ersten Weltkriegs, als die Sympathie deutschsprachiger Offiziere für Deutschland mit der Unterstützung der Französischsprachigen für Frankreich kollidierte und die Sprachgrenze schärfte.","Die Spaltung zeigt sich in Abstimmungen: Französischsprachige Kantone stimmten bei Themen wie dem UNO-Beitritt (2002 angenommen) und der Verschärfung des Asyl- und Einwanderungsrechts anders."]},{"heading":"Alltagssprache und bewegliche Grenzen","paragraphs":["Die Schweiz hat vier Nationalsprachen — Deutsch, Französisch, Italienisch und Rätoromanisch — und Deutschschweizer verwenden im Alltag Dialekt (Schweizerdeutsch), Standarddeutsch bleibt weitgehend dem Schreiben vorbehalten.","Die Grenze verläuft durch zweisprachige Kantone wie Bern, Wallis und Freiburg, wo sich Ortsnamen, Schulsprachen und Lokalpolitik von Dorf zu Dorf verschieben.","Je nach Region und Generation variiert die Wahrnehmung: In Städten ist die Grenze durchlässiger, auf dem Land bleiben die Unterschiede deutlicher."]}],"en":[{"heading":"A Cultural Border on a Plate","paragraphs":["Röstigraben (\"Rösti ditch\") is the informal name for the cultural and political boundary between German- and French-speaking Switzerland, named after the potato dish associated with German-speaking households.","The term spread during the First World War, when German-speaking officers' sympathy for Germany clashed with French-speaking support for France and sharpened the language divide.","The divide shows up in referendums: French-speaking cantons have voted differently on issues such as joining the United Nations (accepted in 2002) and tightening asylum and immigration law."]},{"heading":"Everyday Language and Shifting Lines","paragraphs":["Switzerland has four national languages—German, French, Italian and Romansh—and German-speaking Swiss use dialect (Schweizerdeutsch) in daily life, reserving standard German largely for writing.","The boundary runs through bilingual cantons such as Bern, Valais and Fribourg, where place names, school languages and local politics shift from village to village.","Perceptions vary by region and generation: cities see more mixing, while rural areas keep differences more visible."]}]},"context":{"countries":["CH"],"region":"Mittelland","continent":"europe","languages":["de","fr"],"period":"contemporary"},"tags":["communication","Mittelland"],"sources":[{"organization":"Wikipedia","title":{"ar":"Röstigraben","de":"Röstigraben","en":"Röstigraben"},"url":"https://en.wikipedia.org/wiki/Röstigraben","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Languages of Switzerland","de":"Languages of Switzerland","en":"Languages of Switzerland"},"url":"https://en.wikipedia.org/wiki/Languages_of_Switzerland","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"على متن القطار من زيوريخ إلى لوزان، يتحول الزملاء من الألمانية السويسرية إلى الفرنسية عند حدود اللغة، ومع اللغة تتغير أيضاً التحيات وأحاديث المجاملة وآداب الاجتماعات.","de":"Im Zug von Zürich nach Lausanne wechseln Kollegen an der Sprachgrenze von Schweizerdeutsch zu Französisch, und mit der Sprache ändern sich auch Begrüßungen, Small Talk und Meeting-Etikette.","en":"On the train from Zürich to Lausanne, colleagues switch from Swiss German to French at the language border, and with the language the greetings, small talk and meeting etiquette change too."},"misunderstanding":{"ar":"الاعتقاد بأن روستيجرابن خط فاصل صارم. في الواقع، الحدود اللغوية تدريجية، والفروق بين المدينة والريف تتقاطع معها، والمهنيون الشباب ثنائيو اللغة يتنقلون بين الجانبين يومياً.","de":"Die Annahme, der Röstigraben sei eine harte Trennlinie. Tatsächlich sind Sprachgrenzen fließend, Stadt-Land-Unterschiede schneiden sie, und junge zweisprachige Berufstätige pendeln täglich zwischen beiden Seiten.","en":"Thinking the Röstigraben is a hard line. In reality, language borders are gradual, city-versus-country differences cut across them, and younger bilingual professionals move between both sides daily."},"comparison":{"ar":"مثل الحدود بين اللهجات في العالم العربي، حيث يتغير كلام الناس وسلوكهم اليومي تدريجياً من منطقة إلى أخرى دون خط واضح.","de":"Ähnlich wie Dialektgrenzen im deutschen Sprachraum, wo sich Alltagssprache und Verhalten von Region zu Region allmählich wandeln, ohne klare Linie.","en":"Like dialect boundaries in other countries, where everyday speech and behavior shift gradually from one region to the next without a clear line."},"expression":{"original":"Röstigraben","language":"Swiss German","gloss":{"ar":"«خندق الروستي» — لقب شعبي للحدود السياسية والثقافية بين سويسرا الناطقة بالألمانية والفرنسية","de":"der «Rösti-Graben» — volkstümlicher Spitzname für die politische und kulturelle Grenze zwischen der deutsch- und französischsprachigen Schweiz","en":"the \"Rösti ditch\" — popular nickname for the political and cultural boundary between German- and French-speaking Switzerland"},"usage":{"ar":"يُستخدم للإشارة إلى الاختلاف في التصويت أو العقلية بين المنطقتين.","de":"Wird verwendet, um unterschiedliches Abstimmungsverhalten oder Mentalitätsunterschiede zwischen den Landesteilen zu bezeichnen.","en":"Used to refer to differences in voting behavior or mentality between the two regions."},"transliteration":"Röstigraben"}},{"id":"wrk-005","version":2,"slug":"polderen-how-the-dutch-build-consensus","contentType":"note","category":"work-and-education","title":{"ar":"البولدرة: كيف يصنع الهولنديون التوافق","de":"Polderen: Wie die Niederländer Konsens schmieden","en":"Polderen: How the Dutch Build Consensus"},"deck":{"ar":"نموذج البولدرة الهولندي: مفاوضات الأجور والعمل بين الحكومة وأرباب العمل والنقابات، مع مثال حي من مستشفى في لاهاي.","de":"Das niederländische Poldermodell: Lohn- und Arbeitsverhandlungen zwischen Regierung, Arbeitgebern und Gewerkschaften, illustriert am Beispiel eines Krankenhauses in Den Haag.","en":"The Dutch polder model: consensus-based wage and labour talks between government, employers and unions, illustrated by a hospital in The Hague."},"teaser":{"ar":"في هولندا، تُحل الخلافات عبر مشاورات طويلة تفضي إلى تسويات، كما يظهر في مفاوضات جداول المناوبات بمستشفى.","de":"In den Niederlanden werden Konflikte durch lange Konsultationen und Kompromisse gelöst, wie bei Schichtplänen in einem Krankenhaus.","en":"In the Netherlands, conflicts are settled through long consultations and compromises, as seen in shift-roster talks at a hospital."},"readingMinutes":1,"sections":{"ar":[{"heading":"جذور التوافق","paragraphs":["نموذج البولدرة هو الممارسة الهولندية للتفاوض الجماعي حول الأجور والعمل بين الحكومة وأرباب العمل والنقابات، وقد تأسس في المجلس الاجتماعي والاقتصادي (SER) عام 1950. يعود هذا التقليد إلى مجالس المياه (waterschappen) التي أدارت مخاطر الفيضان المشتركة لقرون.","في عام 1982، تبادل اتفاق واسينار بين النقابات وأرباب العمل الاعتدال في الأجور وتقصير ساعات العمل مقابل وظائف وتدريب، مما ساهم في انخفاض البطالة بسرعة في العقد التالي. ويختلف تطبيق هذا النموذج بين المناطق والأجيال، إذ يميل الشباب في المدن الكبرى إلى مفاوضات أكثر مرونة."]},{"heading":"ممارسة البولدرة اليوم","paragraphs":["غالبًا ما تؤكد الاجتماعات اتفاقات أُعدت مسبقًا: توزع مسودات الاتفاقات بين الأعضاء، ويصادق الاجتماع الرسمي على تسوية بدل مناقشتها من الصفر. الفعل polderen يعني الآن التفاوض على حل وسط عبر مشاورات مطولة.","في مستشفى، يقضي مجلس العمل والإدارة ومندوبو النقابات أسابيع في محادثات بولدرة حول جداول المناوبات، ثم يقدمون تسوية لا يحبها أي طرف لكن يمكنه الدفاع عنها أمام أعضائه."]}],"de":[{"heading":"Wurzeln des Konsenses","paragraphs":["Das Poldermodell ist die niederländische Praxis konsensbasierter Lohn- und Arbeitsverhandlungen zwischen Regierung, Arbeitgebern und Gewerkschaften, institutionalisiert im 1950 gegründeten Sozialökonomischen Rat (SER). Der Brauch geht auf die jahrhundertealten Wasserräte (waterschappen) zurück, die gemeinsame Hochwasserrisiken verwalteten.","1982 tauschte die Wassenaar-Vereinbarung zwischen Gewerkschaften und Arbeitgebern Lohnmäßigung und kürzere Arbeitszeiten gegen Arbeitsplätze und Ausbildung, was den schnellen Rückgang der Arbeitslosigkeit im folgenden Jahrzehnt förderte. Die Anwendung variiert regional und generationell; jüngere Menschen in Großstädten bevorzugen flexiblere Verhandlungen."]},{"heading":"Polderen in der Praxis","paragraphs":["Besprechungen bestätigen oft im Voraus ausgehandelte Deals: Entwürfe zirkulieren unter den Mitgliedern, und das formelle Treffen ratifiziert einen Kompromiss, anstatt ihn von Grund auf zu debattieren. Das Verb polderen bedeutet heute, durch lange Konsultation einen Kompromiss auszuhandeln.","In einem Krankenhaus verbringen Betriebsrat, Management und Gewerkschaftsdelegierte Wochen in Polder-Gesprächen über Schichtpläne und präsentieren dann einen Kompromiss, den keine Partei liebt, den aber alle vor ihren Mitgliedern vertreten können."]}],"en":[{"heading":"Roots of Consensus","paragraphs":["The polder model is the Dutch practice of consensus-based wage and labour negotiations between government, employers and unions, institutionalised in the tripartite Social and Economic Council (SER), founded in 1950. The habit is linked to the centuries-old water boards (waterschappen) that managed shared flood risk.","In 1982, the Wassenaar Agreement between unions and employers traded wage moderation and shorter hours for jobs and training, and is widely credited with the rapid fall in Dutch unemployment in the following decade. Application varies by region and generation; younger people in big cities often favour more flexible bargaining."]},{"heading":"Polderen in Practice","paragraphs":["Meetings often confirm deals prepared in advance: draft agreements circulate among members, and the formal gathering ratifies a compromise rather than debating it from scratch. The verb polderen now means to negotiate a compromise through long consultation.","At a hospital, the works council, management and union delegates spend weeks in polder talks over shift rosters and then present a compromise that none of the parties loves but all can defend to their members."]}]},"context":{"countries":["NL"],"region":"The Hague","continent":"europe","languages":["nl"],"period":"contemporary"},"tags":["work-and-education","The Hague"],"sources":[{"organization":"Wikipedia","title":{"ar":"Polder model","de":"Polder model","en":"Polder model"},"url":"https://en.wikipedia.org/wiki/Polder_model","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Social and Economic Council","de":"Social and Economic Council","en":"Social and Economic Council"},"url":"https://en.wikipedia.org/wiki/Social_and_Economic_Council","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مستشفى، يقضي مجلس العمل والإدارة ومندوبو النقابات أسابيع في محادثات بولدرة حول جداول المناوبات، ثم يقدمون تسوية لا يحبها أي طرف لكن يمكنه الدفاع عنها أمام أعضائه.","de":"In einem Krankenhaus verbringen Betriebsrat, Management und Gewerkschaftsdelegierte Wochen in Polder-Gesprächen über Schichtpläne und präsentieren dann einen Kompromiss, den keine Partei liebt, den aber alle vor ihren Mitgliedern vertreten können.","en":"At a hospital, the works council, management and union delegates spend weeks in polder talks over shift rosters and then present a compromise that none of the parties loves but all can defend to their members."},"misunderstanding":{"ar":"يُفهم أحيانًا أن البولدرة تعني إجماعًا كاملًا، لكنها في الواقع عملية تفاوض قد تستغرق وقتًا وتستبعد بعض الفئات.","de":"Manchmal wird Polderen als vollständiger Konsens missverstanden, doch es ist ein Verhandlungsprozess, der Zeit braucht und einige Gruppen ausschließt.","en":"Polderen is sometimes mistaken for full consensus, but it is a negotiation process that can take time and leaves some groups out."},"comparison":{"ar":"على عكس النماذج التي تعتمد على التصويت السريع، تعطي البولدرة الأولوية للمشاورات الطويلة قبل اتخاذ القرار.","de":"Anders als Modelle mit schnellen Abstimmungen setzt Polderen auf lange Konsultationen vor der Entscheidung.","en":"Unlike models that rely on quick votes, polderen prioritises long consultation before decisions are made."}},{"id":"wrk-006","version":2,"slug":"belgium-s-pillars-and-the-institutions-people-are-born-into","contentType":"note","category":"cities-and-community","title":{"ar":"أعمدة بلجيكا وحياة الناس بينها","de":"Belgiens Säulen und das Leben der Familien","en":"Belgium's pillars and the families inside them"},"deck":{"ar":"كيف نظّمت الأعمدة الكاثوليكية والاشتراكية والليبرالية حياة الأسر البلجيكية، وكيف تراجعت مع الزمن.","de":"Wie katholische, sozialistische und liberale Säulen den Alltag belgischer Familien ordneten und wie sie verblassten.","en":"How Catholic, socialist and liberal pillars shaped Belgian family life, and how they thinned out over time."},"teaser":{"ar":"من المدرسة إلى الطبيب إلى البنك، كان بإمكان الأسرة البلجيكية أن تعيش حياتها كلها داخل عمود واحد.","de":"Von der Schule über den Arzt bis zur Bank konnte eine belgische Familie ihr ganzes Leben in einer einzigen Säule verbringen.","en":"From school to doctor to bank, a Belgian family could once live its whole life inside a single pillar."},"readingMinutes":1,"sections":{"ar":[{"heading":"حياة كاملة داخل عمود واحد","paragraphs":["نظّم نظام الأعمدة (verzuiling) المجتمع البلجيكي في ثلاثة أعمدة: كاثوليكي واشتراكي وليبرالي، ولكل عمود مدارسه وصحفه ومستشفياته ونقاباته وأنديته الرياضية وحزبه السياسي.","بلغ النظام ذروته في النصف الأول من القرن العشرين، وحُسمت حرب المدارس في الخمسينيات حول التعليم الكاثوليكي مقابل التعليم الرسمي بميثاق المدارس عام 1958.","بالنسبة للأسر، كان ذلك يعني أن المدرسة والطبيب والبنك والصحيفة يمكن اختيارها جميعاً داخل ثقافة فرعية واحدة."]},{"heading":"تراجع الأعمدة وبقاء الانقسام اللغوي","paragraphs":["تراجعت الأعمدة منذ الستينيات، لكن المدارس والجامعات وصناديق المرض والإذاعات بقيت مقسّمة، ولا تزال السياسة الحزبية تسير على الخطوط القديمة.","ثبّت التشريع اللغوي في الستينيات الحدود بين المناطق الناطقة بالهولندية والفرنسية والألمانية، وحوّلت الإصلاحات الفدرالية بين 1970 و1993 بلجيكا إلى دولة فدرالية.","يختلف الأمر اليوم بين الأجيال والمناطق: فالأجيال الشابة أقل ارتباطاً بالأعمدة، بينما يبقى الانقسام اللغوي أكثر سياسية وأشدّ حضوراً، لا سيما في فلاندرز."]},{"heading":"كيف يُقرأ هذا اليوم","paragraphs":["يفهم كثيرون نظام الأعمدة اليوم كإطار تاريخي أكثر منه واقعاً يومياً، إذ يمزج معظم البلجيكيين بين مؤسسات من أعمدة مختلفة."]}],"de":[{"heading":"Ein ganzes Leben in einer Säule","paragraphs":["Die Verzuiling ordnete die belgische Gesellschaft in drei Säulen: eine katholische, eine sozialistische und eine liberale, jede mit eigenen Schulen, Zeitungen, Krankenhäusern, Gewerkschaften, Sportvereinen und einer politischen Partei.","Der Höhepunkt lag in der ersten Hälfte des 20. Jahrhunderts; der Schulstreit der 1950er Jahre um katholische und staatliche Bildung wurde 1958 mit dem Schulpakt beigelegt.","Für Familien bedeutete das, dass Schule, Arzt, Bank und Zeitung alle innerhalb einer Subkultur gewählt werden konnten."]},{"heading":"Dünner werdende Säulen, bleibende Sprachgrenze","paragraphs":["Seit den 1960er Jahren wurden die Säulen dünner, doch Schulen, Universitäten, Krankenkassen und Rundfunkanstalten blieben segmentiert, und die Parteipolitik folgt noch den alten Linien.","Die Sprachgesetzgebung der 1960er Jahre legte die Grenzen zwischen der niederländisch-, französisch- und deutschsprachigen Region fest, und die Föderalreformen von 1970 bis 1993 machten Belgien zum Bundesstaat.","Das variiert heute regional und generationell: Jüngere sind weniger an die Säulen gebunden, während die Sprachgrenze, besonders in Flandern, politischer und wirksamer bleibt."]},{"heading":"Wie das heute gelesen wird","paragraphs":["Viele verstehen die Verzuiling heute eher als historischen Rahmen; die meisten Belgier mischen Institutionen aus verschiedenen Säulen."]}],"en":[{"heading":"A whole life inside one pillar","paragraphs":["Pillarisation (verzuiling) organised Belgian society into Catholic, socialist and liberal pillars, each with its own schools, newspapers, hospitals, unions, sports clubs and political party.","The system peaked in the first half of the 20th century; the 1950s school war over Catholic versus state education was settled by the 1958 School Pact.","For families, the result was that school, doctor, bank and newspaper could all be chosen within one subculture."]},{"heading":"Thinning pillars, lasting language line","paragraphs":["The pillars thinned from the 1960s, but schools, universities, health funds and broadcasters remain segmented, and party politics still follows the old lines.","Language legislation in the 1960s fixed the borders between the Dutch-, French- and German-speaking regions, and the federal reforms of 1970-1993 turned Belgium into a federal state.","This varies by region and generation: younger people are less bound to the pillars, while the language divide, especially in Flanders, remains more political and more present."]},{"heading":"How it reads today","paragraphs":["Many now treat pillarisation as a historical frame; most Belgians mix institutions from different pillars."]}]},"context":{"countries":["BE"],"region":"Flanders","continent":"europe","languages":["nl","fr"],"period":"contemporary"},"tags":["cities-and-community","Flanders"],"sources":[{"organization":"Wikipedia","title":{"ar":"Pillarisation","de":"Pillarisation","en":"Pillarisation"},"url":"https://en.wikipedia.org/wiki/Pillarisation","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Language legislation in Belgium","de":"Language legislation in Belgium","en":"Language legislation in Belgium"},"url":"https://en.wikipedia.org/wiki/Language_legislation_in_Belgium","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17"},{"id":"wrk-007","version":2,"slug":"the-35-hour-week-and-france-s-rtt-days","contentType":"note","category":"work-and-education","title":{"ar":"أسبوع الـ35 ساعة وأيام RTT في فرنسا","de":"Die 35-Stunden-Woche und Frankreichs RTT-Tage","en":"The 35-hour week and France's RTT days"},"deck":{"ar":"قانونان عملا على تقليص ساعات العمل الأسبوعية، فمنحا الموظفين أيام راحة إضافية يخططون لها بعناية.","de":"Zwei Gesetze kürzten die Wochenarbeitszeit und bescheren Angestellten zusätzliche freie Tage, die sie gezielt planen.","en":"Two laws cut the statutory working week and gave employees extra days off that they plan with care."},"teaser":{"ar":"كيف غيّر قانون Aubry إيقاع العمل في فرنسا؟ أيام RTT أصبحت جزءًا من حياة الموظفين، تُحسب وتُستخدم بذكاء.","de":"Wie veränderte das Aubry-Gesetz den Arbeitsrhythmus in Frankreich? RTT-Tage sind für viele Angestellte fester Bestandteil der Lebensplanung.","en":"How did the Aubry laws change the rhythm of work in France? RTT days have become part of employees' lives, counted and spent strategically."},"readingMinutes":1,"sections":{"ar":[{"heading":"قانونان لتقاسم العمل","paragraphs":["في عامي 1998 و2000، خفّض قانونان عُرفا باسم وزيرة العمل مارتين أوبري ساعات العمل القانونية من 39 إلى 35 ساعة أسبوعيًا للشركات التي تتجاوز حجمًا معينًا. قُدّم الإصلاح كوسيلة لتقاسم العمل وخلق فرص عمل، وطُبّق تدريجيًا مع استثناءات ومفاوضات وتعديلات لاحقة.","الموظفون الذين تقل ساعاتهم عن الحد الأقصى يحصلون على أيام راحة إضافية تُعرف باسم RTT، غالبًا ما تُربط بالعطل المدرسية أو تُستخدم لصنع أيام جسر حول الأعياد الرسمية."]},{"heading":"تطبيق متفاوت وخلاف مستمر","paragraphs":["العمل الإضافي ممكن وقد توسّع منذ 2002، لذا تختلف ساعات العمل الفعلية بشكل واسع؛ كثير من المديرين يعملون بنظام أيام سنوية بدلًا من ساعات أسبوعية.","لا يزال الاقتصاديون يجادلون حول أثر القانون: بعضهم ينسب إليه خلق مئات الآلاف من الوظائف، بينما يرى نقاد أنه أضاف جمودًا وأن الساعات الفعلية انخفضت أقل من المتوقع. يختلف التطبيق أيضًا حسب المنطقة والجيل، فبعض الشركات الصغيرة والمطاعم لم تطبقه أبدًا."]}],"de":[{"heading":"Zwei Gesetze zur Arbeitsumverteilung","paragraphs":["1998 und 2000 senkten zwei nach Arbeitsministerin Martine Aubry benannte Gesetze die gesetzliche Wochenarbeitszeit von 39 auf 35 Stunden für Unternehmen ab einer bestimmten Größe. Die Reform sollte Arbeit teilen und Jobs schaffen; sie wurde schrittweise mit Ausnahmen, Verhandlungen und späteren Anpassungen eingeführt.","Beschäftigte, deren Stunden unter dem gesetzlichen Maximum bleiben, erhalten zusätzliche freie Tage, bekannt als RTT. Diese werden oft an Schulferien gekoppelt oder für Brückentage um Feiertage genutzt."]},{"heading":"Ungleiche Umsetzung und anhaltende Debatte","paragraphs":["Überstunden sind möglich und wurden seit 2002 ausgeweitet, sodass die tatsächlichen Arbeitszeiten stark variieren; viele Führungskräfte arbeiten nach Jahrestagen statt Wochenstunden.","Ökonomen streiten weiter über die Wirkung: Einige schreiben dem Gesetz die Schaffung mehrerer hunderttausend Jobs zu, Kritiker sehen mehr Starrheit und einen geringeren Rückgang der tatsächlichen Stunden als beabsichtigt. Die Anwendung variiert auch regional und generationell; viele kleine Firmen und Restaurants wandten es nie an."]}],"en":[{"heading":"Two laws to share work","paragraphs":["In 1998 and 2000, two laws named after labour minister Martine Aubry cut the statutory working week from 39 to 35 hours for companies above a size threshold. The reform was presented as sharing work to create jobs and was phased in, with exemptions, negotiations and later adjustments by successive governments.","Employees whose hours fall below the legal maximum receive extra days off known as RTT, often attached to school holidays or used to make bridge days around public holidays."]},{"heading":"Uneven application and ongoing debate","paragraphs":["Overtime is possible and has been expanded since 2002, so real hours differ widely; many managers are on annualised day counts rather than weekly hours.","Economists still debate the law's effect: some credit it with creating several hundred thousand jobs, while critics argue it added rigidity and that actual hours fell less than intended. Application also varies by region and generation; many small firms and restaurants never applied it."]}]},"context":{"countries":["FR"],"region":"Île-de-France","continent":"europe","languages":["fr"],"period":"contemporary"},"tags":["work-and-education","Île-de-France"],"sources":[{"organization":"Wikipedia","title":{"ar":"35-hour workweek","de":"35-hour workweek","en":"35-hour workweek"},"url":"https://en.wikipedia.org/wiki/35-hour_workweek","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Working time","de":"Working time","en":"Working time"},"url":"https://en.wikipedia.org/wiki/Working_time","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"موظفة في مكتب بباريس تحسب أيام RTT الخاصة بها كل يناير وتنفقها في مايو، مضيفة بضعة أيام إلى عطلة رسمية لصنع أسبوع بعيد دون المساس بإجازتها السنوية.","de":"Eine Pariser Büroangestellte zählt jeden Januar ihre RTT-Tage und nimmt sie im Mai, um mit ein paar Tagen an eine Feiertagsbrücke eine Woche Urlaub zu machen, ohne ihren Jahresurlaub anzutasten.","en":"A Paris office worker counts her RTT days each January and spends them in May, adding a few days to a block of public holidays to make a week away without touching her annual leave."},"misunderstanding":{"ar":"يعتقد البعض أن كل العاملين في فرنسا يعملون 35 ساعة بالضبط، لكن القانون يحدد الحد الأقصى ويسمح بالعمل الإضافي، وكثير من المهن لا يشمله.","de":"Manche glauben, alle Beschäftigten in Frankreich arbeiteten exakt 35 Stunden, doch das Gesetz legt eine Obergrenze fest und erlaubt Überstunden; viele Berufe fallen nicht darunter.","en":"Some believe everyone in France works exactly 35 hours, but the law sets a maximum and allows overtime; many professions are not covered."},"comparison":{"ar":"بالمقارنة مع دول أخرى حيث تُحتسب الإجازة بالأيام فقط، فإن أيام RTT في فرنسا تُضاف إلى الإجازة السنوية وتُمنح مقابل ساعات العمل المخفضة، مما يمنح الموظفين مرونة إضافية.","de":"Anders als in Ländern, in denen Urlaub nur in Tagen gezählt wird, kommen in Frankreich RTT-Tage zum Jahresurlaub hinzu und werden für reduzierte Arbeitszeiten gewährt, was zusätzliche Flexibilität schafft.","en":"Unlike countries where leave is counted only in days, France's RTT days are added to annual leave and granted for reduced hours, giving employees extra flexibility."}},{"id":"wrk-008","version":2,"slug":"classes-preparatoires-and-france-s-elite-school-pipeline","contentType":"note","category":"work-and-education","title":{"ar":"الطريق الفرنسي إلى نخبة الدولة","de":"Frankreichs Weg zu den Eliteschulen","en":"France's Pipeline to Elite Schools"},"deck":{"ar":"بعد البكالوريا، يخوض طلاب فرنسيون عامين من الدراسة المكثفة استعداداً لامتحانات تنافسية تفتح أبواب المدارس الكبرى.","de":"Nach dem Abitur folgen zwei Jahre Pauken und ein Wettbewerb, der über den Zugang zu den Grandes écoles entscheidet.","en":"After the baccalauréat, students spend two intense years preparing for competitive exams that open the grandes écoles."},"teaser":{"ar":"في باريس وضواحيها، يمرّ كثير من نخبة الدولة عبر صفوف تحضيرية شاقة وامتحانات دخول نادرة المقاعد.","de":"In Paris und anderswo führt ein schmaler Pfad über Vorbereitungsklassen und Auswahlprüfungen in die Grandes écoles.","en":"In Paris and beyond, a narrow path of preparatory classes and low-admission exams leads into France's elite schools."},"readingMinutes":1,"sections":{"ar":[{"heading":"عامان بين البكالوريا والامتحان","paragraphs":["يدخل الطالب الفرنسي بعد البكالوريا إلى الصفوف التحضيرية، حيث يقضي عامين من الدروس المكثفة والاختبارات الأسبوعية. بعدها يجلس لامتحانات تنافسية بمعدلات قبول منخفضة جداً.","المدارس الكبرى مؤسسات انتقائية خارج منظومة الجامعات الرئيسية، تدرّب جزءاً كبيراً من نخبة الإدارة والعلوم والأعمال، ومنها المدرسة متعددة التقنيات وسياس بو والمدارس العليا العادية."]},{"heading":"تسلسل ونقد","paragraphs":["للنظام هرمه ومفرداته: الطلاب يُسمّون élèves ويُصنّفون حسب نتائج الامتحان، وأعلى السلك الإداري يختار مباشرة من عدد قليل من المدارس.","ينتقد كثيرون النظام لأنه يعيد إنتاج النخبة، إذ تهيمن عليه أسر المهن العليا، وقد لقي نظام الحصص والصفوف التحضيرية الجديدة للمناطق الأقل حظاً جدلاً واسعاً. ويختلف هذا الواقع بين باريس والأقاليم، ويتباين بين الأجيال."]}],"de":[{"heading":"Zwei Jahre zwischen Abitur und Prüfung","paragraphs":["Nach dem baccalauréat beginnt für viele französische Schüler die classe préparatoire: zwei Jahre mit dichtem Unterricht und wöchentlichen Tests. Danach folgt der concours, eine Aufnahmeprüfung mit sehr niedrigen Erfolgsquoten.","Die Grandes écoles sind selektive Hochschulen außerhalb des allgemeinen Universitätssystems. Sie bilden einen großen Teil der Verwaltungs-, Wissenschafts- und Wirtschaftselite aus, darunter die École polytechnique, Sciences Po und die Écoles normales supérieures."]},{"heading":"Rangordnung und Kritik","paragraphs":["Das System hat seine eigene Hierarchie und Sprache: Studierende heißen élèves, werden nach dem concours gereiht, und die obersten Verwaltungsgremien rekrutieren direkt aus wenigen Schulen.","Kritiker nennen es eine Maschine zur Reproduktion der Eliten, da Bewerbungen von Familien der oberen Berufe dominieren. Quoten und neue Vorbereitungsklassen für ärmere Regionen wurden heftig debattiert. Regional und zwischen Generationen unterscheidet sich die Erfahrung deutlich."]}],"en":[{"heading":"Two Years Between Bac and Concours","paragraphs":["After the baccalauréat, many French students enter classes préparatoires: two years of intensive classes and weekly written tests. Then they sit the concours, competitive exams with very low admission rates.","The grandes écoles are selective institutions outside the main university system, training much of France's administrative, scientific and business elite, including École polytechnique, Sciences Po and the Écoles normales supérieures."]},{"heading":"Hierarchy and Criticism","paragraphs":["The system has its own hierarchy and vocabulary: students are élèves, ranked by concours, and top civil-service corps recruit directly from a handful of schools.","Critics call it a machine for reproducing elites, since upper-profession families dominate admissions; quotas and new preparatory classes for poorer areas have been contested. The experience varies by region and generation."]}]},"context":{"countries":["FR"],"region":"Paris","continent":"europe","languages":["fr"],"period":"contemporary"},"tags":["work-and-education","Paris"],"sources":[{"organization":"Wikipedia","title":{"ar":"Grande école","de":"Grande école","en":"Grande école"},"url":"https://en.wikipedia.org/wiki/Grande_école","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Classe préparatoire aux grandes écoles","de":"Classe préparatoire aux grandes écoles","en":"Classe préparatoire aux grandes écoles"},"url":"https://en.wikipedia.org/wiki/Classe_préparatoire_aux_grandes_écoles","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طالب في ثانوية بليون يقضي عامين في الصف التحضيري بنحو أربعين ساعة درساً أسبوعياً واختبار كتابي كل أسبوع، ثم يجلس للامتحان في الربيع آملاً في مقعد من قلة.","de":"Ein Gymnasiast in Lyon verbringt zwei Jahre in der prépa mit rund 40 Unterrichtsstunden und einem schriftlichen Test pro Woche und sitzt im Frühjahr im concours – in der Hoffnung auf einen von wenigen Plätzen.","en":"A lycée student in Lyon spends two years in prépa with about 40 hours of classes and a written test every week, then sits the concours in spring hoping for one of a handful of places."},"misunderstanding":{"ar":"يظن البعض أن كل طالب فرنسي يمر بهذا الطريق، لكن معظمهم لا يدخلونه أبداً، فالمدارس الكبرى تجاور قطاعاً جامعياً جماهيرياً مختلف التمويل والمكانة.","de":"Viele glauben, alle französischen Studierenden gingen diesen Weg. Doch die meisten betreten ihn nie; die Grandes écoles stehen neben einem großen Universitätssystem mit anderer Finanzierung und anderem Prestige.","en":"Many assume every French student passes through this route. Most never enter it: the grandes écoles sit alongside a mass university sector with different funding and prestige, so the pipeline is influential but far from all of French higher education."},"comparison":{"ar":"يقارن كثيرون هذا المسار بمسارات انتقاء أخرى في أوروبا، لكن ما يميزه هو كثافة العامين التحضيريين وهرمية الامتحان الواحد الذي يوزّع الطلاب على المدارس.","de":"Oft wird dieser Weg mit Auswahlverfahren anderer europäischer Länder verglichen. Besonders ist die Intensität der zwei Vorbereitungsjahre und die Hierarchie, die ein einziger concours den Schulen zuweist.","en":"Observers often compare it with selection routes elsewhere in Europe, but what stands out is the intensity of the two preparatory years and a single concours ranking that sorts students across schools."}},{"id":"wrk-009","version":2,"slug":"brick-lane-and-the-making-of-banglatown","contentType":"note","category":"migration-and-identity","title":{"ar":"بريكل لين وبناء بنغلاتاون","de":"Brick Lane und die Entstehung von Banglatown","en":"Brick Lane and the making of Banglatown"},"deck":{"ar":"كيف أصبح شارع في شرق لندن قلب المجتمع البنغالي البريطاني، وكيف تغيّر عبر موجات الهجرة.","de":"Wie eine Straße im Osten Londons zum Herz der britisch-bangladeschischen Gemeinschaft wurde und sich mit jeder Migrationswelle veränderte.","en":"How a street in east London became the heart of the British Bangladeshi community, and how it changed with each wave of migration."},"teaser":{"ar":"من نسّاجي الحرير إلى المهاجرين البنغاليين، يحكي بريكل لين قصة أجيال تعاقبت على نفس الشارع.","de":"Von Seidenwebern zu bangladeschischen Einwanderern: Die Brick Lane erzählt die Geschichte von Generationen, die dieselbe Straße prägten.","en":"From Huguenot silk weavers to Bangladeshi migrants, Brick Lane tells the story of generations who shaped the same street."},"readingMinutes":1,"sections":{"ar":[{"heading":"شارع تحكي جدرانه الهجرة","paragraphs":["في خمسينيات القرن الماضي، بدأ مهاجرون من سيلهيت، التي كانت جزءاً من باكستان الشرقية ثم بنغلاديش، بالاستقرار في بريكل لين بشرق لندن. أصبح الشارع قلب المجتمع البنغالي البريطاني، لكن مبانيه تحمل آثار هجرات أقدم: نسّاجو الحرير الهوغونوتيون في القرن الثامن عشر، ثم المهاجرون اليهود الذين تحوّل كنيسهم إلى مسجد بريكل لين الجامع.","اشتهرت المنطقة بمطاعم الكاري البنغالية وسوق الأحد، ومنذ التسعينيات رُوّج لها باسم \"بنغلاتاون\". تتركّز حياة المجتمع حول مسجد شرق لندن في وايت تشابل رود، والإعلام باللغة البنغالية، ومهرجان رأس السنة البنغالية (بويلا بويشاخ).","لكن التغيير مستمر: غلاء الإيجارات والحياة الليلية في شورديتش دفعا كثيراً من العائلات البنغالية إلى إلفورد ومناطق أخرى في ضواحي لندن. يختلف هذا التأثير بين الأجيال: فالشباب قد ينتقلون بحثاً عن العمل، بينما يبقى كبار السن مرتبطين بالحي."]},{"heading":"رمز أكثر من حي","paragraphs":["\"بنغلاتاون\" اسم يختصر مجتمعاً معقداً: اللغة السيلهيتية هي لغة البيت عادةً وليست البنغالية الفصحى، ومعظم البنغاليين البريطانيين يعيشون الآن خارج تاور هامليتس. لذا يظل الشارع رمزاً بقدر ما هو حي."]}],"de":[{"heading":"Eine Straße, deren Mauern Migration erzählen","paragraphs":["In den 1950er Jahren ließen sich Migranten aus Sylhet, damals Teil Ostpakistans und später Bangladeschs, in der Brick Lane im Osten Londons nieder. Die Straße wurde zum Herz der britisch-bangladeschischen Gemeinschaft, doch ihre Gebäude zeugen von älteren Migrationen: hugenottische Seidenweber im 18. Jahrhundert, dann jüdische Einwanderer, deren Synagoge zur Brick Lane Jamme Masjid wurde.","Bekannt wurde das Viertel durch bangladeschische Curryhäuser und den Sonntagsmarkt; seit den 1990er Jahren wurde es als „Banglatown“ vermarktet. Das Gemeinschaftsleben dreht sich um die East London Mosque an der Whitechapel Road, bengalischsprachige Medien und das bengalische Neujahrsfest (Pohela Boishakh).","Doch der Wandel hält an: Gentrifizierung, steigende Mieten und das Nachtleben in Shoreditch haben viele bangladeschische Familien nach Ilford und in andere Außenbezirke Londons gedrängt. Dieser Effekt variiert je nach Generation – Jüngere ziehen oft aus beruflichen Gründen weg, während Ältere dem Viertel verbunden bleiben."]},{"heading":"Ein Symbol, mehr als ein Viertel","paragraphs":["„Banglatown“ verdichtet eine komplexe Gemeinschaft: Sylheti ist meist die Haussprache, nicht Standardbengalisch, und die meisten britischen Bangladescher leben heute außerhalb von Tower Hamlets. Die Straße ist daher ebenso Symbol wie Nachbarschaft."]}],"en":[{"heading":"A street whose walls tell of migration","paragraphs":["In the 1950s, migrants from Sylhet, then part of East Pakistan and later Bangladesh, began settling in Brick Lane in east London. The street became the heart of the British Bangladeshi community, but its buildings record earlier migrations: Huguenot silk weavers in the 18th century, then Jewish immigrants, whose synagogue became the Brick Lane Jamme Masjid.","The area became famous for Bangladeshi curry houses and the Sunday market, and from the 1990s local branding promoted it as \"Banglatown\". Community life centres on the East London Mosque on Whitechapel Road, Bengali-language media and the Bengali New Year (Pohela Boishakh) street festival.","But change continues: gentrification, rising rents and Shoreditch nightlife have pushed many Bangladeshi families to Ilford and other parts of outer London. This effect varies by generation – younger people often move for work, while older residents remain attached to the neighbourhood."]},{"heading":"A symbol as much as a neighbourhood","paragraphs":["\"Banglatown\" compresses a complex community: Sylheti is the usual home language rather than standard Bengali, and most British Bangladeshis now live outside Tower Hamlets, so the street is a symbol as much as a neighbourhood."]}]},"context":{"countries":["GB"],"region":"Tower Hamlets, London","community":"British Bangladeshi community","continent":"europe","languages":["en","bn"],"period":"contemporary"},"tags":["migration-and-identity","Tower Hamlets, London"],"sources":[{"organization":"Wikipedia","title":{"ar":"Brick Lane","de":"Brick Lane","en":"Brick Lane"},"url":"https://en.wikipedia.org/wiki/Brick_Lane","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"British Bangladeshis","de":"British Bangladeshis","en":"British Bangladeshis"},"url":"https://en.wikipedia.org/wiki/British_Bangladeshis","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في عصر يوم جمعة، تبيع أكشاك السوق أقمشة الساري والخضروات والتوابل بينما يصطف موظفو المكاتب لشراء الكعك، وتتعايش هجرات الشارع المتعاقبة جنباً إلى جنب.","de":"An einem Freitagnachmittag verkaufen Marktstände Saristoffe, Gemüse und Gewürze, während Büroangestellte nach Bagels anstehen – die aufeinanderfolgenden Migrationen der Straße liegen nebeneinander.","en":"On a Friday afternoon, market stalls sell sari fabric, vegetables and spices while office workers queue for bagels, the street's successive migrations sitting side by side."},"misunderstanding":{"ar":"يُفترض أحياناً أن \"بنغلاتاون\" يمثل كل البنغاليين البريطانيين، لكنه في الواقع حي محدد ارتبط بموجة هجرة معينة، وكثير من أبناء المجتمع يعيشون اليوم في ضواحي لندن.","de":"Manchmal wird angenommen, „Banglatown“ stehe für alle britischen Bangladescher, doch es ist ein bestimmtes Viertel, das mit einer Einwanderungswelle verbunden ist; viele aus der Gemeinschaft leben heute in den Außenbezirken.","en":"It is sometimes assumed that \"Banglatown\" represents all British Bangladeshis, but it is a specific neighbourhood tied to one wave of migration, and many in the community now live in outer London."},"comparison":{"ar":"كما تحول كنيس يهودي إلى مسجد، يذكّرنا بريكل لين بأن أحياء المهاجرين ليست ثابتة، بل تتغير مع كل جيل جديد.","de":"So wie eine Synagoge zu einer Moschee wurde, erinnert die Brick Lane daran, dass Einwandererviertel nicht statisch sind, sondern sich mit jeder Generation verändern.","en":"Just as a synagogue became a mosque, Brick Lane reminds us that migrant neighbourhoods are not static but change with each new generation."}},{"id":"wrk-010","version":2,"slug":"the-pub-and-the-working-men-s-club","contentType":"note","category":"cities-and-community","title":{"ar":"الحانة ونادي العمال في شمال إنجلترا","de":"Der Pub und der Arbeiterclub in Nordengland","en":"The pub and the working men's club"},"deck":{"ar":"كيف تشكّل الحانة ونادي العمال حياة المجتمعات المحلية في شمال إنجلترا","de":"Wie Pub und Arbeiterclub das Gemeinschaftsleben in Nordengland prägen","en":"How the pub and the working men's club shape community life in Northern England"},"teaser":{"ar":"منذ القرن الثامن عشر، والحانة مؤسسة اجتماعية مرخصة، ونادي العمال تعاونية أعضاؤها فقط، لكن كليهما يواجه تراجعًا حادًا.","de":"Seit dem 18. Jahrhundert ist der Pub eine lizenzierte soziale Einrichtung, der Arbeiterclub eine Genossenschaft nur für Mitglieder – doch beide kämpfen mit starkem Rückgang.","en":"Since the 18th century, the pub has been a licensed social institution, the working men's club a members-only cooperative – but both face sharp decline."},"readingMinutes":1,"sections":{"ar":[{"heading":"أكثر من مجرد مكان للشرب","paragraphs":["الحانة العامة مؤسسة اجتماعية مرخصة منذ القرن الثامن عشر على الأقل. قانون البيرهوس 1830 ألغى القيود على بيع البيرة فازدهرت الحانات الصغيرة، ثم جاءت قوانين الترخيص اللاحقة وقانون 2003 لتنظيم ساعات العمل.","تعمل الحانة كـ\"مكان ثالث\"، إذ تستضيف فرق السهام والبلياردو وأمسيات المسابقات واجتماعات نقابة العمال وحفلات التأبين وأعياد الميلاد، وليس الشرب فقط. تختلف هذه الأدوار بين الأجيال؛ فالشباب قد يفضلون المقاهي أو التواصل عبر الإنترنت."]},{"heading":"أندية العمال: تعاونيات محلية","paragraphs":["تأسست أندية العمال في القرن التاسع عشر كتعاونيات للأعضاء فقط، يديرها committee منتخبة، وتقدم بيرة رخيصة وقاعة حفلات. وهي شائعة بشكل خاص في شمال إنجلترا وميدلاندز.","شهدت التجارة تراجعًا حادًا، إذ أغلقت آلاف الحانات في العقدين الماضيين مع انخفاض شرب الشباب وانتقال الحياة الاجتماعية إلى الإنترنت والمقاهي. وقد حلّت الحانات المعدّة للطعام والحانات الصغيرة جزئيًا محل الحانات التقليدية، مما غيّر من يرتادها ومتى."]}],"de":[{"heading":"Mehr als nur ein Ort zum Trinken","paragraphs":["Der Public House ist mindestens seit dem 18. Jahrhundert eine lizenzierte soziale Einrichtung. Der Beerhouse Act von 1830 deregulierte den Bierverkauf und löste einen Boom kleiner Bierhäuser aus, später prägten Lizenzgesetze und der Licensing Act von 2003 die Öffnungszeiten.","Pubs fungieren als „dritte Orte“: Sie beherbergen Dart- und Poolteams, Quizabende, Gewerkschaftstreffen, Trauerfeiern und Geburtstagsfeiern – nicht nur das Trinken. Diese Rollen variieren je nach Generation; Jüngere bevorzugen oft Cafés oder Online-Kommunikation."]},{"heading":"Arbeiterclubs: lokale Genossenschaften","paragraphs":["Arbeiterclubs wurden im 19. Jahrhundert als Mitgliedergenossenschaften gegründet, von einem gewählten Komitee geführt, mit billigem Bier und einem Konzertsaal. Besonders verbreitet sind sie in Nordengland und den Midlands.","Das Gewerbe ist stark zurückgegangen: Tausende Pubs schlossen in den letzten zwei Jahrzehnten, da Jüngere weniger trinken und das soziale Leben online und in Cafés stattfindet. Gastropubs und winzige Micropubs haben die traditionellen Lokale teilweise ersetzt und verändert, wer sie wann nutzt."]}],"en":[{"heading":"More than just a place to drink","paragraphs":["The public house has been a licensed social institution since at least the 18th century. The 1830 Beerhouse Act deregulated beer sales and created a boom in small beerhouses, while later licensing acts and the 2003 Licensing Act shaped opening hours.","Pubs work as third places: they host darts and pool teams, quiz nights, union branch meetings, wakes and birthday parties, not only drinking. These roles vary by generation; younger people may prefer cafés or online socializing."]},{"heading":"Working men's clubs: local cooperatives","paragraphs":["Working men's clubs, founded in the 19th century, are members-only cooperatives run by a committee, with cheap beer and a concert room. They are especially common in northern England and the Midlands.","The trade has declined sharply, with thousands of pubs closing in the past two decades as younger people drink less and social life moves online and to cafés. Food-led gastropubs and tiny micropubs have partly replaced the old drinking-only locals, changing who uses them and when."]}]},"context":{"countries":["GB"],"region":"Northern England","continent":"europe","languages":["en"],"period":"contemporary"},"tags":["cities-and-community","Northern England"],"sources":[{"organization":"Wikipedia","title":{"ar":"Pub","de":"Pub","en":"Pub"},"url":"https://en.wikipedia.org/wiki/Pub","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Working men's club","de":"Working men's club","en":"Working men's club"},"url":"https://en.wikipedia.org/wiki/Working_men's_club","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في نادٍ بجنوب يوركشاير، تعرض لوحة اللجنة بingo الأسبوع المقبل، ومأدبة عزاء، وسحب الأعضاء، وكلفة كوب البيرة أقل من بار وسط المدينة.","de":"In einem Club in South Yorkshire listet das Komitee-Schwarze Brett das Bingo der nächsten Woche, ein Trauerbuffet und die Mitgliederziehung auf – und ein Pint kostet weniger als in der Bar im Stadtzentrum.","en":"In a South Yorkshire club, the committee noticeboard lists next week's bingo, a funeral buffet and the members' draw, and a pint costs less than in the town-centre bar."},"misunderstanding":{"ar":"يُفترض أحيانًا أن الحانات مجرد أماكن للشرب، لكنها مراكز اجتماعية متعددة الأغراض، وأن أندية العمال حكر على الرجال، مع أنها مفتوحة للعائلات أحيانًا.","de":"Manchmal wird angenommen, Pubs seien nur Orte zum Trinken, doch sie sind multifunktionale soziale Zentren; auch gelten Arbeiterclubs als reine Männerdomäne, sind aber oft für Familien offen.","en":"Pubs are sometimes assumed to be just drinking places, but they are multi-purpose social centres; working men's clubs are thought to be male-only, yet they are often open to families."},"comparison":{"ar":"بينما تتراجع الحانات التقليدية، تزدهر الحانات الصغيرة والحانات المعدّة للطعام، مما يعكس تحولًا في أنماط الحياة الاجتماعية والاستهلاك.","de":"Während traditionelle Pubs zurückgehen, florieren Micropubs und Gastropubs – ein Spiegel des Wandels sozialer Lebensstile und Konsummuster.","en":"While traditional pubs decline, micropubs and gastropubs thrive, reflecting a shift in social lifestyles and consumption patterns."}},{"id":"wrk-011","version":2,"slug":"the-gaeltacht-and-the-boundaries-of-irish","contentType":"language","category":"languages","title":{"ar":"الغايلتاخت وحدود اللغة الأيرلندية","de":"Die Gaeltacht und die Grenzen des Irischen","en":"The Gaeltacht and the boundaries of Irish"},"deck":{"ar":"مناطق صغيرة تُعلن رسميًا ناطقة بالأيرلندية، لكن الحياة اليومية فيها تفاوض مستمر بين لغتين.","de":"Kleine offiziell irischsprachige Gebiete, in denen der Alltag dennoch ein ständiges Aushandeln zwischen zwei Sprachen ist.","en":"Small officially Irish-speaking districts where everyday life is a constant negotiation between two languages."},"teaser":{"ar":"في كونيمارا وغيرها، يعيش نحو ٢٪ من سكان أيرلندا في مناطق الغايلتاخت، حيث الأيرلندية لغة البيت لأقلية فقط.","de":"In Connemara und anderswo lebt rund 2 % der irischen Bevölkerung in Gaeltachtaí, doch Irisch ist dort nur für eine Minderheit Haushaltssprache.","en":"In Connemara and elsewhere, about 2% of Ireland's population lives in Gaeltachtaí, yet Irish is the household language for only a minority there."},"readingMinutes":1,"sections":{"ar":[{"heading":"مناطق صغيرة بثقل رسمي","paragraphs":["الغايلتاخت (جمعها Gaeltachtaí) هي المناطق المعلنة رسميًا ناطقة بالأيرلندية، وتتركز في مقاطعات غالواي وكيري ودونيغال ومايو وكورك وواترفورد وميث. لكنها صغيرة: نحو ٢٪ من سكان أيرلندا يعيشون فيها، وحتى داخلها الأيرلندية لغة البيت لأقلية فقط.","تختلف هذه الصورة بين جيل وآخر وبين قرية وأخرى، فالإنجليزية تهيمن في مناطق كثيرة، ومعظم متحدثي الأيرلندية اليوم يعيشون في المدن والبلدات خارج المناطق الرسمية.","تأسست وكالة أوداراس نا غايلتاختا عام ١٩٨٠ لدعم العمل والإسكان والتخطيط اللغوي في هذه المناطق."]},{"heading":"مدرسة الصيف كطقس عبور","paragraphs":["يحمل تقليد الكولايستي سامرايد الصيفي المراهقين للعيش مع عائلات في الغايلتاخت والتحدث بالأيرلندية، وهو طقس عبور لكثير من الطلاب الأيرلنديين.","وفي الوقت نفسه نمت المدارس الأيرلندية (Gaelscoileanna) بقوة خارج الغايلتاخت، والأيرلندية لغة رسمية في أيرلندا وفي الاتحاد الأوروبي.","في متجر بكونيمارا يعدّ البائع الباقي بالأيرلندية، ولا يتحول إلى الإنجليزية إلا حين يجيبه الزبون بها، وهي مساومة صغيرة يومية على اللغة."]}],"de":[{"heading":"Kleine Gebiete mit großem Status","paragraphs":["Die Gaeltacht (Plural Gaeltachtaí) sind die offiziell ausgewiesenen irischsprachigen Bezirke, vor allem in den Counties Galway, Kerry, Donegal, Mayo, Cork, Waterford und Meath. Sie sind klein: Rund 2 % der Bevölkerung Irlands lebt dort, und selbst innerhalb der Bezirke ist Irisch nur für eine Minderheit Haushaltssprache.","Dieses Bild variiert je nach Generation und Dorf, Englisch dominiert in vielen Gebieten, und die meisten Irischsprecher leben heute in Städten und Orten außerhalb der offiziellen Bezirke.","Die Gaeltacht-Behörde Údarás na Gaeltachta, 1980 gegründet, fördert Beschäftigung, Wohnen und Sprachplanung in diesen Gebieten."]},{"heading":"Das Sommerkolleg als Übergangsritual","paragraphs":["Die Tradition des Coláiste samhraidh schickt Jugendliche zu Gastfamilien in die Gaeltacht, wo sie Irisch sprechen – ein Übergangsritual für viele irische Schülerinnen und Schüler.","Zugleich sind irischsprachige Schulen (Gaelscoileanna) außerhalb der Gaeltacht stark gewachsen, und Irisch ist Amtssprache in Irland und in der Europäischen Union.","In einem Laden in Connemara zählt die Verkäuferin das Wechselgeld auf Irisch und wechselt erst ins Englische, wenn die Kundschaft auf Englisch antwortet – eine kleine tägliche Verhandlung über Sprache."]}],"en":[{"heading":"Small districts with official weight","paragraphs":["The Gaeltacht (plural Gaeltachtaí) are the officially designated Irish-speaking districts, concentrated in counties Galway, Kerry, Donegal, Mayo, Cork, Waterford and Meath. They are small: roughly 2% of Ireland's population lives there, and even inside the districts Irish is the household language for only a minority.","This picture varies by generation and village, English dominates in many areas, and most Irish speakers today live in cities and towns outside the official districts.","The Gaeltacht agency Údarás na Gaeltachta, established in 1980, supports employment, housing and language planning in these areas."]},{"heading":"The summer college as a rite of passage","paragraphs":["The summer college (coláiste samhraidh) tradition sends teenagers to live with Gaeltacht families and speak Irish, a rite of passage for many Irish students.","At the same time, Irish-medium schooling (Gaelscoileanna) has grown strongly outside the Gaeltacht, and Irish is an official language of Ireland and of the European Union.","In a Connemara shop, the shopkeeper counts out change in Irish and switches to English only when the customer answers in English, a small daily negotiation over language."]}]},"context":{"countries":["IE"],"region":"Connemara","continent":"europe","languages":["ga","en"],"period":"contemporary"},"tags":["languages","Connemara"],"sources":[{"organization":"Wikipedia","title":{"ar":"Gaeltacht","de":"Gaeltacht","en":"Gaeltacht"},"url":"https://en.wikipedia.org/wiki/Gaeltacht","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Irish language","de":"Irish language","en":"Irish language"},"url":"https://en.wikipedia.org/wiki/Irish_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في متجر بكونيمارا يعدّ البائع الباقي بالأيرلندية، ولا يتحول إلى الإنجليزية إلا حين يجيبه الزبون بها، وهي مساومة صغيرة يومية على اللغة.","de":"In einem Laden in Connemara zählt die Verkäuferin das Wechselgeld auf Irisch und wechselt erst ins Englische, wenn die Kundschaft auf Englisch antwortet – eine kleine tägliche Verhandlung über Sprache.","en":"In a Connemara shop, the shopkeeper counts out change in Irish and switches to English only when the customer answers in English, a small daily negotiation over language."},"misunderstanding":{"ar":"يُظن أن الغايلتاخت تعني أن الأيرلندية لغة الجميع هناك، لكنها في الواقع لغة البيت لأقلية فقط، والإنجليزية حاضرة بقوة.","de":"Man nimmt an, die Gaeltacht bedeute, dass dort alle Irisch sprechen, doch es ist Haushaltssprache einer Minderheit, und Englisch ist stark präsent.","en":"People assume the Gaeltacht means everyone there speaks Irish, but it is the household language of a minority and English is strongly present."},"comparison":{"ar":"يشبه الأمر مناطق لغوية محمية رسميًا، لكن المدارس الأيرلندية خارجها تنمو أسرع من الأحياء الناطقة بها.","de":"Es ähnelt offiziell geschützten Sprachgebieten, doch die irischsprachigen Schulen außerhalb wachsen schneller als die irischsprachigen Viertel selbst.","en":"It resembles officially protected language areas, yet Irish-medium schools outside them are growing faster than the Irish-speaking districts themselves."},"expression":{"original":"Gaeltacht","language":"Irish (Gaeilge)","gloss":{"ar":"منطقة معلنة رسميًا ناطقة بالأيرلندية","de":"ein offiziell ausgewiesener irischsprachiger Bezirk","en":"an officially designated Irish-speaking district"},"usage":{"ar":"تُستخدم للإشارة إلى المناطق الرسمية الناطقة بالأيرلندية، وجمعها Gaeltachtaí.","de":"Bezeichnet die offiziellen irischsprachigen Gebiete; Plural Gaeltachtaí.","en":"Used for the official Irish-speaking districts; plural Gaeltachtaí."},"transliteration":"Gaeltacht"}},{"id":"wrk-012","version":2,"slug":"siesta-sobremesa-and-spain-s-working-rhythm","contentType":"note","category":"everyday-life","title":{"ar":"القيلولة والغداء الممتد في إسبانيا","de":"Siesta, Sobremesa und Spaniens Arbeitsrhythmus","en":"Siesta, Sobremesa and Spain's Working Rhythm"},"deck":{"ar":"القيلولة ليست مجرد نوم، بل جزء من إيقاع يومي يتغير مع العمر والمهنة والمنطقة.","de":"Die Siesta ist mehr als Schlaf – sie ist Teil eines Tagesrhythmus, der sich mit Alter, Beruf und Region wandelt.","en":"The siesta is more than sleep—it's part of a daily rhythm that shifts with age, job, and region."},"teaser":{"ar":"بين القيلولة والغداء الممتد، كيف ينظم الإسبان يومهم؟ نظرة على عادات العمل والراحة في الأندلس وإسبانيا.","de":"Zwischen Siesta und Sobremesa: Wie gestalten Spanier ihren Tag? Ein Blick auf Arbeits- und Ruhegewohnheiten in Andalusien und Spanien.","en":"Between siesta and sobremesa: how do Spaniards structure their day? A look at work and rest habits in Andalusia and Spain."},"readingMinutes":1,"sections":{"ar":[{"heading":"القيلولة: أسطورة أم واقع؟","paragraphs":["القيلولة استراحة منتصف النهار ارتبطت تاريخياً بالحرارة وبأيام العمل الزراعية الطويلة، وكانت مألوفة في جنوب أوروبا كلها وليس في إسبانيا وحدها. اليوم، قلة من العاملين يأخذون قيلولة حقيقية؛ فالدراسات تظهر أنها أكثر شيوعاً بين المتقاعدين منها بين الموظفين بدوام كامل.","مع ذلك، لا تزال كثير من المتاجر ومؤسسات الضيافة تقسم يومها، فتغلق حوالي الساعة 13:30 أو 14:00 وتعيد الفتح حوالي 16:30 أو 17:00، مع وجبة رئيسية بعد ذلك، بينما انتقلت معظم المكاتب إلى يوم متواصل."]},{"heading":"السوبريميسا: اجتماع على الطاولة","paragraphs":["السوبريميسا — البقاء على الطاولة بعد الغداء للحديث — غالباً ما تكون الطقس الاجتماعي الأهم من النوم، خاصة في الوجبات العائلية. فبعد أن تُرفع الأطباق، يستمر القهوة والحديث لساعات."]}],"de":[{"heading":"Siesta: Mythos oder Realität?","paragraphs":["Die Siesta ist eine Mittagspause, die historisch mit Hitze und langen landwirtschaftlichen Arbeitstagen verbunden ist und einst in ganz Südeuropa üblich war, nicht nur in Spanien. Heute machen nur wenige Berufstätige eine echte Siesta; Umfragen zeigen, dass sie bei Rentnern weit verbreiteter ist als bei Vollzeitbeschäftigten.","Dennoch teilen viele Geschäfte und Gastronomiebetriebe den Tag noch immer: Sie schließen gegen 13:30 oder 14:00 Uhr und öffnen gegen 16:30 oder 17:00 Uhr wieder, mit der Hauptmahlzeit danach, während die meisten Büros zu einem durchgehenden Arbeitstag übergegangen sind."]},{"heading":"Sobremesa: Gespräch am Tisch","paragraphs":["Die Sobremesa – das Verweilen am Tisch nach dem Mittagessen zum Gespräch – ist oft das wichtigere soziale Ritual als der Schlaf, besonders bei Familienessen. Wenn die Teller abgeräumt sind, füllen Kaffee und Gespräche noch Stunden."]}],"en":[{"heading":"Siesta: Myth or Reality?","paragraphs":["The siesta is a midday break historically linked to heat and long agricultural working days, once familiar across southern Europe, not only in Spain. Today, only a minority of workers take a real siesta; surveys show it is far more common among retired people than full-time employees.","Still, many shops and hospitality businesses split the day, closing around 13:30 or 14:00 and reopening around 16:30 or 17:00, with the main meal afterwards, while most offices have moved to a continuous day."]},{"heading":"Sobremesa: Conversation at the Table","paragraphs":["The sobremesa—lingering at the table after lunch to talk—is often the more important social ritual than sleep, especially at family meals. Once the plates are cleared, coffee and conversation fill hours."]}]},"context":{"countries":["ES"],"region":"Andalusia","continent":"europe","languages":["es"],"period":"contemporary"},"tags":["everyday-life","Andalusia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Siesta","de":"Siesta","en":"Siesta"},"url":"https://en.wikipedia.org/wiki/Siesta","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Sobremesa","de":"Sobremesa","en":"Sobremesa"},"url":"https://en.wikipedia.org/wiki/Sobremesa","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"غداء عائلي في مدريد يوم الأحد يمتد من الساعة 14:00 حتى 17:00، مع قهوة وحديث يملأ السوبريميسا بعد إزالة الأطباق.","de":"Ein Sonntagsessen einer Madrider Familie dauert von 14:00 bis 17:00 Uhr, wobei Kaffee und Gespräche die Sobremesa lange nach dem Abräumen der Teller füllen.","en":"A Madrid family's Sunday lunch runs from 14:00 to 17:00, with coffee and conversation filling the sobremesa long after the plates have been cleared."},"misunderstanding":{"ar":"أسطورة القيلولة مبالغ فيها: في المدن الكبرى والمكاتب يكون يوم العمل محكماً، والعادات الإقليمية تختلف، ووصف إسبانيا بأمة النائمين هو صورة نمطية يجدها الإسبان مملة.","de":"Die Siesta-Legende ist übertrieben: In Großstädten und Büros ist der Arbeitstag straff, regionale Gewohnheiten unterscheiden sich, und Spanien als Nation von Nickerchen-Machern zu bezeichnen, ist ein Klischee, das Spanier oft als lästig empfinden.","en":"The siesta legend is overstated: in big cities and offices the working day is tight, regional habits differ, and calling Spain a nation of nappers is a caricature that Spaniards often find tedious."},"comparison":{"ar":"بينما تحافظ المتاجر على يوم مقسم، تتبنى المكاتب يوماً متواصلاً، مما يعكس تنوعاً في إيقاع العمل داخل البلد الواحد.","de":"Während Geschäfte den geteilten Tag beibehalten, haben Büros den durchgehenden Tag übernommen – ein Zeichen für die Vielfalt des Arbeitsrhythmus im selben Land.","en":"While shops keep the split day, offices have adopted a continuous schedule—reflecting diverse work rhythms within the same country."}},{"id":"wrk-013","version":2,"slug":"euskara-and-the-basque-language-revival","contentType":"language","category":"languages","title":{"ar":"الباسكية: لغة تُبعث من جديد","de":"Baskisch: eine Sprache lebt wieder auf","en":"Euskara and the Basque revival"},"deck":{"ar":"لغة معزولة تتحدثها مئات الآلاف، يجمعها التعليم والمعيار المكتوب وتُغنيها اللهجات.","de":"Eine isolierte Sprache mit Hunderttausenden Sprechenden, getragen von Schule, Standardform und lebendigen Dialekten.","en":"An isolate language spoken by hundreds of thousands, carried by schooling, a written standard and stubborn regional variety."},"teaser":{"ar":"كيف يعيش متحدثو الباسكية بين الإسبانية ولغتهم الأم، وكيف أعاد التعليم والكتابة الموحّدة إحياءها؟","de":"Wie leben Baskischsprachige zwischen Spanisch und Euskara, und wie haben Bildung und eine einheitliche Schrift die Sprache gestärkt?","en":"How do Basque speakers live between Spanish and euskara, and how did education and a standard written form help the language recover?"},"readingMinutes":1,"sections":{"ar":[{"heading":"لغة بلا أقارب","paragraphs":["الباسكية (euskara) لغة معزولة، لا تربطها صلة بالإسبانية ولا بأي لغة حية أخرى، ويتحدثها ما بين 700 ألف و800 ألف شخص. وهي لغة مشتركة رسمياً مع الإسبانية في إقليم الباسك وأجزاء من نافارا.","لا يزال التباين الإقليمي قوياً، مع لهجات مثل البيسكاية والغيپوسكوية والسوليتينية، وما زال الباحثون يتجادلون في أصول اللغة. ويختلف واقعها بين المناطق والأجيال: أقوى في الداخل وأضعف في المدن الكبرى."]},{"heading":"التعليم والمعيار","paragraphs":["قاد التعليم عملية الإحياء: كثير من التلاميذ يدرسون بالباسكية في مسار النموذج D، بينما كانت المدارس المجتمعية «إيكاستولا» رائدة في التعليم بهذه اللغة.","طُوّر الشكل المكتوب الموحّد «باتوا» في أواخر الستينيات لتوحيد اللهجات، وهو اليوم الشكل الأساسي في البث والنشر، إلى جانب حياة ثقافية تنبض بالمهرجانات وشعر «بيرتسولاريتسا» المرتجل ووسائل إعلام بالباسكية."]}],"de":[{"heading":"Eine Sprache ohne Verwandte","paragraphs":["Baskisch (Euskara) ist eine isolierte Sprache, weder mit Spanisch noch mit einer anderen lebenden Sprache verwandt, und wird von geschätzt 700.000 bis 800.000 Menschen gesprochen. Im Baskenland und Teilen Navarras ist es mit Spanisch kooffiziell.","Die regionale Vielfalt bleibt stark, mit Dialekten wie Biscayisch, Gipuzkoanisch und Souletinisch, und Forschende streiten weiter über die Ursprünge. Je nach Region und Generation unterscheidet sich die Lage: stärker im Landesinneren, schwächer in der Metropole Bilbao."]},{"heading":"Schule und Standard","paragraphs":["Bildung trieb die Wiederbelebung voran: Viele Schüler lernen im Modell D auf Baskisch, während gemeinschaftlich gegründete Ikastolas den baskischsprachigen Unterricht voranbrachten.","Die einheitliche Schriftform Batua entstand Ende der 1960er, um Dialekte zu verbinden, und prägt heute Rundfunk und Verlagswesen. Dazu kommt ein Kulturleben mit Festen, improvisierter Bertsolaritza-Dichtung und baskischen Medien."]}],"en":[{"heading":"A language without relatives","paragraphs":["Basque (euskara) is a language isolate, unrelated to Spanish or any other living language, spoken by an estimated 700,000 to 800,000 people. It is co-official with Spanish in the Basque Country and parts of Navarre.","Regional variation remains strong, with dialects such as Biscayan, Gipuzkoan and Souletin, and researchers still debate the language's origins. Its situation varies by region and generation: strongest inland, weaker in metropolitan Bilbao and southern Navarre."]},{"heading":"Schooling and the standard","paragraphs":["Education has driven the revival: many pupils now study through Basque in the model D stream, while community-founded ikastolas pioneered Basque-medium schooling.","The standardised written form, Batua, was developed in the late 1960s to unify dialects and is now the main form used in broadcasting and publishing. Cultural life runs through festivals, bertsolaritza improvised poetry and Basque-language media."]}]},"context":{"countries":["ES"],"region":"Basque Country","continent":"europe","languages":["eu","es"],"period":"contemporary"},"tags":["languages","Basque Country"],"sources":[{"organization":"Wikipedia","title":{"ar":"Basque language","de":"Basque language","en":"Basque language"},"url":"https://en.wikipedia.org/wiki/Basque_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Basque Country (autonomous community)","de":"Basque Country (autonomous community)","en":"Basque Country (autonomous community)"},"url":"https://en.wikipedia.org/wiki/Basque_Country_(autonomous_community)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مدرسة ببلباو، يتحدث الأطفال بالباسكية، ثم ينتقلون إلى الإسبانية لشرح علمي من أستاذ زائر، وبعدها ينضمون إلى نادٍ لشعر البيرتسو بعد الدوام.","de":"In einer Schule in Bilbao plaudern Kinder auf Baskisch, wechseln für eine naturwissenschaftliche Erklärung eines Gastlehrers ins Spanische und gehen später in einen Bertsolaritza-Club.","en":"In a Bilbao school, children chat in Basque, switch to Spanish for a science explanation from a visiting teacher, and later join an after-school bertsolaritza club."},"misunderstanding":{"ar":"يظن كثيرون أن الباسكية لهجة إسبانية قديمة، لكنها لغة مستقلة تماماً وغير مرتبطة بأي لغة حية.","de":"Viele halten Baskisch für einen alten spanischen Dialekt, doch es ist eine eigenständige Sprache ohne Verwandtschaft zu anderen lebenden Sprachen.","en":"Many assume Basque is an old Spanish dialect, but it is a separate language unrelated to Spanish or any other living language."},"comparison":{"ar":"حيث تتعايش لغتان، تصبح الحياة اليومية ثنائية اللغة: الباسكية في البيت والمدرسة، والإسبانية في الإدارة والإعلام الأوسع.","de":"Wo zwei Sprachen zusammenleben, wird der Alltag zweisprachig: Baskisch zu Hause und in der Schule, Spanisch in Verwaltung und breiteren Medien.","en":"Where two languages share daily life, bilingual routines become normal: Basque at home and school, Spanish in administration and wider media."},"expression":{"original":"Kaixo","language":"Basque (euskara)","gloss":{"ar":"مرحباً","de":"Hallo","en":"hello"},"usage":{"ar":"تحية غير رسمية تُقال عند اللقاء في الشارع أو المدرسة.","de":"Informelle Begrüßung auf der Straße oder in der Schule.","en":"An informal greeting used in the street or at school."},"transliteration":"kaixo"}},{"id":"wrk-014","version":2,"slug":"campanilismo-and-loyalty-to-the-town-bell-tower","contentType":"note","category":"cities-and-community","title":{"ar":"كامبانِليزمو: الولاء لبرج الجرس البلدي","de":"Campanilismo: Treue zum Glockenturm der Stadt","en":"Campanilismo and loyalty to the town bell tower"},"deck":{"ar":"في توسكانا، الانتماء إلى البلدة الصغيرة أقوى أحياناً من الانتماء إلى إيطاليا نفسها، ويظهر ذلك في الرياضة والطعام والأعياد.","de":"In der Toskana ist die Bindung an die eigene Kleinstadt oft stärker als die an Italien – sichtbar in Sport, Essen und Festen.","en":"In Tuscany, attachment to a small town often runs deeper than attachment to Italy itself, and it shows in sport, food and festivals."},"teaser":{"ar":"روح البلدة الصغيرة تُبنى حول برج الجرس، وتظهر في المباريات والأعياد والمنافسات بين البلدات المتجاورة.","de":"Der lokale Stolz dreht sich um den Glockenturm und zeigt sich in Rivalitäten zwischen Nachbarorten, in Festen und im Alltag.","en":"Local pride is built around the bell tower and surfaces in derbies, saints' days and rivalries between neighbouring towns."},"readingMinutes":1,"sections":{"ar":[{"heading":"برج الجرس مركز العالم","paragraphs":["يعني كامبانِليزمو التعلّق ببرج الجرس المحلي، ثم الولاء الشديد لبلدة المرء بدلاً من الإقليم أو الأمة. هذا الشعور مرتبط بتوحيد إيطاليا المتأخر عام 1861 وبالتاريخ الطويل للمدن المستقلة التي تركت فخراً مدنياً ومنافسات محلية.","البلدية هي الوحدة السياسية اليومية ومركز الهوية المحلية، لها رئيسها ومجلسها وقديسها الشفيع. ويظهر هذا الولاء في الرياضة والطعام والأعياد: سباق باليو في سيينا يواجه فيه أحياء المدينة بعضها مرتين سنوياً، وتتنافس بلدات توسكانية متجاورة على النبيذ وأعياد القديسين وكرة القدم."]},{"heading":"نظرة نقدية ووجه آخر للروح المحلية","paragraphs":["يُستخدم المصطلح غالباً بنقد ليعني ضيق الأفق، لكنه أيضاً يدعم جمعيات التطوع المحلية والمهرجانات والعناية بالفضاءات العامة المشتركة. الاختلاف بين الأجيال ملحوظ: الشبان يتنقلون بسهولة بين الانتماء المحلي والإقليمي والوطني.","في محادثة واحدة قد يذكر موظف شاب في أريتسو رموز أحياء سيينا ويسخر من برج بيزا ويشرح قواعد تعاونية نبيذ محلية."]}],"de":[{"heading":"Der Glockenturm als Mittelpunkt","paragraphs":["Campanilismo bedeutet die Bindung an den eigenen Glockenturm (campanile) und darüber hinaus eine heftige Treue zur eigenen Stadt oder zum Dorf statt zur Region oder Nation. Das Gefühl hängt mit der späten Einigung Italiens 1861 und der langen Geschichte unabhängiger Stadtstaaten zusammen, die starken Bürgerstolz und lokale Rivalitäten hinterließ.","Die comune, die grundlegende Gemeinde, ist die politische Alltagseinheit und ein Fokus lokaler Identität, mit eigenem Bürgermeister, Rat und Schutzheiligen. Rivalitäten zeigen sich in Sport, Essen und Festen: Beim Palio di Siena treten die contrade, die Stadtviertel, zweimal im Jahr gegeneinander an, und benachbarte toskanische Orte konkurrieren um Wein, Heiligentage und Fußball."]},{"heading":"Kritik und gelebte Nachbarschaft","paragraphs":["Campanilismo wird oft kritisch als Engstirnigkeit verwendet, trägt aber auch lokale Freiwilligenvereine, Feste und die Pflege gemeinsamer öffentlicher Räume. Regionale und generationelle Unterschiede sind deutlich: Junge Leute bewegen sich leicht zwischen lokaler, regionaler und nationaler Zugehörigkeit.","Ein junger Büroangestellter in Arezzo kann in einem Gespräch die contrada-Symbole Sienas nennen, über den Turm von Pisa spotten und die Regeln einer lokalen Weingenossenschaft erklären."]}],"en":[{"heading":"The bell tower at the centre","paragraphs":["Campanilismo means attachment to the local bell tower (campanile) and, by extension, fierce loyalty to one's own town or village rather than to a region or nation. The sentiment is bound up with Italy's late unification in 1861 and the long history of independent city-states, which left strong civic pride and local rivalries.","The comune, the basic municipality, is the everyday political unit and a focus of local identity, with its own mayor, council and patron saint. Rivalries surface in sport, food and festivals: the Palio di Siena pits the city's contrade, or wards, against one another twice a year, and neighbouring Tuscan towns compete over wine, saints' days and football."]},{"heading":"Criticism and everyday care","paragraphs":["Campanilismo is often used critically to mean parochialism, but it also sustains local volunteer associations, festivals and care for shared public spaces. Regional and generational variation is visible: young people move easily between local, regional and national belonging.","A young office worker in Arezzo can name the contrada symbols of Siena, mock Pisa's tower and explain the rules of a local wine cooperative, all in one conversation."]}]},"context":{"countries":["IT"],"region":"Tuscany","continent":"europe","languages":["it"],"period":"contemporary"},"tags":["cities-and-community","Tuscany"],"sources":[{"organization":"Wikipedia","title":{"ar":"Palio di Siena","de":"Palio di Siena","en":"Palio di Siena"},"url":"https://en.wikipedia.org/wiki/Palio_di_Siena","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Comune","de":"Comune","en":"Comune"},"url":"https://en.wikipedia.org/wiki/Comune","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"موظف شاب في أريتسو يسمّي رموز أحياء سيينا ويسخر من برج بيزا ويشرح قواعد تعاونية نبيذ محلية في محادثة واحدة.","de":"Ein junger Büroangestellter in Arezzo nennt die contrada-Symbole Sienas, spottet über den Turm von Pisa und erklärt die Regeln einer lokalen Weingenossenschaft – alles in einem Gespräch.","en":"A young office worker in Arezzo can name the contrada symbols of Siena, mock Pisa's tower and explain the rules of a local wine cooperative, all in one conversation."},"misunderstanding":{"ar":"يُفهم كامبانِليزمو أحياناً كأنه انفصال أو رفض لإيطاليا، لكنه في الغالب تعلّق عملي بالجيران والبلدية لا موقف سياسي.","de":"Campanilismo wird manchmal als Absage an Italien verstanden, ist aber meist eine praktische Bindung an Nachbarschaft und Gemeinde, keine politische Haltung.","en":"Campanilismo is sometimes read as a rejection of Italy, but it is usually a practical attachment to neighbours and the comune rather than a political stance."},"comparison":{"ar":"يشبه هذا الولاء القبلي المحلي في مدن أخرى، لكنه في توسكانا مرتبط تاريخياً بالبلديات المستقلة وبالتوحيد المتأخر.","de":"Ähnliche lokale Loyalitäten gibt es auch anderswo, doch in der Toskana sind sie historisch mit den Stadtstaaten und der späten Einigung verbunden.","en":"Similar local loyalties exist elsewhere, but in Tuscany they are historically tied to the city-states and to late unification."}},{"id":"wrk-015","version":2,"slug":"fika-and-the-swedish-office-coffee-break","contentType":"scene","category":"work-and-education","title":{"ar":"فيكا: استراحة القهوة السويدية","de":"Fika: die schwedische Kaffeepause","en":"Fika and the Swedish Office Coffee Break"},"deck":{"ar":"في المكاتب السويدية، استراحة القهوة ليست رفاهية بل طقس اجتماعي يومي.","de":"In schwedischen Büros ist die Kaffeepause kein Luxus, sondern ein tägliches soziales Ritual.","en":"In Swedish offices, the coffee break is not a luxury but a daily social ritual."},"teaser":{"ar":"فيكا هي استراحة القهوة في السويد، تُؤخذ عادة مرتين يوميًا في أوقات محددة مع قهوة وكعكة قرفة، وتعزز التواصل وتقلل التسلسل الهرمي.","de":"Fika ist die schwedische Kaffeepause, meist zweimal täglich zu festen Zeiten mit Kaffee und Zimtschnecke. Sie fördert Gespräche und flacht Hierarchien ab.","en":"Fika is the Swedish coffee break, usually taken twice a day at fixed times with coffee and a cinnamon bun, fostering conversation and flattening hierarchy."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقس يومي في مكان العمل","paragraphs":["فيكا هو مصطلح سويدي لاستراحة القهوة، وهي مؤسسة اجتماعية تُمارس عادة مرتين يوميًا في أوقات ثابتة نسبيًا. تُقدم القهوة مع شيء صغير يؤكل، غالبًا كعكة القرفة (kanelbulle). الكلمة مأخوذة من kaffe (قهوة) بطريقة عكس المقاطع، وتُستخدم كاسم وفعل: att fika، vi fikar.","في العديد من أماكن العمل، تُجدول الفيكا في الصباح وبعد الظهر، ويُتوقع من المديرين الحضور، وقد يُعتبر من يتخطاها غير اجتماعي. الاستراحة متأنية عمدًا وتُقدّر كوسيلة لتقليل التسلسل الهرمي؛ فالمحادثات تمتد بين العمل والحياة الخاصة وتعبر حدود الأقسام."]},{"heading":"تقاليد تتغير","paragraphs":["تكون الفيكا المؤسسية أقوى في المكاتب والمدارس والهيئات العامة، وقد تراجعت بسبب العمل بنظام الورديات والشركات الصغيرة والعمل عن بعد. ليس كل سويدي يأخذ فيكا مرتين يوميًا، ويختلف الطقس بين أماكن العمل؛ فقد يشعر القادم الجديد بأنه إلزامي، بينما يفتقده العاملون عن بعد والورديات."]}],"de":[{"heading":"Ein tägliches Ritual am Arbeitsplatz","paragraphs":["Fika ist der schwedische Begriff für die Kaffeepause, eine soziale Institution, die meist zweimal täglich zu relativ festen Zeiten stattfindet. Es gibt Kaffee und etwas Kleines zu essen, oft eine Zimtschnecke (kanelbulle). Das Wort ist eine umgekehrte Silbenform von kaffe (Kaffee) und funktioniert als Nomen und Verb: att fika, vi fikar.","In vielen Büros ist Fika morgens und nachmittags eingeplant, Führungskräfte werden erwartet, und wer sie auslässt, kann als ungesellig gelten. Die Pause ist bewusst unhetzt und wird geschätzt, um Hierarchien abzubauen: Gespräche reichen von Arbeit bis Privatleben und überschreiten Abteilungsgrenzen."]},{"heading":"Tradition im Wandel","paragraphs":["Institutionalisierte Fika ist am stärksten in Büros, Schulen und Behörden und wurde durch Schichtarbeit, kleine Unternehmen und Homeoffice zurückgedrängt. Nicht jeder Schwede macht zweimal täglich Fika, und das Ritual variiert je nach Arbeitsplatz; für Neue kann es verpflichtend wirken, während es bei Remote- und Schichtarbeit oft ganz fehlt."]}],"en":[{"heading":"A Daily Workplace Ritual","paragraphs":["Fika is the Swedish term for the coffee break, a social institution usually taken twice a day at fairly fixed times. It involves coffee and something small to eat, often a cinnamon bun (kanelbulle). The word is a reversed-syllable slang form of kaffe (coffee) and works as both noun and verb: att fika, vi fikar.","At many workplaces fika is scheduled in the morning and afternoon, managers are expected to attend, and skipping it can mark a colleague as unsociable. The break is deliberately unhurried and valued as a way to flatten hierarchy: conversation ranges over work and private life and crosses departmental boundaries."]},{"heading":"A Tradition Under Change","paragraphs":["Institutionalised fika is strongest in offices, schools and public bodies, and has been eroded by shift work, small businesses and remote work. Not every Swede takes fika twice a day, and the ritual varies between workplaces; for newcomers it can feel compulsory, while remote and shift workers often miss it entirely."]}]},"context":{"countries":["SE"],"region":"Stockholm","continent":"europe","languages":["sv"],"period":"contemporary"},"tags":["work-and-education","Stockholm"],"sources":[{"organization":"Wikipedia","title":{"ar":"Coffee in Sweden","de":"Coffee in Sweden","en":"Coffee in Sweden"},"url":"https://en.wikipedia.org/wiki/Coffee_in_Sweden","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Coffee culture","de":"Coffee culture","en":"Coffee culture"},"url":"https://en.wikipedia.org/wiki/Coffee_culture","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في الساعة 15:00 في مكتب بستوكهولم، يهدأ المطبخ بينما يتجمع الفريق حول طبق من كعك الهيل، وينتظر الاجتماع حول المنتج الجديد حتى تنتهي القهوة.","de":"Um 15 Uhr wird es in der Teeküche eines Stockholmer Büros still, als das Team sich um einen Teller Kardamombrötchen versammelt, und das Meeting zum neuen Produkt wartet, bis der Kaffee ausgetrunken ist.","en":"At 15:00 on a Stockholm office floor the kitchen goes quiet as the team gathers around a plate of cardamom buns, and the meeting about the new product waits until the coffee is finished."},"misunderstanding":{"ar":"قد يُفهم أن الفيكا مجرد استراحة قهوة عابرة، لكنها في الواقع مناسبة اجتماعية منظمة تعزز العلاقات وتقلل الحواجز الهرمية.","de":"Fika wird oft als bloße Kaffeepause missverstanden, ist aber ein fest institutionalisiertes soziales Ereignis, das Beziehungen stärkt und Hierarchien abbaut.","en":"Fika is often mistaken for a quick coffee break, but it is a structured social event that builds relationships and reduces hierarchical barriers."},"comparison":{"ar":"على عكس استراحات القهوة السريعة في بعض الثقافات، تتميز الفيكا بطابعها المتأني والمحدد بمواعيد ثابتة، مما يجعلها جزءًا من بنية يوم العمل.","de":"Anders als schnelle Kaffeepausen in manchen Kulturen ist Fika bewusst entschleunigt und an feste Zeiten gebunden, was sie zu einem festen Bestandteil des Arbeitstages macht.","en":"Unlike quick coffee breaks in some cultures, fika is deliberately unhurried and tied to fixed times, making it a core part of the workday structure."}},{"id":"wrk-016","version":2,"slug":"silesian-speech-and-the-politics-of-regional-identity","contentType":"language","category":"languages","title":{"ar":"اللغة السيليزية وسياسة الهوية الإقليمية","de":"Schlesische Sprache und regionale Identität","en":"Silesian speech and regional identity politics"},"deck":{"ar":"اللغة السيليزية (ślōnskŏ gōdka) هي لغة سلافية غربية تُستخدم في سيليزيا العليا، ويُعترف بها برمز ISO 639-3 خاص بها، szl، منذ عام 2007.","de":"Schlesisch (ślōnskŏ gōdka) ist eine westslawische Sprachvarietät, die in Oberschlesien gesprochen wird und seit 2007 einen eigenen ISO 639-3-Code, szl, besitzt.","en":"Silesian (ślōnskŏ gōdka) is a West Slavic speech variety used in Upper Silesia and recognised with its own ISO 639-3 code, szl, since 2007."},"teaser":{"ar":"في سيليزيا العليا، يتحدث نصف مليون شخص باللغة السيليزية في المنزل، مما يجعلها جزءًا حيًا من الهوية الإقليمية.","de":"In Oberschlesien sprechen etwa 500.000 Menschen Schlesisch zu Hause – eine lebendige Sprache mit eigener Identität.","en":"In Upper Silesia, about 500,000 people speak Silesian at home, keeping a regional identity alive through language and culture."},"readingMinutes":1,"sections":{"ar":[{"heading":"لغة وهوية","paragraphs":["اللغة السيليزية (ślōnskŏ gōdka، وتُعرف أيضًا باسم gwara śląska) هي لغة سلافية غربية تُستخدم في سيليزيا العليا، ويُعترف بها برمز ISO 639-3 خاص بها، szl، منذ عام 2007.","في تعداد عام 2011، أعلن حوالي 500,000 شخص أن السيليزية هي اللغة التي يتحدثونها في المنزل، وأعلن حوالي 817,000 شخص أنهم من القومية السيليزية، وهي أكبر هوية أقلية في بولندا."]},{"heading":"حياة يومية وتراث","paragraphs":["تظهر اللغة في وسائل الإعلام المحلية والمسرح وبعض المدارس كمادة إضافية، لكنها لا تتمتع بوضع رسمي، ويختلف هجاؤها بين الكتاب والمنظمات.","تتضمن الثقافة الشعبية السيليزية الفرق النحاسية والكباريه اللهجي، كما تُعد الطعام والمهرجانات الإقليمية جزءًا من الهوية.","يختلف استخدام اللغة بين الأجيال والمناطق: فهي أقوى في البلدات الصناعية القديمة منها بين القادمين الجدد."]}],"de":[{"heading":"Sprache und Identität","paragraphs":["Schlesisch (ślōnskŏ gōdka, auch gwara śląska genannt) ist eine westslawische Sprachvarietät, die in Oberschlesien verwendet wird und seit 2007 mit dem ISO 639-3-Code szl anerkannt ist.","Bei der Volkszählung 2011 gaben rund 500.000 Menschen an, Schlesisch als Sprache im Haushalt zu sprechen, und etwa 817.000 erklärten sich zur schlesischen Nationalität, der größten Minderheitenidentität in Polen."]},{"heading":"Alltag und Brauchtum","paragraphs":["Die Sprache erscheint in lokalen Medien, im Theater und in einigen Schulen als zusätzliches Fach, hat aber keinen offiziellen Status, und ihre Rechtschreibung variiert zwischen Autoren und Organisationen.","Zur schlesischen Volkskultur gehören Blaskapellen und Dialektkabarett; regionale Küche und Feste sind Teil der Identität.","Die Nutzung variiert regional und generationell: In alten Industrieorten ist die Sprache stärker verankert als bei Neuzugezogenen."]}],"en":[{"heading":"Language and identity","paragraphs":["Silesian (ślōnskŏ gōdka, also called gwara śląska) is a West Slavic speech variety used in Upper Silesia and recognised with its own ISO 639-3 code, szl, since 2007.","In the 2011 census about 500,000 people declared Silesian as the language spoken at home, and some 817,000 declared Silesian nationality, the largest minority identity in Poland."]},{"heading":"Everyday life and heritage","paragraphs":["The language appears in local media, theatre and some schools as an extra subject, but it has no official status and its spelling varies between writers and organisations.","Silesian folk culture includes brass bands and dialect cabaret, and regional food and festivals are part of the identity.","Use varies by region and generation: the language is stronger in old industrial towns than among newcomers."]}]},"context":{"countries":["PL"],"region":"Upper Silesia","continent":"europe","languages":["pl"],"period":"contemporary"},"tags":["languages","Upper Silesia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Silesian language","de":"Silesian language","en":"Silesian language"},"url":"https://en.wikipedia.org/wiki/Silesian_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Silesians","de":"Silesians","en":"Silesians"},"url":"https://en.wikipedia.org/wiki/Silesians","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تتحول أسرة في كاتوفيتسه من البولندية القياسية إلى السيليزية على طاولة المطبخ، وتكون كلمات الجدة اللهجية للأدوات والطعام مصدرًا للنكات والفخر معًا.","de":"Eine Familie in Katowice wechselt am Küchentisch vom Standardpolnischen ins Schlesische, und die Dialektwörter der Großmutter für Werkzeuge und Essen sind sowohl Anlass für Witze als auch für Stolz.","en":"A family in Katowice switches from standard Polish to Silesian at the kitchen table, and the grandmother's dialect words for tools and food are a source of both jokes and pride."},"misunderstanding":{"ar":"ليس كل من سيليزيا يعرّف نفسه كسيليزي، واللغة أقوى في البلدات الصناعية القديمة منها بين القادمين الجدد، وتختلف إجابات التعداد حسب صيغة السؤال ومن يقوم بالعد.","de":"Nicht jeder aus Schlesien identifiziert sich als Schlesier, die Sprache ist in alten Industrieorten stärker als bei Neuzugezogenen, und die Antworten bei Volkszählungen hängen davon ab, wie die Frage formuliert ist und wer zählt.","en":"Not everyone from Silesia identifies as Silesian, the language is stronger in old industrial towns than among newcomers, and census answers vary with how the question is worded and who is counting."},"comparison":{"ar":"على عكس اللغات الإقليمية المعترف بها رسميًا في بولندا، تفتقر السيليزية إلى وضع رسمي، لكنها تحتفظ بحضور قوي في المنزل والثقافة الشعبية.","de":"Anders als offiziell anerkannte Regionalsprachen in Polen hat Schlesisch keinen offiziellen Status, bleibt aber im Haushalt und in der Volkskultur stark präsent.","en":"Unlike officially recognised regional languages in Poland, Silesian lacks official status but remains strong in homes and folk culture."},"expression":{"original":"Szczynść Boże","language":"Silesian (ślōnskŏ gōdka)","gloss":{"ar":"بارك الله — تحية سيليزية تقليدية تُستخدم عند لقاء شخص ما","de":"Gott segne – ein traditioneller schlesischer Gruß zur Begrüßung","en":"God bless — a traditional Silesian greeting used when meeting someone"},"usage":{"ar":"تُستخدم عند اللقاء، خاصة بين كبار السن في المناطق الريفية والحضرية.","de":"Wird bei Begegnungen verwendet, besonders unter älteren Menschen in ländlichen und städtischen Gebieten.","en":"Used when meeting someone, especially among older people in rural and urban areas."},"transliteration":"szczynść Boże"}},{"id":"wrk-017","version":2,"slug":"e-estonia-and-the-once-only-digital-state","contentType":"note","category":"cultural-change","title":{"ar":"إستونيا الرقمية: دولة تسأل مرة واحدة","de":"E-Estland: Der Staat fragt nur einmal","en":"E-Estonia: The State Asks Once"},"deck":{"ar":"من تبادل البيانات إلى التصويت الإلكتروني، كيف يعيش الإستونيون حياة يومية تعتمد على الهوية الرقمية والخدمات الحكومية السلسة.","de":"Vom Datenaustausch bis zur Online-Wahl: Wie Esten im Alltag mit digitaler Identität und nahtlosen Behördengängen leben.","en":"From data exchange to online voting, how Estonians live daily with digital identity and seamless public services."},"teaser":{"ar":"في إستونيا، الدولة لا تطلب بيانات تملكها بالفعل، والمواطن يرى من اطّلع على ملفه. كيف يغيّر ذلك الحياة اليومية؟","de":"In Estland fragt der Staat keine Daten ab, die er schon hat, und Bürger sehen, wer ihre Akten geöffnet hat. Was ändert das im Alltag?","en":"In Estonia, the state cannot ask for data it already holds, and citizens see who opened their records. How does that change everyday life?"},"readingMinutes":1,"sections":{"ar":[{"heading":"حياة يومية بلمسة رقمية","paragraphs":["منذ عام 2001، بنت إستونيا دولة رقمية على طبقة تبادل بيانات تُعرف باسم X-Road، ثم أطلقت بطاقة هوية إلكترونية في 2002 تحمل توقيعات رقمية تُستخدم في الإدارة اليومية. يوقّع الناس عقودهم، ويتحققون من وثائقهم، ويتفاعلون مع الدولة عبر الهوية الرقمية.","تتبع الخدمات العامة مبدأ 'المرة الواحدة': لا يجوز للدولة أن تطلب بيانات تملكها بالفعل، ويمكن للمواطنين رؤية أي مسؤول اطّلع على سجلاتهم. هذا المبدأ يقلل التكرار ويجعل التعامل مع الإدارة أسرع وأكثر شفافية."]},{"heading":"تصويت وضرائب من الشاشة","paragraphs":["كانت إستونيا أول دولة تجري انتخابات وطنية عبر التصويت الإلكتروني في 2005، واليوم تُقدَّم الغالبية العظمى من الإقرارات الضريبية إلكترونيًا. كما تمنح الإقامة الإلكترونية منذ 2014 الأجانب هوية رقمية للوصول إلى تسجيل الشركات والخدمات المصرفية دون العيش في البلاد.","مع ذلك، ليس النظام شاملًا للجميع: كبار السن وسكان الريف يستخدمون الخدمات الرقمية أقل، ولا تزال الخيارات الورقية والحضورية متاحة. ويختلف الاستخدام أيضًا بين الأجيال والمناطق، حيث يتبنى سكان المدن الشباب الخدمات الرقمية بسرعة أكبر."]}],"de":[{"heading":"Alltag mit digitalem Ausweis","paragraphs":["Seit 2001 baute Estland einen digitalen Staat auf der Datenaustauschschicht X-Road auf und führte 2002 eine elektronische ID-Karte ein, die digitale Signaturen für die tägliche Verwaltung trägt. Menschen unterschreiben Verträge, prüfen Dokumente und interagieren über ihre digitale Identität mit dem Staat.","Öffentliche Dienste folgen dem 'Once-Only'-Prinzip: Der Staat darf keine Daten verlangen, die er bereits hat, und Bürger können einsehen, welche Beamten ihre Akten geöffnet haben. Das reduziert Doppelarbeit und macht Verwaltung schneller und transparenter."]},{"heading":"Wählen und Steuern per Bildschirm","paragraphs":["Estland war 2005 das erste Land, das nationale Wahlen online abhielt, und heute wird die große Mehrheit der Steuererklärungen elektronisch eingereicht. Seit 2014 gibt die E-Residency Ausländern eine digitale Identität für Firmenregistrierung und Bankdienste, ohne im Land zu leben.","Dennoch ist das System nicht universell: Ältere und ländliche Bewohner nutzen digitale Dienste weniger, und Papier- sowie Präsenzoptionen bleiben verfügbar. Auch zwischen Generationen und Regionen variiert die Nutzung, wobei junge Stadtbewohner digitale Dienste schneller annehmen."]}],"en":[{"heading":"Daily life with a digital ID","paragraphs":["Since 2001, Estonia has built a digital state on the X-Road data-exchange layer, and in 2002 introduced an electronic ID card carrying digital signatures used in daily administration. People sign contracts, verify documents and interact with the state through their digital identity.","Public services follow a 'once-only' principle: the state may not ask for data it already holds, and citizens can see which officials have accessed their records. This reduces duplication and makes dealing with administration faster and more transparent."]},{"heading":"Voting and taxes from a screen","paragraphs":["Estonia was the first country to hold national elections with online voting in 2005, and today the great majority of tax returns are filed electronically. Since 2014, E-Residency gives foreigners a digital identity for company registration and banking without living in the country.","Yet the system is not universal: older and rural residents use digital services less, and paper and in-person options remain available. Usage also varies between generations and regions, with younger city residents adopting digital services more quickly."]}]},"context":{"countries":["EE"],"region":"Tallinn","continent":"europe","languages":["et"],"period":"contemporary"},"tags":["cultural-change","Tallinn"],"sources":[{"organization":"Wikipedia","title":{"ar":"E-Estonia","de":"E-Estonia","en":"E-Estonia"},"url":"https://en.wikipedia.org/wiki/E-Estonia","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"E-Residency of Estonia","de":"E-Residency of Estonia","en":"E-Residency of Estonia"},"url":"https://en.wikipedia.org/wiki/E-Residency_of_Estonia","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"مستقلة في تارتو تقدم إقرارها الضريبي السنوي في دقائق، وتوقّع عقدًا بهويتها الإلكترونية، وتتحقق من السجل لترى أي مسؤول فتح ملفها.","de":"Eine Freiberuflerin in Tartu reicht ihre jährliche Steuererklärung in wenigen Minuten ein, unterzeichnet einen Vertrag mit ihrer elektronischen ID und prüft das Protokoll, um zu sehen, welche Beamten ihre Akte geöffnet haben.","en":"A freelancer in Tartu files her annual tax return in a few minutes, signs a contract with her electronic ID and checks the log to see which officials opened her file."},"misunderstanding":{"ar":"الاعتقاد الشائع أن إستونيا دولة بلا ورق تمامًا، لكن الواقع أن الخيارات الورقية والحضورية باقية، وأن النظام الرقمي ليس شاملًا للجميع.","de":"Der verbreitete Irrtum, Estland sei völlig papierlos, doch Papier- und Präsenzoptionen bleiben bestehen, und das digitale System ist nicht für alle umfassend.","en":"A common misconception is that Estonia is entirely paperless, but paper and in-person options remain, and the digital system is not comprehensive for everyone."},"comparison":{"ar":"بينما تطلب دول أخرى البيانات نفسها مرارًا، تعتمد إستونيا مبدأ 'المرة الواحدة' وتتيح للمواطن تتبع من اطّلع على بياناته.","de":"Während andere Länder dieselben Daten mehrfach abfragen, setzt Estland auf das Once-Only-Prinzip und lässt Bürger nachverfolgen, wer ihre Daten eingesehen hat.","en":"While other countries ask for the same data repeatedly, Estonia relies on the once-only principle and lets citizens track who has viewed their data."}},{"id":"wrk-018","version":2,"slug":"blat-and-the-soviet-economy-of-favours","contentType":"note","category":"work-and-education","title":{"ar":"بلات: شبكات المصالح في الاقتصاد السوفييتي","de":"Blat: Das sowjetische Netzwerk der Gefälligkeiten","en":"Blat: The Soviet Economy of Favours"},"deck":{"ar":"كيف اعتمد الناس في موسكو على العلاقات الشخصية للحصول على السلع والخدمات النادرة، وكيف استمرت هذه الممارسة بعد انهيار الاتحاد السوفييتي.","de":"Wie Menschen in Moskau über persönliche Beziehungen an knappe Güter und Dienstleistungen gelangten und wie diese Praxis den Zusammenbruch der Sowjetunion überlebte.","en":"How people in Moscow relied on personal networks to obtain scarce goods and services, and how the practice persisted after the Soviet Union collapsed."},"teaser":{"ar":"في اقتصاد الندرة، لم تكن الطوابير الرسمية كافية. بلات، أو 'الواسطة'، جعلت العلاقات الشخصية عملة حقيقية.","de":"In der Mangelwirtschaft reichten offizielle Schlangen nicht aus. Blat – „durch Beziehungen“ – machte persönliche Netzwerke zur eigentlichen Währung.","en":"In a shortage economy, official queues were not enough. Blat — getting things “through connections” — turned personal relationships into a parallel currency."},"readingMinutes":1,"sections":{"ar":[{"heading":"آلية الندرة والتبادل","paragraphs":["بلات هو ممارسة سوفييتية للحصول على السلع والخدمات عبر شبكات شخصية غير رسمية وخدمات متبادلة، بدلاً من الطوابير أو الخطط الرسمية. ازدهر في اقتصاد الندرة، حيث كان الوصول إلى السلع النادرة وقطع الغيار والسكن وأماكن الجامعة والرعاية الطبية يعتمد على من تعرفه.","يعمل بلات من خلال الالتزام المتبادل: الخدمة تخلق ديناً يجب سداده لاحقاً، وغالباً بعملة مختلفة من السلع أو الخدمات. ويميز الباحثون بين بلات والرشوة: قد يكون المال متورطاً، لكن الآلية الأساسية هي الالتزام المتبادل والثقة والعلاقات المستمرة."]},{"heading":"الاستمرارية بعد 1991","paragraphs":["استمرت الممارسة بعد عام 1991 واندمجت في حياة الأعمال ما بعد السوفييتية، حيث لا تزال العلاقات الشخصية مهمة للعقود والتصاريح والتوظيف. يختلف انتشار بلات بين الأجيال والمناطق: فالأصغر سناً في المدن الكبرى يعتمدون على الأسواق الرسمية أكثر، بينما تظل الشبكات الشخصية قوية في الأوساط البيروقراطية والطبية والمهنية."]}],"de":[{"heading":"Mangel und Gegenseitigkeit","paragraphs":["Blat ist eine sowjetische Praxis, Güter und Dienstleistungen über informelle persönliche Netzwerke und gegenseitige Gefälligkeiten zu beschaffen – po blatu, „über Beziehungen“, statt über offizielle Schlangen oder Pläne. Sie blühte in der Mangelwirtschaft: Zugang zu knappen Gütern, Ersatzteilen, Wohnungen, Studienplätzen und medizinischer Versorgung hing davon ab, wen man kannte.","Blat funktioniert durch gegenseitige Verpflichtung: Ein Gefallen schafft eine Schuld, die später zurückgezahlt wird, oft in einer anderen Währung aus Gütern oder Dienstleistungen. Forscher unterscheiden Blat von Bestechung: Geld kann eine Rolle spielen, aber der Kernmechanismus ist reziproke Verpflichtung, Vertrauen und fortbestehende Beziehungen."]},{"heading":"Fortbestand nach 1991","paragraphs":["Die Praxis bestand nach 1991 fort und verschmolz mit dem postsowjetischen Geschäftsleben, wo persönliche Kontakte noch immer für Verträge, Genehmigungen und Personalbeschaffung wichtig sind. Regional und generationell gibt es Unterschiede: Jüngere in Großstädten nutzen häufiger formelle Märkte, während persönliche Netzwerke in bürokratischen, medizinischen und freiberuflichen Kreisen stark bleiben."]}],"en":[{"heading":"Shortage and Reciprocal Obligation","paragraphs":["Blat is the Soviet-era practice of obtaining goods and services through informal personal networks and mutual favours (po blatu, “through connections”) rather than through official queues or plans. It thrived in the shortage economy: access to scarce goods, spare parts, housing, university places and medical care depended on who one knew.","Blat works through mutual obligation: a favour creates a debt to be returned later, often in a different currency of goods or services. Scholars distinguish blat from bribery: money may be involved, but the core mechanism is reciprocal obligation, trust and ongoing relationships."]},{"heading":"Survival After 1991","paragraphs":["The practice persisted after 1991 and merged into post-Soviet business life, where personal connections still matter for contracts, permits and recruitment. There is regional and generational variation: younger city dwellers rely more on formal markets, while personal networks remain strong in bureaucratic, medical and professional settings."]}]},"context":{"countries":["RU"],"region":"Moscow","continent":"europe","languages":["ru"],"period":"contemporary"},"tags":["work-and-education","Moscow"],"sources":[{"organization":"Wikipedia","title":{"ar":"Blat (favors)","de":"Blat (favors)","en":"Blat (favors)"},"url":"https://en.wikipedia.org/wiki/Blat_(favors)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Second economy of the Soviet Union","de":"Second economy of the Soviet Union","en":"Second economy of the Soviet Union"},"url":"https://en.wikipedia.org/wiki/Second_economy_of_the_Soviet_Union","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"مدير مصنع في نيجني نوفغورود يحصل على قطع غيار ليس من المورد الرسمي بل عبر صديق في مصنع آخر، ويسدد الخدمة بعد أشهر بمساعدة الصديق في الحصول على مكان لقضاء العطلة.","de":"Ein Fabrikmanager in Nischni Nowgorod bezieht Ersatzteile nicht vom offiziellen Lieferanten, sondern über einen Freund in einem anderen Werk, und revanchiert sich Monate später, indem er dem Freund zu einem Urlaubsplatz verhilft.","en":"A factory manager in Nizhny Novgorod gets spare parts not from the official supplier but through a friend at another plant, and repays the favour months later by helping that friend obtain a holiday place."},"misunderstanding":{"ar":"بلات ليس حكراً على روسيا، وقد ضعف مع وفرة السلع وتشكل الأسواق، لكنه يبقى حيث يعتمد الوصول على الأشخاص لا على الأسعار.","de":"Blat ist nicht spezifisch russisch und hat mit der Fülle an Gütern und formalisierten Märkten an Bedeutung verloren; es überlebt vor allem dort, wo Zugang von Personen statt Preisen abhängt.","en":"Blat is not uniquely Russian and has weakened as goods became abundant and markets formalised; it survives most where access still depends on people rather than prices."},"comparison":{"ar":"يشبه بلات مفهوم 'الواسطة' في المجتمعات العربية، حيث تحل العلاقات الشخصية محل الإجراءات الرسمية في تيسير الأمور.","de":"Ähnlich wie „Vitamin B“ in Deutschland bezeichnet Blat ein System, in dem Beziehungen formale Wege ersetzen oder ergänzen.","en":"Blat resembles the German notion of “Vitamin B” — relationships that substitute for or supplement formal channels."}}];

